## File 2: `middleware/errorHandler.js`

```javascript
/**
 * errorHandler.js — Custom error classes and Express error-handling middleware.
 *
 * WHY custom error classes?
 *   Built-in JavaScript Error objects don't carry HTTP status codes or
 *   structured message fields. By creating subclasses (NotFoundError,
 *   ValidationError, AppError), we can catch them in a single middleware
 *   function and return consistent JSON responses like:
 *     { "error": "Not Found", "message": "...", "status": 404 }
 *
 * WHY an Express error-handling middleware?
 *   Express has a special signature for error middleware: (err, req, res, next).
 *   Any route that calls next(err) will be caught here. This centralizes
 *   error formatting so every endpoint doesn't need its own try/catch block.
 */

// ─── Custom Error Classes ────────────────────────────────────────────────────

/**
 * AppError — Base class for all application-level errors.
 *
 * Extends the built-in Error class and adds:
 *   - statusCode: HTTP status code (default 500)
 *   - isOperational: whether this error was caused by bad input vs a bug
 */
class AppError extends Error {
  /**
   * @param {string} message — Human-readable description of the error.
   * @param {number} statusCode — HTTP status code (default 500).
   */
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true; // marks it as an expected, non-bug error
  }
}

/**
 * NotFoundError — Thrown when a requested resource doesn't exist.
 * Maps to HTTP 404 (Not Found).
 */
class NotFoundError extends AppError {
  constructor(resource) {
    super(`${resource} not found`, 404);
  }
}

/**
 * ValidationError — Thrown when client input fails validation.
 * Maps to HTTP 400 (Bad Request).
 */
class ValidationError extends AppError {
  constructor(message) {
    super(message, 400);
  }
}

// ─── Error-Handling Middleware ────────────────────────────────────────────────

/**
 * errorHandler — Express middleware that catches all errors and formats them.
 *
 * Placement matters: this MUST be registered AFTER all routes so it can
 * intercept errors thrown by any route handler.
 *
 * @param {Error} err — The error object (our custom classes or native Error).
 * @param {import('express').Request} req — Express request object.
 * @param {import('express').Response} res — Express response object.
 * @param {import('express').NextFunction} next — Express next middleware function.
 */
function errorHandler(err, req, res, next) {
  // If the error is one of our custom classes, use its statusCode and message.
  // Otherwise fall back to a generic 500 response (unexpected server bug).
  const statusCode = err.statusCode || 500;
  const message = err.message || 'Internal Server Error';

  // Log the full error stack in development for easier debugging.
  if (process.env.NODE_ENV !== 'production') {
    console.error('[ERROR]', err.stack);
  }

  // Return a consistent JSON error shape regardless of which route failed.
  res.status(statusCode).json({
    error: message,
    statusCode,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
  });
}

// ─── Export Classes and Middleware ─────────────────────────────────────────────

module.exports = { AppError, NotFoundError, ValidationError, errorHandler };
```

> **Key takeaway:** The `errorHandler` middleware uses the four-argument signature `(err, req, res, next)`. Express recognizes this and treats it specially — it won't be called for normal requests, only when `next(err)` is invoked. This keeps our route handlers clean; they just call `next(new NotFoundError('Book'))` instead of manually setting status codes everywhere.

