## File 3: `routes/books.js`

```javascript
/**
 * routes/books.js — CRUD routes for the /books resource.
 *
 * WHY separate route file?
 *   Keeping routes in their own module makes server.js lean and lets us
 *   test each resource independently. Express's Router() gives us a
 *   mini-application scoped to /books, so we don't repeat the prefix.
 *
 * WHY async/await even with in-memory data?
 *   This demonstrates the pattern you'd use with a real database (MongoDB,
 *   PostgreSQL, etc.). When we swap the array for an ORM later, only this
 *   file changes — the routes and server stay identical.
 */

const express = require('express');
const { NotFoundError, ValidationError } = require('../middleware/errorHandler');

// ─── In-Memory Data Store ─────────────────────────────────────────────────────

/**
 * books — Array that holds all book objects in memory.
 *
 * WHY an array?
 *   For a small educational example, an array is simple and fast (O(1) by index).
 *   In production you'd use a database because:
 *     - Arrays don't persist across server restarts.
 *     - Searching an array is O(n); databases use indexes for O(log n).
 *     - No concurrency control — two requests could overwrite each other.
 *
 * Each book object shape:
 *   {
 *     id: number,          // unique identifier (auto-incremented)
 *     title: string,       // book title
 *     author: string,      // primary author name
 *     isbn: string,        // 10 or 13 digit ISBN
 *     publishedYear: number, // year the book was published
 *     genre: string,       // e.g., "Fiction", "Science"
 *     createdAt: ISOString, // when the record was created
 *     updatedAt: ISOString  // when the record was last updated
 *   }
 */
let books = [
  {
    id: 1,
    title: 'To Kill a Mockingbird',
    author: 'Harper Lee',
    isbn: '9780061120084',
    publishedYear: 1960,
    genre: 'Fiction',
    createdAt: new Date('2024-01-01T00:00:00Z').toISOString(),
    updatedAt: new Date('2024-01-01T00:00:00Z').toISOString(),
  },
  {
    id: 2,
    title: 'A Brief History of Time',
    author: 'Stephen Hawking',
    isbn: '9780553380163',
    publishedYear: 1988,
    genre: 'Science',
    createdAt: new Date('2024-01-02T00:00:00Z').toISOString(),
    updatedAt: new Date('2024-01-02T00:00:00Z').toISOString(),
  },
];

/** Next auto-incremented ID. Starts at 3 so it doesn't collide with existing data. */
let nextId = 3;

// ─── Router Setup ─────────────────────────────────────────────────────────────

const router = express.Router();

// ─── GET /books — List All Books (with optional filtering) ────────────────────

/**
 * GET /books
 *
 * Returns a JSON array of all books. Supports optional query parameters for
 * filtering:
 *   - genre    : exact match, e.g. ?genre=Fiction
 *   - author   : case-insensitive substring match, e.g. ?author=hawking
 *   - yearFrom : minimum published year (inclusive), e.g. ?yearFrom=1970
 *   - yearTo   : maximum published year (inclusive), e.g. ?yearTo=2000
 *
 * @example curl http://localhost:3000/books
 * @example curl "http://localhost:3000/books?genre=Fiction&yearFrom=1950"
 */
router.get('/', async function listBooks(req, res, next) {
  try {
    // Destructure query parameters with defaults so we don't need null checks later.
    const { genre, author, yearFrom, yearTo } = req.query;

    /**
     * Filter the in-memory array based on whichever query params were provided.
     * We use Array.prototype.filter() which returns a new array — this is
     * non-destructive and safe for concurrent requests.
     */
    let result = books;

    if (genre) {
      // Exact, case-insensitive match on genre.
      result = result.filter((book) => book.genre.toLowerCase() === genre.toLowerCase());
    }

    if (author) {
      // Substring match, case-insensitive — more forgiving than exact match.
      const authorLower = author.toLowerCase();
      result = result.filter((book) => book.author.toLowerCase().includes(authorLower));
    }

    if (yearFrom) {
      const from = parseInt(yearFrom, 10);
      if (!isNaN(from)) {
        result = result.filter((book) => book.publishedYear >= from);
      }
    }

    if (yearTo) {
      const to = parseInt(yearTo, 10);
      if (!isNaN(to)) {
        result = result.filter((book) => book.publishedYear <= to);
      }
    }

    // Return the filtered list with a 200 OK status.
    res.json({
      count: result.length,
      data: result,
    });
  } catch (err) {
    next(err); // pass any unexpected error to our global error handler
  }
});

// ─── GET /books/:id — Get a Single Book ───────────────────────────────────────

/**
 * GET /books/:id
 *
 * Returns the book whose id matches the URL parameter, or 404 if not found.
 *
 * @param {number} id — The numeric ID from req.params.id.
 *
 * @example curl http://localhost:3000/books/1
 */
router.get('/:id', async function getBook(req, res, next) {
  try {
    const id = parseInt(req.params.id, 10);

    // Validate that the ID is a real number.
    if (isNaN(id)) {
      throw new ValidationError('Invalid book ID: must be a number');
    }

    /**
     * Array.prototype.find() returns the first element that satisfies the
     * predicate, or undefined if none match. This is O(n) but fine for
     * small datasets. For large datasets you'd use a Map keyed by id.
     */
    const book = books.find((b) => b.id === id);

    if (!book) {
      // Throw our custom NotFoundError so the error handler formats it nicely.
      throw new NotFoundError('Book');
    }

    res.json(book);
  } catch (err) {
    next(err);
  }
});

// ─── POST /books — Create a New Book ──────────────────────────────────────────

/**
 * POST /books
 *
 * Creates a new book from the JSON body and returns it with status 201.
 *
 * Required fields in the request body:
 *   - title      (string, non-empty)
 *   - author     (string, non-empty)
 *   - isbn       (string, non-empty)
 *   - publishedYear (number, between 0 and current year + 1)
 *   - genre      (string, non-empty)
 *
 * @example curl -X POST http://localhost:3000/books \
 *           -H "Content-Type: application/json" \
 *           -d '{"title":"1984","author":"George Orwell","isbn":"9780451524935",
 *                  "publishedYear":1949,"genre":"Dystopian"}'
 */
router.post('/', async function createBook(req, res, next) {
  try {
    const { title, author, isbn, publishedYear, genre } = req.body;

    // ── Validation ───────────────────────────────────────────────────────────
    if (!title || typeof title !== 'string' || title.trim() === '') {
      throw new ValidationError('Title is required and must be a non-empty string');
    }
    if (!author || typeof author !== 'string' || author.trim() === '') {
      throw new ValidationError('Author is required and must be a non-empty string');
    }
    if (!isbn || typeof isbn !== 'string' || isbn.trim() === '') {
      throw new ValidationError('ISBN is required and must be a non-empty string');
    }
    if (
      publishedYear === undefined ||
      publishedYear === null ||
      !Number.isInteger(publishedYear) ||
      publishedYear < 0 ||
      publishedYear > new Date().getFullYear() + 1
    ) {
      throw new ValidationError(
        'publishedYear is required and must be a valid integer between 0 and the current year'
      );
    }
    if (!genre || typeof genre !== 'string' || genre.trim() === '') {
      throw new ValidationError('Genre is required and must be a non-empty string');
    }

    // ── Build the new book object ────────────────────────────────────────────
    const now = new Date().toISOString();

    const newBook = {
      id: nextId++, // auto-increment; in production use a DB sequence or UUID
      title: title.trim(),
      author: author.trim(),
      isbn: isbn.trim(),
      publishedYear,
      genre: genre.trim(),
      createdAt: now,
      updatedAt: now,
    };

    /**
     * Push the new book onto our in-memory array.
     * In a real app you'd await db.books.insertOne(newBook) here.
     */
    books.push(newBook);

    // 201 Created is the standard status for successful resource creation.
    res.status(201).json(newBook);
  } catch (err) {
    next(err);
  }
});

// ─── PUT /books/:id — Full Update an Existing Book ────────────────────────────

/**
 * PUT /books/:id
 *
 * Replaces the entire book record with the provided JSON body.
 * Returns the updated book, or 404 if not found.
 *
 * NOTE: This is a FULL update (not PATCH). All fields must be present.
 *
 * @example curl -X PUT http://localhost:3000/books/1 \
 *           -H "Content-Type: application/json" \
 *           -d '{"title":"To Kill a Mockingbird","author":"Harper Lee",
 *                  "isbn":"9780061120084","publishedYear":1960,"genre":"Fiction"}'
 */
router.put('/:id', async function updateBook(req, res, next) {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new ValidationError('Invalid book ID: must be a number');
    }

    // Find the index so we can both check existence and mutate in place.
    const index = books.findIndex((b) => b.id === id);

    if (index === -1) {
      throw new NotFoundError('Book');
    }

    const { title, author, isbn, publishedYear, genre } = req.body;

    // Reuse the same validation logic as POST.
    if (!title || typeof title !== 'string' || title.trim() === '') {
      throw new ValidationError('Title is required and must be a non-empty string');
    }
    if (!author || typeof author !== 'string' || author.trim() === '') {
      throw new ValidationError('Author is required and must be a non-empty string');
    }
    if (!isbn || typeof isbn !== 'string' || isbn.trim() === '') {
      throw new ValidationError('ISBN is required and must be a non-empty string');
    }
    if (
      publishedYear === undefined ||
      publishedYear === null ||
      !Number.isInteger(publishedYear) ||
      publishedYear < 0 ||
      publishedYear > new Date().getFullYear() + 1
    ) {
      throw new ValidationError(
        'publishedYear is required and must be a valid integer between 0 and the current year'
      );
    }
    if (!genre || typeof genre !== 'string' || genre.trim() === '') {
      throw new ValidationError('Genre is required and must be a non-empty string');
    }

    const now = new Date().toISOString();

    /**
     * Replace the entire object at the found index.
     * For a PATCH (partial update) you'd only overwrite the fields present
     * in req.body instead of replacing the whole record.
     */
    books[index] = {
      id, // preserve the original ID — we don't allow ID changes on update
      title: title.trim(),
      author: author.trim(),
      isbn: isbn.trim(),
      publishedYear,
      genre: genre.trim(),
      createdAt: books[index].createdAt, // preserve creation timestamp
      updatedAt: now,
    };

    res.json(books[index]);
  } catch (err) {
    next(err);
  }
});

// ─── DELETE /books/:id — Delete a Book ────────────────────────────────────────

/**
 * DELETE /books/:id
 *
 * Removes the book with the matching ID and returns 204 No Content.
 * Returns 404 if the book doesn't exist.
 *
 * @example curl -X DELETE http://localhost:3000/books/1
 */
router.delete('/:id', async function deleteBook(req, res, next) {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new ValidationError('Invalid book ID: must be a number');
    }

    const index = books.findIndex((b) => b.id === id);

    if (index === -1) {
      throw new NotFoundError('Book');
    }

    /**
     * Array.prototype.splice removes the element in-place and returns an array
     * containing the removed element(s). We don't need the return value here.
     */
    books.splice(index, 1);

    // 204 No Content is standard for DELETE when there's no body to return.
    res.status(204).end();
  } catch (err) {
    next(err);
  }
});

// ─── Export the Router ─────────────────────────────────────────────────────────

module.exports = router;
```

> **Why `findIndex` instead of `find` for PUT/DELETE?** We need both to check existence and to mutate (replace or remove) in a single pass. Using `findIndex` lets us do both without iterating twice. For read-only operations like GET, `find` is slightly more readable since we only need the object.

