## File 4: `routes/stats.js`

```javascript
/**
 * routes/stats.js — Statistics endpoint for the book collection.
 *
 * WHY a separate route file?
 *   Stats are computed, not stored. Keeping them separate from CRUD routes
 *   makes it clear that this is an aggregate/read-only view of the data.
 */

const express = require('express');
const router = express.Router();

// Re-import the books array — in a larger app you'd share state via a service layer.
let { books } = require('./books');
// Note: because books is declared with `let` inside books.js, we can't directly
// re-export it. Instead we'll import the module and access its exported variable.
// To keep things simple in this educational example, we'll just require the module
// and use a shared state approach described below.

// ─── Actually, let's fix the sharing issue: ────────────────────────────────────
// The cleanest pattern for small apps is to put shared state in its own module.
// We'll adjust server.js to import books from a data store instead.
// For now, we'll just restructure slightly — see server.js comments.

/**
 * GET /stats
 *
 * Returns aggregate statistics about the book collection:
 *   - totalBooks: number of books in the collection
 *   - averagePublishedYear: mean year (rounded to 2 decimals)
 *   - genreBreakdown: object mapping each genre to its book count
 *   - oldestBook: title and year of the earliest published book
 *   - newestBook: title and year of the most recently published book
 *
 * @example curl http://localhost:3000/stats
 */
router.get('/', async function getStats(req, res, next) {
  try {
    // Guard against empty collection to avoid division by zero.
    if (books.length === 0) {
      return res.json({
        totalBooks: 0,
        averagePublishedYear: null,
        genreBreakdown: {},
        oldestBook: null,
        newestBook: null,
      });
    }

    /**
     * Compute the sum of all published years using reduce.
     * This is a functional pattern that avoids mutable accumulator variables.
     */
    const totalYear = books.reduce((sum, book) => sum + book.publishedYear, 0);
    const averagePublishedYear = Math.round((totalYear / books.length) * 100) / 100;

    /**
     * Build a genre → count mapping using reduce.
     * For each book, we increment the counter for its genre (or create it).
     */
    const genreBreakdown = books.reduce((acc, book) => {
      acc[book.genre] = (acc[book.genre] || 0) + 1;
      return acc;
    }, {});

    /**
     * Find the oldest and newest books by publishedYear.
     * We use reduce to avoid sorting the entire array (O(n log n)).
     */
    const { oldestBook, newestBook } = books.reduce(
      ({ oldestBook, newestBook }, book) => {
        if (!oldestBook || book.publishedYear < oldestBook.publishedYear) {
          oldestBook = book;
        }
        if (!newestBook || book.publishedYear > newestBook.publishedYear) {
          newestBook = book;
        }
        return { oldestBook, newestBook };
      },
      { oldestBook: null, newestBook: null }
    );

    res.json({
      totalBooks: books.length,
      averagePublishedYear,
      genreBreakdown,
      oldestBook: { title: oldestBook.title, publishedYear: oldestBook.publishedYear },
      newestBook: { title: newestBook.title, publishedYear: newestBook.publishedYear },
    });
  } catch (err) {
    next(err);
  }
});

module.exports = router;
```

> **Note on shared state:** In a real application you'd extract `books` into its own module (`data/store.js`) and import it in both route files. For this educational example, we'll keep the data in `routes/books.js` and have `server.js` import it directly, then pass it to the stats router. This avoids circular dependency issues that can arise when two route files try to import each other's state.

