```javascript
/**
 * routes/stats.js — Statistics endpoint.
 */

const express = require('express');
const { books } = require('../data/store');
const router = express.Router();

router.get('/', async function getStats(req, res, next) {
  try {
    if (books.length === 0) {
      return res.json({
        totalBooks: 0,
        averagePublishedYear: null,
        genreBreakdown: {},
        oldestBook: null,
        newestBook: null,
      });
    }

    const totalYear = books.reduce((sum, book) => sum + book.publishedYear, 0);
    const averagePublishedYear = Math.round((totalYear / books.length) * 100) / 100;

    const genreBreakdown = books.reduce((acc, book) => {
      acc[book.genre] = (acc[book.genre] || 0) + 1;
      return acc;
    }, {});

    const { oldestBook, newestBook } = books.reduce(
      ({ oldestBook, newestBook }, book) => {
        if (!oldestBook || book.publishedYear < oldestBook.publishedYear) {
          oldestBook = book;
        }
        if (!newestBook || book.publishedYear > newestBook.publishedYear) {
          newestBook = book;
        }
        return { oldestBook, newestBook };
      },
      { oldestBook: null, newestBook: null }
    );

    res.json({
      totalBooks: books.length,
      averagePublishedYear,
      genreBreakdown,
      oldestBook: { title: oldestBook.title, publishedYear: oldestBook.publishedYear },
      newestBook: { title: newestBook.title, publishedYear: newestBook.publishedYear },
    });
  } catch (err) {
    next(err);
  }
});

module.exports = router;
```

