## File 7: `server.js` — Application Entry Point

```javascript
/**
 * server.js — Express application bootstrap.
 *
 * WHY this order of middleware registration?
 *   1. express.json() — parses incoming JSON request bodies so req.body works.
 *      MUST come before route definitions so routes can read req.body.
 *   2. Our routes — mounted on /books and /stats prefixes.
 *   3. 404 catch-all — catches requests that don't match any route.
 *   4. errorHandler — catches errors from anywhere above. MUST be last.
 *
 * Express processes middleware in registration order, so placement is critical.
 */

const express = require('express');
const bookRoutes = require('./routes/books');
const statsRoutes = require('./routes/stats');
const { errorHandler } = require('./middleware/errorHandler');

const app = express();
const PORT = process.env.PORT || 3000;

// ─── Middleware ────────────────────────────────────────────────────────────────

/**
 * express.json() — Built-in middleware that parses incoming requests with
 * JSON payloads. Available under req.body. Without this, POST/PUT bodies
 * would be raw strings instead of parsed objects.
 */
app.use(express.json());

// Log every request in development for debugging visibility.
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next();
});

// ─── Routes ────────────────────────────────────────────────────────────────────

/**
 * Mount the book CRUD router at /books.
 * All routes defined in routes/books.js will be prefixed with /books.
 */
app.use('/books', bookRoutes);

/**
 * Mount the stats router at /stats.
 */
app.use('/stats', statsRoutes);

// ─── 404 Catch-All ─────────────────────────────────────────────────────────────

/**
 * If no route matches, return a 404 with a JSON message.
 * This must come AFTER all route definitions.
 */
app.use((req, res, next) => {
  const { NotFoundError } = require('./middleware/errorHandler');
  next(new NotFoundError('Endpoint'));
});

// ─── Global Error Handler ──────────────────────────────────────────────────────

/**
 * Must be the LAST middleware. Catches errors from routes, the 404 handler,
 * and any unexpected thrown errors.
 */
app.use(errorHandler);

// ─── Start Server ──────────────────────────────────────────────────────────────

app.listen(PORT, () => {
  console.log(`📚 Book API running on http://localhost:${PORT}`);
  console.log(`   GET  /books          — list all books`);
  console.log(`   GET  /books/:id      — get one book`);
  console.log(`   POST /books          — create a book`);
  console.log(`   PUT  /books/:id      — update a book`);
  console.log(`   DELETE /books/:id    — delete a book`);
  console.log(`   GET  /stats          — collection statistics`);
});
```

