## Arquivo 2: `src/models/book.js`

```javascript
/**
 * ============================================================
 *  MÓDULO: book.js — Modelo de dados (camada de persistência)
 * ============================================================
 *
 * POR QUE UM ARQUIVO SEPARADO?
 * ----------------------------
 * Separar a lógica de dados da lógica de rotas segue o princípio
 * da "separação de responsabilidades". As rotas decidem QUANDO
 * responder HTTP; este módulo decide COMO os dados são armazenados
 * e manipulados. Isso permite, no futuro, trocar o array em memória
 * por um banco de dados sem alterar as rotas.
 *
 * POR QUE ARRAY EM MEMÓRIA?
 * --------------------------
 * Para fins educacionais, um array é suficiente: é simples, previsível
 * e não requer instalação de bancos externos. Em produção, substituiríamos
 * por MongoDB, PostgreSQL, etc., mantendo a mesma interface (funções).
 *
 * POR QUE USAR SET PARA IDs?
 * ----------------------------
 * Um Set permite verificação O(1) de existência de ID, evitando
 * duplicatas durante a geração automática.
 */

// ─────────────────────────────────────────────────────────────
//  ESTADO GLOBAL (em memória)
// ─────────────────────────────────────────────────────────────

/**
 * Array que armazena todos os livros.
 *
 * Escolha: array em vez de objeto/map porque a ordem de inserção
 * importa para listagens e porque arrays são mais intuitivos para
 * operações como filtragem com .filter() e .find().
 */
const books = [];

/**
 * Contador sequencial para geração automática de IDs.
 *
 * Escolha: contador simples em vez de UUIDs porque IDs numéricos
 * são mais legíveis em exemplos educacionais e mais eficientes
 * para comparações. Em produção, UUID v4 ou nanoid seriam preferidos.
 */
let nextId = 1;

/**
 * Conjunto (Set) de IDs já utilizados.
 *
 * Escolha: Set porque oferece verificação de existência em O(1),
 * garantindo que IDs nunca se repitam mesmo após exclusões.
 */
const usedIds = new Set();

// ─────────────────────────────────────────────────────────────
//  FUNÇÕES DO MODELO
// ─────────────────────────────────────────────────────────────

/**
 * Retorna todos os livros armazenados.
 *
 * @returns {Array<Object>} Lista de todos os livros
 */
function getAll() {
  return books;
}

/**
 * Busca um livro pelo seu ID numérico.
 *
 * @param {number} id - ID do livro a ser encontrado
 * @returns {Object|null} Livro encontrado ou null se não existir
 */
function getById(id) {
  return books.find((book) => book.id === id) || null;
}

/**
 * Cria um novo livro e o adiciona à lista.
 *
 * Gera automaticamente um ID único usando o contador nextId,
 * incrementando-o após a criação para garantir unicidade.
 *
 * @param {Object} bookData - Dados do livro (sem id)
 * @returns {Object} O livro criado com ID atribuído
 */
function create(bookData) {
  const newBook = {
    id: nextId++,          // ID autoincremental único
    ...bookData,            // Espalha os campos fornecidos
    createdAt: new Date().toISOString(), // Timestamp de criação
    updatedAt: new Date().toISOString(),  // Timestamp de última atualização
  };

  usedIds.add(newBook.id);  // Registra o ID usado
  books.push(newBook);      // Adiciona ao array
  return newBook;
}

/**
 * Atualiza um livro existente pelo ID.
 *
 * Se o livro não existir, retorna null.
 * Usa Object.assign para mesclar os campos fornecidos,
 * mantendo id e timestamps originais intactos.
 *
 * @param {number} id - ID do livro a atualizar
 * @param {Object} updates - Campos a serem atualizados
 * @returns {Object|null} Livro atualizado ou null se não encontrado
 */
function update(id, updates) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return null;

  // Mescla dados existentes com atualizações
  books[index] = {
    ...books[index],        // Mantém campos não fornecidos
    ...updates,             // Sobrescreve com novos valores
    id,                     // Garante que o ID não mude
    updatedAt: new Date().toISOString(), // Atualiza timestamp
  };

  return books[index];
}

/**
 * Remove um livro pelo ID.
 *
 * @param {number} id - ID do livro a remover
 * @returns {boolean} true se removido, false se não encontrado
 */
function remove(id) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1);   // Remove do array
  usedIds.delete(id);       // Libera o ID do conjunto
  return true;
}

/**
 * Calcula estatísticas agregadas sobre os livros.
 *
 * @returns {Object} Estatísticas: total, média de páginas,
 *                   autores únicos, gêneros únicos, etc.
 */
function getStats() {
  const total = books.length;

  if (total === 0) {
    return {
      total,
      averagePages: 0,
      uniqueAuthors: 0,
      uniqueGenres: 0,
      minPages: null,
      maxPages: null,
    };
  }

  // Usa Set para contar valores únicos (autores e gêneros)
  const authors = new Set(books.map((b) => b.author));
  const genres = new Set(books.flatMap((b) => (Array.isArray(b.genre) ? b.genre : [b.genre])));

  const pages = books.map((b) => b.pages || 0);
  const minPages = Math.min(...pages);
  const maxPages = Math.max(...pages);
  const averagePages = parseFloat(
    (pages.reduce((a, b) => a + b, 0) / total).toFixed(2)
  );

  return {
    total,
    averagePages,
    uniqueAuthors: authors.size,
    uniqueGenres: genres.size,
    minPages,
    maxPages,
  };
}

// ─────────────────────────────────────────────────────────────
//  EXPORTAÇÃO (padrão CommonJS)
// ─────────────────────────────────────────────────────────────
module.exports = { getAll, getById, create, update, remove, getStats };
```

