## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================
 *  MÓDULO: errorHandler.js — Middleware centralizado de erros
 * ============================================================
 *
 * POR QUE UM MIDDLWARE DE ERROS?
 * --------------------------------
 * Em vez de repetir blocos try/catch em cada rota, criamos um
 * middleware que captura erros e os transforma em respostas HTTP
 * padronizadas. Isso garante consistência na formato de erro
 * retornado ao cliente (campo "error" com mensagem legível).
 *
 * O Express identifica middlewares de erro pela assinatura
 * especial: (err, req, res, next) => ... — quatro parâmetros.
 */

/**
 * Classe base para erros personalizados da API.
 *
 * Herda de Error nativo para manter compatibilidade com o stack trace.
 * Adiciona uma propriedade `statusCode` que indica o código HTTP
 * correspondente ao tipo de erro.
 */
class ApiError extends Error {
  /**
   * @param {string} message - Mensagem de erro legível
   * @param {number} statusCode - Código HTTP (400, 404, 500, etc.)
   */
  constructor(message, statusCode) {
    super(message);          // Chama o construtor da classe Error
    this.statusCode = statusCode;
    this.isOperational = true; // Marca como erro esperado (não bug)
  }
}

/**
 * Erro para requisições malformadas (campos faltando, tipos errados).
 */
class ValidationError extends ApiError {
  constructor(message) {
    super(message, 400);     // 400 Bad Request
  }
}

/**
 * Erro quando um recurso não é encontrado.
 */
class NotFoundError extends ApiError {
  constructor(resource) {
    super(`${resource} não encontrado`, 404);  // 404 Not Found
  }
}

/**
 * Middleware que captura erros e os converte em respostas JSON padronizadas.
 *
 * @param {Error} err - Objeto de erro capturado
 * @param {Object} req - Request do Express
 * @param {Object} res - Response do Express
 * @param {Function} next - Função next do Express (não usada aqui)
 */
function errorHandler(err, req, res, next) {
  // Para erros operacionais da API, usamos a mensagem e status definidos
  if (err.isOperational) {
    return res.status(err.statusCode).json({
      success: false,
      error: err.message,
    });
  }

  // Para erros não esperadas (bugs), logamos no servidor
  // mas enviamos uma mensagem genérica ao cliente por segurança
  console.error('❌ ERRO NO SERVIDOR:', err);
  return res.status(500).json({
    success: false,
    error: 'Erro interno do servidor',
  });
}

module.exports = { ApiError, ValidationError, NotFoundError, errorHandler };
```

