## Arquivo 4: `src/routes/books.js`

```javascript
/**
 * ============================================================
 *  MÓDULO: books.js — Rotas da API para livros
 * ============================================================
 *
 * POR QUE ROTAS SEPARADAS?
 * -------------------------
 * Manter rotas em arquivo próprio permite escalar: quando a API
 * crescer (autores, editoras, empréstimos), cada domínio terá seu
 * próprio arquivo de rotas. O Express usa `express.Router()` para
 * criar roteadores modulares que podem ser montados no app principal.
 *
 * POR QUE USAR async/await?
 * --------------------------
 * Async/await torna o código assíncrono mais legível, evitando
 * "callback hell" e facilitando o uso de try/catch para tratamento
 * de erros. Mesmo que neste exemplo as operações sejam síncronas
 * (array em memória), usamos async/await como prática preparatória
 * para quando conectarmos a um banco de dados real.
 */

const express = require('express');
const router = express.Router(); // Cria um roteador modular

// Importa o modelo e os erros personalizados
const { getAll, getById, create, update, remove, getStats } = require('../models/book');
const { ValidationError, NotFoundError } = require('../middleware/errorHandler');

// ─────────────────────────────────────────────────────────────
//  VALIDAÇÃO DE ENTRADA (input validation)
// ─────────────────────────────────────────────────────────────

/**
 * Valida os campos obrigatórios para criação/atualização de livro.
 *
 * @param {Object} body - Corpo da requisição
 * @throws {ValidationError} Se campos obrigatórios faltarem
 */
function validateBookBody(body) {
  const errors = [];

  if (!body.title || typeof body.title !== 'string' || body.title.trim() === '') {
    errors.push('O campo "title" é obrigatório e deve ser uma string não vazia.');
  }
  if (!body.author || typeof body.author !== 'string' || body.author.trim() === '') {
    errors.push('O campo "author" é obrigatório e deve ser uma string não vazia.');
  }

  // pages deve ser um número positivo se fornecido
  if (body.pages !== undefined && (typeof body.pages !== 'number' || body.pages < 0)) {
    errors.push('O campo "pages" deve ser um número inteiro não negativo.');
  }

  if (errors.length > 0) {
    throw new ValidationError(errors.join(' '));
  }
}

// ─────────────────────────────────────────────────────────────
//  GET /books — Listar todos os livros (com filtragem opcional)
// ─────────────────────────────────────────────────────────────

/**
 * @route   GET /books
 * @desc    Retorna lista de todos os livros
 * @access  Public
 *
 * QUERY PARAMETERS (opcionais):
 *   - author: filtra por autor (case-insensitive)
 *   - genre:  filtra por gênero
 *   - minPages: filtro mínimo de páginas
 *   - maxPages: filtro máximo de páginas
 *
 * @example curl "http://localhost:3000/books?author=jk&minPages=100"
 */
router.get('/books', (req, res) => {
  let result = getAll(); // Começa com todos os livros

  // Filtragem por autor (parcial e case-insensitive)
  if (req.query.author) {
    const authorFilter = req.query.author.toLowerCase();
    result = result.filter((book) =>
      book.author.toLowerCase().includes(authorFilter)
    );
  }

  // Filtragem por gênero
  if (req.query.genre) {
    const genreFilter = req.query.genre.toLowerCase();
    result = result.filter((book) => {
      const genres = Array.isArray(book.genre) ? book.genre : [book.genre];
      return genres.some((g) => g.toLowerCase() === genreFilter);
    });
  }

  // Filtragem por faixa de páginas
  if (req.query.minPages) {
    const min = parseInt(req.query.minPages, 10);
    result = result.filter((book) => (book.pages || 0) >= min);
  }
  if (req.query.maxPages) {
    const max = parseInt(req.query.maxPages, 10);
    result = result.filter((book) => (book.pages || 0) <= max);
  }

  // Resposta padronizada com campo "success"
  res.json({ success: true, data: result });
});

// ─────────────────────────────────────────────────────────────
//  GET /books/stats — Estatísticas agregadas
// ─────────────────────────────────────────────────────────────

/**
 * @route   GET /books/stats
 * @desc    Retorna estatísticas sobre os livros cadastrados
 * @access  Public
 *
 * Resposta inclui: total de livros, média de páginas,
 * quantidade de autores e gêneros únicos, min/max de páginas.
 *
 * @example curl "http://localhost:3000/books/stats"
 */
router.get('/books/stats', (req, res) => {
  const stats = getStats();
  res.json({ success: true, data: stats });
});

// ─────────────────────────────────────────────────────────────
//  GET /books/:id — Obter livro por ID
// ─────────────────────────────────────────────────────────────

/**
 * @route   GET /books/:id
 * @desc    Retorna um livro específico pelo ID
 * @access  Public
 *
 * @param {number} id - ID numérico do livro (parâmetro de rota)
 *
 * @example curl "http://localhost:3000/books/1"
 */
router.get('/books/:id', (req, res) => {
  const id = parseInt(req.params.id, 10); // Converte string para número

  const book = getById(id);
  if (!book) {
    throw new NotFoundError('Livro'); // Lança erro que será capturado pelo middleware
  }

  res.json({ success: true, data: book });
});

// ─────────────────────────────────────────────────────────────
//  POST /books — Criar novo livro
// ─────────────────────────────────────────────────────────────

/**
 * @route   POST /books
 * @desc    Cria um novo livro
 * @access  Public
 *
 * Body JSON esperado:
 * {
 *   "title": "O Senhor dos Anéis",
 *   "author": "J.R.R. Tolkien",
 *   "genre": ["Fantasia", "Aventura"],
 *   "pages": 1200,
 *   "year": 1954
 * }
 *
 * @example curl -X POST http://localhost:3000/books \
 *           -H "Content-Type: application/json" \
 *           -d '{"title":"1984","author":"George Orwell","pages":328}'
 */
router.post('/books', (req, res) => {
  // Valida os campos obrigatórios antes de criar
  validateBookBody(req.body);

  const book = create({
    title: req.body.title.trim(),
    author: req.body.author.trim(),
    genre: req.body.genre || 'Não informado',
    pages: req.body.pages || 0,
    year: req.body.year || null,
    description: req.body.description || '',
  });

  // 201 Created é o código HTTP padrão para recursos criados com sucesso
  res.status(201).json({ success: true, data: book });
});

// ─────────────────────────────────────────────────────────────
//  PUT /books/:id — Atualizar livro existente
// ─────────────────────────────────────────────────────────────

/**
 * @route   PUT /books/:id
 * @desc    Atualiza completamente um livro existente
 * @access  Public
 *
 * Body JSON: campos a atualizar (title, author, genre, pages, year, description)
 * Campos não fornecidos são mantidos.
 *
 * @example curl -X PUT http://localhost:3000/books/1 \
 *           -H "Content-Type: application/json" \
 *           -d '{"pages": 450}'
 */
router.put('/books/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);

  // Primeiro verifica se o livro existe
  const existing = getById(id);
  if (!existing) {
    throw new NotFoundError('Livro');
  }

  // Valida apenas os campos fornecidos no body
  validateBookBody(req.body);

  const updated = update(id, {
    title: req.body.title !== undefined ? req.body.title.trim() : existing.title,
    author: req.body.author !== undefined ? req.body.author.trim() : existing.author,
    genre: req.body.genre !== undefined ? req.body.genre : existing.genre,
    pages: req.body.pages !== undefined ? req.body.pages : existing.pages,
    year: req.body.year !== undefined ? req.body.year : existing.year,
    description: req.body.description !== undefined ? req.body.description : existing.description,
  });

  res.json({ success: true, data: updated });
});

// ─────────────────────────────────────────────────────────────
//  DELETE /books/:id — Excluir livro
// ─────────────────────────────────────────────────────────────

/**
 * @route   DELETE /books/:id
 * @desc    Remove um livro pelo ID
 * @access  Public
 *
 * @param {number} id - ID numérico do livro a remover
 *
 * @example curl -X DELETE http://localhost:3000/books/1
 */
router.delete('/books/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);

  const removed = remove(id);
  if (!removed) {
    throw new NotFoundError('Livro');
  }

  // 200 OK com mensagem de confirmação
  res.json({ success: true, message: 'Livro removido com sucesso' });
});

// ─────────────────────────────────────────────────────────────
//  EXPORTAÇÃO DO ROTEADOR
// ─────────────────────────────────────────────────────────────
module.exports = router;
```

