/**
 * ============================================================
 *  MÓDULO: app.js — Configuração da aplicação Express
 * ============================================================
 *
 * Este arquivo configura o aplicativo Express central, montando
 * middlewares globais e roteadores. A ordem de montagem dos
 * middlewares é importante: body-parser antes das rotas,
 * errorHandler por último (após todas as rotas).
 */

const express = require('express');
const bookRoutes = require('./routes/books');
const { errorHandler } = require('./middleware/errorHandler');

const app = express(); // Cria a instância do aplicativo

// ─────────────────────────────────────────────────────────────
//  MIDDLEWARES GLOBAIS
// ─────────────────────────────────────────────────────────────

/**
 * express.json() — Parser do corpo da requisição como JSON.
 *
 * Sem este middleware, req.body seria undefined.
 * Limitamos a 10kb para evitar requisições excessivamente grandes.
 */
app.use(express.json({ limit: '10kb' }));

/**
 * Middleware simples de logging de requisições.
 * Imprime método, URL e timestamp no console do servidor.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Passa para o próximo middleware/rota
});

// ─────────────────────────────────────────────────────────────
//  MONTAGEM DAS ROTAS
// ─────────────────────────────────────────────────────────────

/**
 * Monta as rotas de livros no caminho base /books.
 * Todas as rotas definidas em routes/books.js ficam disponíveis
 * sob o prefixo /books (ex: GET /books, POST /books/:id).
 */
app.use('/books', bookRoutes);

// ─────────────────────────────────────────────────────────────
//  ROTA DE HEALTH CHECK (raiz)
// ─────────────────────────────────────────────────────────────

/**
 * @route   GET /
 * @desc    Health check — verifica se a API está no ar
 * @access  Public
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'API de Livros rodando!',
    endpoints: {
      list: 'GET /books',
      stats: 'GET /books/stats',
      byId: 'GET /books/:id',
      create: 'POST /books',
      update: 'PUT /books/:id',
      delete: 'DELETE /books/:id',
    },
  });
});

// ─────────────────────────────────────────────────────────────
//  MANIPULADOR DE ROTAS NÃO ENCONTRADAS (404)
// ─────────────────────────────────────────────────────────────

/**
 * Retorna 404 para qualquer rota que não corresponda a nenhuma definida.
 */
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: `Rota ${req.method} ${req.url} não encontrada`,
  });
});

// ─────────────────────────────────────────────────────────────
//  MIDDLEWARE DE ERROS (DEVE SEMPRE SER O ÚLTIMO)
// ─────────────────────────────────────────────────────────────

/**
 * Middleware de tratamento de erros centralizado.
 * Deve ser o último app.use() para capturar erros de todas as rotas.
 */
app.use(errorHandler);

module.exports = app;
