/**
 * ============================================================================
 * CUSTOM ERROR CLASSES
 * ============================================================================
 *
 * WHY we use custom error classes instead of generic Error objects:
 *   1. They carry semantic meaning — a NotFoundError tells the caller exactly
 *      what went wrong without reading stack traces.
 *   2. They enable type-based error handling in middleware (instanceof checks).
 *   3. They extend naturally from Node's built-in Error, preserving all standard
 *      behavior (stack traces, message property, etc.).
 *
 * DESIGN CHOICE: Each class sets `this.name` explicitly so that when the error
 * is logged or serialized, it appears with a human-readable identifier rather
 * than the default "Error" name.
 */

/**
 * Base custom error class that all application errors extend from.
 * Provides consistent structure for name, message, and HTTP status code.
 */
class AppError extends Error {
  /**
   * @param {string} message - Human-readable description of the error
   * @param {number} statusCode - HTTP status code to return to the client
   */
  constructor(message, statusCode) {
    super(message); // Call the parent Error constructor with our message

    // Explicitly set the name so error logs show "ValidationError" instead of "Error"
    this.name = this.constructor.name;

    // Attach the HTTP status code as a property — middleware reads this to respond correctly
    this.statusCode = statusCode;

    // Capture the stack trace at the point where this error was thrown
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * ResourceNotFoundError — thrown when a requested resource does not exist.
 * Example: GET /books/999 when only books with IDs 1-5 exist.
 *
 * HTTP STATUS: 404 Not Found
 */
class NotFoundError extends AppError {
  constructor(resource, id) {
    // Build a descriptive message that identifies both the resource type and the missing ID
    const message = `${resource} with id ${id} not found`;
    super(message, 404);
  }
}

/**
 * ValidationError — thrown when client input fails validation checks.
 * Example: POST /books with an empty title or a negative price.
 *
 * HTTP STATUS: 400 Bad Request
 */
class ValidationError extends AppError {
  constructor(message) {
    super(message, 400);
  }
}

/**
 * MethodNotAllowedError — thrown when an unsupported HTTP method is used.
 * Example: PATCH /books/:id (we only support PUT for updates).
 *
 * HTTP STATUS: 405 Method Not Allowed
 */
class MethodNotAllowedError extends AppError {
  constructor(allowedMethods) {
    const message = `Method ${allowedMethods.join(', ')} is not allowed. Use one of: ${allowedMethods.join(' or ')}`;
    super(message, 405);
  }
}

/**
 * InternalServerError — thrown for unexpected server-side failures.
 * This should rarely be used directly; prefer letting unhandled exceptions
 * bubble up so the generic error handler catches them.
 *
 * HTTP STATUS: 500 Internal Server Error
 */
class InternalServerError extends AppError {
  constructor(message = 'An unexpected error occurred on the server') {
    super(message, 500);
  }
}

// Export all custom error classes for use throughout the application
module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  MethodNotAllowedError,
  InternalServerError,
};
```

> **Key takeaway:** Custom error classes form the foundation of our error-handling strategy. By attaching a `statusCode` property to each error, our middleware can automatically map errors to appropriate HTTP responses without needing switch/case statements for every error type.

