## File 3: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================================
 * ERROR HANDLING MIDDLEWARE
 * ============================================================================
 *
 * WHY we use a centralized error-handling middleware in Express:
 *   Express provides a special middleware signature with FOUR parameters:
 *     (error, req, res, next)
 *   When ANY route or middleware calls `next(error)`, Express skips all
 *   remaining normal middleware and jumps directly to this handler. This means:
 *     - We never need try/catch blocks in every single route handler
 *       (when using async/await with proper wrapping — see below)
 *     - Error responses are consistent across the entire API
 *     - Debugging is easier because all errors flow through one place
 *
 * DESIGN CHOICE: We handle both synchronous errors (via next(error)) and
 * asynchronous errors (by wrapping route handlers). The `asyncHandler`
 * utility below bridges the gap between async/await and Express's error pattern.
 */

const { InternalServerError } = require('../errors/customErrors');

/**
 * Wraps an async route handler so that any thrown error is automatically
 * passed to Express's error-handling middleware via next(error).
 *
 * WITHOUT this wrapper, if an async function throws an error, Express has no
 * way to catch it because the promise rejection doesn't call `next()`.
 * This wrapper converts unhandled promise rejections into Express errors.
 *
 * @param {Function} fn - An async function that handles a request
 * @returns {Function} An Express middleware function
 *
 * EXAMPLE USAGE:
 *   router.get('/books', asyncHandler(async (req, res) => { ... }));
 */
function asyncHandler(fn) {
  return (req, res, next) => {
    // Call the wrapped async function and pass `next` so it can propagate errors
    fn(req, res, next).catch(next);
    // .catch(next) is the key: if the promise rejects, we call next(error)
    // which routes execution to our error-handling middleware below
  };
}

/**
 * Main error-handling middleware.
 * This MUST be registered last (after all routes) for Express to recognize it
 * as an error handler rather than a normal middleware.
 *
 * @param {Error} err - The error object (our custom error or a standard Error)
 * @param {import('express').Request} req - The Express request object
 * @param {import('express').Response} res - The Express response object
 * @param {import('express').NextFunction} next - Not used in error handlers
 */
function errorHandler(err, req, res, next) {
  // Determine the HTTP status code:
  //   - If our custom error has a statusCode property, use it (e.g., 404, 400)
  //   - Otherwise default to 500 for unexpected/unhandled errors
  const statusCode = err.statusCode || 500;

  // Build a consistent JSON response body for ALL errors
  const response = {
    success: false,
    error: {
      // Use the error's name property (e.g., "NotFoundError") if available,
      // otherwise fall back to the generic "Error"
      type: err.name || 'Error',
      message: err.message,
    },
  };

  // In development mode, include the full stack trace for debugging.
  // In production, hide stack traces to avoid leaking internal implementation details.
  if (process.env.NODE_ENV !== 'production') {
    response.error.stack = err.stack;
  }

  // Log the error to the console/server logs for debugging and monitoring.
  // This runs regardless of environment so we can track issues in production too.
  console.error(`[ERROR] ${statusCode} - ${err.name}: ${err.message}`);
  if (process.env.NODE_ENV !== 'production' && err.stack) {
    console.error(err.stack);
  }

  // Send the JSON response with the appropriate status code
  res.status(statusCode).json(response);
}

module.exports = { asyncHandler, errorHandler };
```

> **Why `asyncHandler`?** This is one of the most important utilities in an Express + async/await application. Without it, every async route would need a try/catch block calling `next(err)` manually. With it, promise rejections flow naturally into our centralized error handler. The pattern `.catch(next)` is idiomatic and keeps route handlers clean.

