```javascript
/**
 * ============================================================================
 * IN-MEMORY DATA STORE (MODEL LAYER)
 * ============================================================================
 *
 * WHY we use an in-memory array instead of a database for this educational example:
 *   1. Zero setup — no MongoDB, PostgreSQL, or SQLite installation required
 *   2. Instant startup — the API is ready to test immediately after `npm start`
 *   3. Focus on API patterns — we can concentrate on REST conventions, error
 *      handling, and middleware without database complexity
 *   4. Easy to understand — a plain JavaScript array with objects is transparent
 *
 * DATA STRUCTURE CHOICE: We use an array of book objects rather than a Map or
 * object keyed by ID because:
 *   - Arrays preserve insertion order (useful for list endpoints)
 *   - They're the most familiar data structure to JavaScript developers
 *   - For this educational scale (dozens of records), performance is not a concern
 *
 * NOTE: In a production application, you would replace this entire module with
 * database queries (e.g., using Sequelize, Mongoose, or raw SQL). The route
 * handlers below would remain largely the same — only the data access layer changes.
 */

// Import custom errors so we can throw meaningful errors when operations fail
const { NotFoundError, ValidationError } = require('../errors/customErrors');

/**
 * In-memory storage array for all book records.
 *
 * STRUCTURE of each book object:
 *   {
 *     id: number          — Unique identifier (auto-incremented)
 *     title: string       — Book title (required, non-empty)
 *     author: string      — Author name (required, non-empty)
 *     genre: string       — Book genre/category (optional)
 *     publishedYear: number — Year the book was published (optional)
 *     createdAt: string    — ISO timestamp of creation (auto-generated)
 *     updatedAt: string    — ISO timestamp of last modification (auto-generated)
 *   }
 *
 * WHY we store timestamps as ISO strings:
 *   - ISO 8601 format is the standard for APIs (e.g., "2024-01-15T10:30:00.000Z")
 *   - JavaScript's Date.toISOString() produces this format natively
 *   - It sorts correctly as strings and is unambiguous across timezones
 */
const books = [];

/**
 * Counter for generating unique book IDs.
 * Starts at 1 and increments with each new book creation.
 *
 * WHY a simple counter instead of UUIDs or timestamps:
 *   - Simpler to understand and debug
 *   - Produces clean, sequential IDs (1, 2, 3...) that are easy to reference
 *   - For an educational example, readability matters more than collision resistance
 *
 * In production, you would use UUIDs (v4) or database auto-increment columns.
 */
let nextId = 1;

/**
 * Retrieves all books from the in-memory store.
 *
 * @returns {Array<Object>} Array of all book objects
 */
function getAllBooks() {
  return books;
}

/**
 * Finds a single book by its ID.
 *
 * @param {number} id - The unique identifier of the book to find
 * @returns {Object|null} The book object if found, null otherwise
 */
function getBookById(id) {
  // Array.find() returns the first element that matches the predicate, or undefined
  return books.find((book) => book.id === id) || null;
}

/**
 * Creates a new book and adds it to the in-memory store.
 *
 * @param {Object} bookData - The book data provided by the client
 * @param {string} bookData.title - Book title (required)
 * @param {string} bookData.author - Author name (required)
 * @param {string} [bookData.genre] - Book genre (optional)
 * @param {number} [bookData.publishedYear] - Publication year (optional)
 * @returns {Object} The newly created book object with generated id and timestamps
 * @throws {ValidationError} If required fields are missing or invalid
 */
function createBook(bookData) {
  // Validate that the title is provided and is a non-empty string
  if (!bookData.title || typeof bookData.title !== 'string' || bookData.title.trim() === '') {
    throw new ValidationError('Title is required and must be a non-empty string');
  }

  // Validate that the author is provided and is a non-empty string
  if (!bookData.author || typeof bookData.author !== 'string' || bookData.author.trim() === '') {
    throw new ValidationError('Author is required and must be a non-empty string');
  }

  // Generate a unique ID by incrementing our counter
  const id = nextId++;

  // Capture the current timestamp in ISO format for both createdAt and updatedAt
  const now = new Date().toISOString();

  // Build the book object, spreading in any optional fields from bookData
  // We explicitly set id, createdAt, and updatedAt — these are server-controlled
  const book = {
    id,
    title: bookData.title.trim(), // Trim whitespace from the title for consistency
    author: bookData.author.trim(), // Trim whitespace from the author for consistency
    genre: bookData.genre ? bookData.genre.trim() : undefined, // Optional field, trim if present
    publishedYear: bookData.publishedYear || undefined, // Optional numeric field
    createdAt: now,
    updatedAt: now,
  };

  // Add the new book to our in-memory array
  books.push(book);

  return book;
}

/**
 * Updates an existing book by its ID.
 *
 * @param {number} id - The unique identifier of the book to update
 * @param {Object} updateData - Fields to update (partial object)
 * @returns {Object} The updated book object
 * @throws {NotFoundError} If no book with the given ID exists
 * @throws {ValidationError} If required fields fail validation after update
 */
function updateBook(id, updateData) {
  // Find the index of the book in our array (indexOf returns -1 if not found)
  const index = books.findIndex((book) => book.id === id);

  // If the book doesn't exist, throw a NotFoundError with a descriptive message
  if (index === -1) {
    throw new NotFoundError('Book', id);
  }

  // Validate title if it's being updated
  if (updateData.title !== undefined) {
    if (typeof updateData.title !== 'string' || updateData.title.trim() === '') {
      throw new ValidationError('Title must be a non-empty string');
    }
    updateData.title = updateData.title.trim();
  }

  // Validate author if it's being updated
  if (updateData.author !== undefined) {
    if (typeof updateData.author !== 'string' || updateData.author.trim() === '') {
      throw new ValidationError('Author must be a non-empty string');
    }
    updateData.author = updateData.author.trim();
  }

  // Update the book object in-place using Object.assign, which copies properties
  // from updateData onto the existing book object
  // We also update the updatedAt timestamp to reflect when this change occurred
  const updatedBook = Object.assign(books[index], updateData, { updatedAt: new Date().toISOString() });

  return updatedBook;
}

/**
 * Deletes a book from the in-memory store by its ID.
 *
 * @param {number} id - The unique identifier of the book to delete
 * @returns {Object} The deleted book object
 * @throws {NotFoundError} If no book with the given ID exists
 */
function deleteBook(id) {
  // Find the index of the book in our array
  const index = books.findIndex((book) => book.id === id);

  // If not found, throw a NotFoundError
  if (index === -1) {
    throw new NotFoundError('Book', id);
  }

  // Remove the book from the array using splice:
  //   - index: starting position
  //   - 1: number of elements to remove
  // Returns an array containing the removed element(s)
  const [deletedBook] = books.splice(index, 1);

  return deletedBook;
}

/**
 * Computes aggregate statistics about all books in the store.
 *
 * @returns {Object} Statistics object containing counts and breakdowns
 */
function getStats() {
  // Total number of books in the store
  const totalBooks = books.length;

  // Count books by genre using a reduce accumulator:
  //   - Start with an empty object {}
  //   - For each book, increment the count for its genre (or 'Unknown' if missing)
  const genres = books.reduce((acc, book) => {
    const genre = book.genre && book.genre.trim() !== '' ? book.genre : 'Unknown';
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  // Count books by decade of publication:
  //   - Only consider books that have a publishedYear
  //   - Group into decades (e.g., 1990s, 2000s, 2010s)
  const decades = books
    .filter((book) => book.publishedYear && !isNaN(book.publishedYear))
    .reduce((acc, book) => {
      // Math.floor divides by 10 and rounds down to get the decade
      // e.g., 1995 -> Math.floor(1995/10)*10 = 1990
      const decade = Math.floor(book.publishedYear / 10) * 10;
      const decadeLabel = `${decade}s`;
      acc[decadeLabel] = (acc[decadeLabel] || 0) + 1;
      return acc;
    }, {});

  // Sort decades chronologically by converting keys back to numbers
  const sortedDecades = Object.entries(decades)
    .sort((a, b) => parseInt(a[0]) - parseInt(b[0]))
    .reduce((acc, [key, value]) => {
      acc[key] = value;
      return acc;
    }, {});

  return {
    totalBooks,
    booksByGenre: genres,
    booksByDecade: sortedDecades,
    averagePublishedYear:
      totalBooks > 0
        ? (books.reduce((sum, book) => sum + (book.publishedYear || 0), 0) / totalBooks).toFixed(1)
        : null,
  };
}

// Export all data access functions as a module
// This follows the principle of explicit exports — consumers know exactly what's available
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

> **Why separate model from routes?** This separation means we could swap the in-memory store for a real database (MongoDB, PostgreSQL, etc.) without changing any route logic. The routes call `createBook(data)` regardless of whether that function queries a database or pushes to an array. This is called the **Repository Pattern** and is essential for maintainable applications.

