/**
 * ============================================================================
 * BOOK ROUTES
 * ============================================================================
 *
 * WHY we organize routes into a separate module:
 *   1. Separation of concerns — route definitions are isolated from the app setup
 *   2. Reusability — this router can be mounted at any path in the main app
 *   3. Testability — individual route handlers can be tested in isolation
 *   4. Readability — each file focuses on one resource's endpoints
 *
 * REST CONVENTIONS we follow:
 *   - GET    /books          → List all books (with optional query filters)
 *   - GET    /books/:id      → Get a single book by ID
 *   - POST   /books          → Create a new book
 *   - PUT    /books/:id      → Fully update an existing book
 *   - DELETE /books/:id      → Delete a book by ID
 *
 * HTTP STATUS CODES we return:
 *   - 200 OK        → Successful GET or PUT request
 *   - 201 Created   → Successful POST request (resource was created)
 *   - 204 No Content→ Successful DELETE request (no body to return)
 *   - 400 Bad Request → Validation errors (handled by our error middleware)
 *   - 404 Not Found → Resource doesn't exist (handled by our error middleware)
 *
 * QUERY PARAMETER FILTERING:
 *   The GET /books endpoint supports optional query parameters for filtering:
 *     ?genre=fiction      — Filter by genre (case-insensitive partial match)
 *     ?author=tolkien     — Filter by author name (case-insensitive partial match)
 *     ?year=2020          — Filter by exact publication year
 *     ?search=mystery     — Search across title and author fields
 */

const express = require('express');

// Import our custom error handler wrapper for async route safety
const { asyncHandler } = require('../middleware/errorHandler');

// Import data access functions from our model layer
const { getAllBooks, getBookById, createBook, updateBook, deleteBook } = require('../models/books');

// Create an Express router instance — this is a standalone middleware/container
// It allows us to define routes that can be mounted anywhere in the app
const router = express.Router();

/**
 * GET /books
 * Retrieves all books with optional filtering via query parameters.
 *
 * QUERY PARAMETERS (all optional):
 *   - genre: string — Filter by genre (case-insensitive, partial match)
 *   - author: string — Filter by author name (case-insensitive, partial match)
 *   - year: number — Filter by exact publication year
 *   - search: string — Search across title and author fields
 *
 * @example
 *   // Get all books
 *   GET /books
 *
 *   // Get fiction books
 *   GET /books?genre=fiction
 *
 *   // Search for books by authors containing "tolkien"
 *   GET /books?author=tolkien
 *
 *   // Get books published in 2020
 *   GET /books?year=2020
 *
 *   // Search across title and author
 *   GET /books?search=mystery
 */
router.get(
  '/books',
  asyncHandler(async (req, res) => {
    // Destructure query parameters from req.query with fallback defaults
    // req.query is an object containing all URL query string parameters
    const { genre, author, year, search } = req.query;

    // Start with the full list of books
    let filteredBooks = getAllBooks();

    // Apply genre filter if provided:
    //   - Convert both the filter and book genre to lowercase for case-insensitive comparison
    //   - Use String.includes() for partial matching (e.g., "fic" matches "fiction")
    if (genre) {
      filteredBooks = filteredBooks.filter((book) =>
        book.genre && book.genre.toLowerCase().includes(genre.toLowerCase())
      );
    }

    // Apply author filter if provided:
    //   - Same case-insensitive partial match approach as genre
    if (author) {
      filteredBooks = filteredBooks.filter((book) =>
        book.author.toLowerCase().includes(author.toLowerCase())
      );
    }

    // Apply year filter if provided:
    //   - Convert both to numbers for exact numeric comparison
    //   - Use Number() to handle string-to-number conversion from query params
    if (year) {
      const yearNum = Number(year);
      filteredBooks = filteredBooks.filter((book) => book.publishedYear === yearNum);
    }

    // Apply search filter if provided:
    //   - Search across both title and author fields
    //   - Case-insensitive partial match on either field
    if (search) {
      const searchTerm = search.toLowerCase();
      filteredBooks = filteredBooks.filter(
        (book) =>
          book.title.toLowerCase().includes(searchTerm) ||
          book.author.toLowerCase().includes(searchTerm)
      );
    }

    // Return the (possibly filtered) list of books with a 200 OK status
    // We include a message to indicate whether filtering was applied
    res.status(200).json({
      success: true,
      count: filteredBooks.length,
      data: filteredBooks,
      filters: { genre, author, year, search }.filter((v) => v !== undefined),
    });
  })
);

/**
 * GET /books/:id
 * Retrieves a single book by its unique ID.
 *
 * @param {string} req.params.id - The book ID (converted to number internally)
 *
 * @example
 *   // Get the book with ID 1
 *   GET /books/1
 *
 *   // Response:
 *   {
 *     "success": true,
 *     "data": {
 *       "id": 1,
 *       "title": "The Hobbit",
 *       "author": "J.R.R. Tolkien",
 *       "genre": "Fantasy",
 *       "publishedYear": 1937,
 *       "createdAt": "2024-01-15T10:30:00.000Z",
 *       "updatedAt": "2024-01-15T10:30:00.000Z"
 *     }
 *   }
 */
router.get(
  '/books/:id',
  asyncHandler(async (req, res) => {
    // Convert the ID from string (URL params are always strings) to a number
    const id = Number(req.params.id);

    // Look up the book using our model function
    const book = getBookById(id);

    // If the book doesn't exist, NotFoundError is thrown by getBookById
    // and caught by our error-handling middleware (via asyncHandler)
    res.status(200).json({
      success: true,
      data: book,
    });
  })
);

/**
 * POST /books
 * Creates a new book from the request body.
 *
 * REQUEST BODY (JSON):
 *   {
 *     "title": "The Hobbit",        // Required string
 *     "author": "J.R.R. Tolkien",   // Required string
 *     "genre": "Fantasy",           // Optional string
 *     "publishedYear": 1937         // Optional number
 *   }
 *
 * @example
 *   POST /books
 *   Content-Type: application/json
 *
 *   Body:
 *   {
 *     "title": "Dune",
 *     "author": "Frank Herbert",
 *     "genre": "Science Fiction",
 *     "publishedYear": 1965
 *   }
 *
 *   Response (201 Created):
 *   {
 *     "success": true,
 *     "data": {
 *       "id": 6,
 *       "title": "Dune",
 *       "author": "Frank Herbert",
 *       ...
 *     }
 *   }
 */
router.post(
  '/books',
  asyncHandler(async (req, res) => {
    // req.body contains the parsed JSON from the request body.
    // Express's built-in express.json() middleware handles parsing automatically.
    const bookData = req.body;

    // Create the book using our model function.
    // Validation errors (missing title/author) throw ValidationError,
    // which is caught by asyncHandler and passed to our error middleware.
    const newBook = createBook(bookData);

    // Return 201 Created with the newly created book in the response body.
    // 201 is the standard status code for successful resource creation.
    res.status(201).json({
      success: true,
      data: newBook,
    });
  })
);

/**
 * PUT /books/:id
 * Fully updates an existing book. All provided fields replace the current values.
 *
 * REQUEST BODY (JSON) — all fields are optional; only provided fields are updated:
 *   {
 *     "title": "The Hobbit (Updated Title)",  // Optional
 *     "author": "J.R.R. Tolkien",             // Optional
 *     "genre": "Fantasy Adventure",           // Optional
 *     "publishedYear": 1937                    // Optional
 *   }
 *
 * @example
 *   PUT /books/1
 *   Content-Type: application/json
 *
 *   Body:
 *   {
 *     "title": "The Hobbit - Special Edition",
 *     "genre": "Fantasy"
 *   }
 *
 *   Response (200 OK):
 *   {
 *     "success": true,
 *     "data": {
 *       "id": 1,
 *       "title": "The Hobbit - Special Edition",
 *       "author": "J.R.R. Tolkien",
 *       "genre": "Fantasy",
 *       ...
 *     }
 *   }
 */
router.put(
  '/books/:id',
  asyncHandler(async (req, res) => {
    const id = Number(req.params.id);
    const updateData = req.body;

    // Update the book using our model function.
    // If the book doesn't exist, NotFoundError is thrown automatically.
    const updatedBook = updateBook(id, updateData);

    res.status(200).json({
      success: true,
      data: updatedBook,
    });
  })
);

/**
 * DELETE /books/:id
 * Deletes a book by its ID. Returns no content on success.
 *
 * @example
 *   DELETE /books/1
 *
 *   Response (204 No Content):
 *   // Empty body with status code 204
 *
 *   // If the book doesn't exist:
 *   {
 *     "success": false,
 *     "error": {
 *       "type": "NotFoundError",
 *       "message": "Book with id 999 not found"
 *     }
 *   }
 */
router.delete(
  '/books/:id',
  asyncHandler(async (req, res) => {
    const id = Number(req.params.id);

    // Delete the book using our model function.
    // If the book doesn't exist, NotFoundError is thrown automatically.
    deleteBook(id);

    // Return 204 No Content — standard for DELETE operations with no response body.
    // This tells the client the resource was successfully removed.
    res.status(204).send();
  })
);

// Export the router so it can be mounted in our main application
module.exports = router;
```

> **Why `asyncHandler` on every route?** Without it, if `createBook()` or any model function throws an error inside an async route handler, Express won't catch it because promise rejections bypass the normal middleware chain. The `.catch(next)` in `asyncHandler` ensures errors flow into our centralized error middleware regardless of where they originate.

