/**
 * ============================================================================
 * MAIN APPLICATION ENTRY POINT
 * ============================================================================
 *
 * WHY we use a single app.js as the entry point:
 *   - It's the file specified in package.json's "main" field
 *   - It orchestrates all modules (routes, middleware, model) into a working API
 *   - It sets up Express configuration before starting the server
 *
 * ARCHITECTURE FLOW:
 *   1. Import dependencies and our custom modules
 *   2. Create an Express application instance
 *   3. Configure middleware (JSON parsing, error handling)
 *   4. Mount route routers at their respective paths
 *   5. Start the HTTP server on a configured port
 *
 * MIDDLEWARE ORDER matters in Express — it executes in the order it's registered:
 *   express.json() → Our routes → errorHandler (must be last)
 */

const express = require('express');

// Import our route modules
const bookRoutes = require('./routes/books');
const statsRoutes = require('./routes/stats');

// Import our error-handling middleware
const { errorHandler } = require('./middleware/errorHandler');

// Create the Express application instance.
// This is the core object that handles HTTP requests and responses.
const app = express();

// ============================================================================
// MIDDLEWARE CONFIGURATION
// ============================================================================

/**
 * Built-in Express middleware that parses incoming JSON request bodies.
 *
 * WHY this is essential: Without it, req.body would be undefined and we couldn't
 * read POST/PUT request data. This middleware reads the raw request stream,
 * parses JSON, and attaches the result to req.body as a JavaScript object.
 *
 * LIMITATION: It only handles Content-Type: application/json by default.
 * For other content types, you'd need additional parsers (e.g., express.urlencoded).
 */
app.use(express.json());

/**
 * Built-in Express middleware that parses URL-encoded request bodies.
 *
 * WHY we include this: Some API clients send data as form-encoded bodies
 * (Content-Type: application/x-www-form-urlencoded) rather than JSON.
 * This ensures our API can handle both formats.
 */
app.use(express.urlencoded({ extended: true }));

// ============================================================================
// ROUTE MOUNTING
// ============================================================================

/**
 * Mount the book routes at the root path '/'.
 *
 * WHY we mount at '/' instead of '/books':
 *   - Our route definitions already include '/books' in every handler
 *     (e.g., router.get('/books', ...), router.get('/books/:id', ...))
 *   - Mounting at '/' keeps the URLs clean: GET /books, not GET /api/books
 *   - In a larger app, you might mount at '/api/v1' for versioning
 */
app.use('/', bookRoutes);

/**
 * Mount the stats routes.
 * The stats router defines GET /stats, so mounting at '/' gives us GET /stats.
 */
app.use('/', statsRoutes);

// ============================================================================
// ROOT ENDPOINT (HELLO WORLD)
// ============================================================================

/**
 * GET /
 * A simple root endpoint that confirms the API is running.
 *
 * WHY we include this: It provides an easy way to verify the server is up
 * and responding without needing to know any specific endpoint paths.
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'Books REST API is running!',
    endpoints: {
      books: {
        list: 'GET /books',
        getById: 'GET /books/:id',
        create: 'POST /books',
        update: 'PUT /books/:id',
        delete: 'DELETE /books/:id',
      },
      stats: 'GET /stats',
    },
  });
});

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * Register our custom error-handling middleware LAST.
 *
 * WHY it must be last: Express identifies error-handling middleware by its
 * four-parameter signature (error, req, res, next). If registered before
 * routes, it would intercept normal requests incorrectly. By placing it at
 * the end, we ensure all route errors flow through this handler.
 *
 * This middleware catches:
 *   - Errors thrown synchronously in routes (via next(error))
 *   - Async errors caught by our asyncHandler wrapper
 *   - Any unhandled exceptions that bubble up
 */
app.use(errorHandler);

// ============================================================================
// SERVER STARTUP
// ============================================================================

/**
 * Determine the port to run on:
 *   1. Use PORT environment variable if set (common in cloud/deployment)
 *   2. Fall back to 3000 for local development
 *
 * WHY environment variables for configuration:
 *   - Keeps secrets and deployment-specific settings out of source code
 *   - Allows the same code to run in different environments (dev, staging, prod)
 *   - Follows the Twelve-Factor App methodology
 */
const PORT = process.env.PORT || 3000;

/**
 * Start the HTTP server and log a confirmation message.
 *
 * WHY we use arrow function syntax for the callback:
 *   - It's concise and idiomatic in modern JavaScript
 *   - No need for `this` binding (not relevant here, but good practice)
 */
app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`  Books REST API running on port ${PORT}`);
  console.log(`  Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`========================================`);
  console.log(`\nTest the API with these commands:`);
  console.log(`  curl http://localhost:${PORT}/`);
  console.log(`  curl http://localhost:${PORT}/books`);
  console.log(`  curl -X POST http://localhost:${PORT}/books \\`);
  console.log(`    -H "Content-Type: application/json" \\`);
  console.log(`    -d '{"title":"The Hobbit","author":"J.R.R. Tolkien","genre":"Fantasy","publishedYear":1937}'`);
  console.log(`\nPress Ctrl+C to stop the server.\n`);
});

// Export the app for testing purposes (allows importing in test suites)
module.exports = app;
```

> **Why mount routes at `'/'`?** Our route files already define paths like `/books`, `/books/:id`, etc. If we mounted `bookRoutes` at `/api`, the URLs would become `/api/books`. By mounting at `/`, we keep URLs simple: `/books`. In production apps, you'd typically use `/api/v1` for versioning.

