## Arquivo: `src/data/store.js`

```javascript
/**
 * Módulo de armazenamento em memória para a API de livros.
 *
 * POR QUE USAR UM ARRAY EM MEMÓRIA?
 * ----------------------------------
 * Para este exemplo educacional, um array em memória é suficiente porque:
 *   1. Não requer configuração de banco de dados (simplicidade)
 *   2. Permite focar nos conceitos de REST e Express
 *   3. Operações são O(1) para push/pop e O(n) para busca — aceitável
 *      para poucos registros em um exemplo
 *
 * Em produção, substituiríamos este módulo por uma camada de acesso a dados
 * (DAO) que usaria MongoDB, PostgreSQL, etc., mantendo a mesma interface.
 *
 * POR QUE USAR UM OBJETO + ARRAY?
 * ---------------------------------
 * Armazenamos os livros em um array (`books`) para preservar a ordem de
 * inserção e facilitar iterações. Usamos IDs numéricos autoincrementais
 * porque:
 *   - São simples e eficientes para comparação
 *   - Evitam colisões de strings (UUIDs são overkill para este exemplo)
 *   - Facilitam o entendimento do código por iniciantes
 */

// Estado mutável da aplicação — em produção, isso seria injetado via DI.
const books = [];

// Contador autoincremental para geração de IDs únicos.
// Usamos uma variável externa porque números são primitivos imutáveis;
// precisamos de referência mutável para incrementar.
let nextId = 1;

/**
 * Retorna todos os livros armazenados.
 *
 * @returns {Array<Object>} Lista de objetos livro
 */
function getAllBooks() {
  return books;
}

/**
 * Busca um livro pelo seu ID numérico.
 *
 * @param {number} id - ID do livro a ser buscado
 * @returns {Object|null} Livro encontrado ou null se não existir
 */
function getBookById(id) {
  // find() retorna o primeiro elemento que satisfaz a função de teste,
  // ou undefined se nenhum elemento corresponder.
  return books.find((book) => book.id === id) || null;
}

/**
 * Adiciona um novo livro ao armazenamento.
 *
 * @param {Object} bookData - Dados do livro (sem ID — será gerado automaticamente)
 * @returns {Object} O livro criado com seu ID atribuído
 */
function createBook(bookData) {
  const newBook = {
    id: nextId++,          // Gera ID único e incrementa o contador
    title: bookData.title,
    author: bookData.author,
    isbn: bookData.isbn || null,
    year: bookData.year || null,
    genre: bookData.genre || null,
    createdAt: new Date().toISOString(), // ISO 8601 para consistência de fuso
    updatedAt: new Date().toISOString(),
  };

  books.push(newBook); // O(1) — adiciona ao final do array
  return newBook;
}

/**
 * Atualiza um livro existente pelo ID.
 *
 * @param {number} id - ID do livro a ser atualizado
 * @param {Object} updates - Campos a serem atualizados (partial update)
 * @returns {Object|null} Livro atualizado ou null se não encontrado
 */
function updateBook(id, updates) {
  const index = books.findIndex((book) => book.id === id);

  if (index === -1) {
    return null; // Livro não encontrado
  }

  // Atualiza apenas os campos fornecidos (partial update / PATCH semantics).
  // Isso permite que o cliente envie apenas os campos que deseja alterar.
  books[index] = {
    ...books[index],           // Espalha os campos existentes
    ...updates,                // Sobrescreve com os novos valores
    id: books[index].id,       // Garante que o ID não seja sobrescrito
    createdAt: books[index].createdAt, // Preserva a data de criação
    updatedAt: new Date().toISOString(), // Atualiza timestamp de modificação
  };

  return books[index];
}

/**
 * Remove um livro pelo ID.
 *
 * @param {number} id - ID do livro a ser removido
 * @returns {boolean} true se removido, false se não encontrado
 */
function deleteBook(id) {
  const index = books.findIndex((book) => book.id === id);

  if (index === -1) {
    return false;
  }

  // splice() remove o elemento no índice e ajusta o array.
  // Complexidade O(n) porque precisa realocar elementos após a remoção.
  books.splice(index, 1);
  return true;
}

/**
 * Calcula estatísticas agregadas sobre os livros armazenados.
 *
 * @returns {Object} Estatísticas: total, por gênero, média de anos, autores únicos
 */
function getStats() {
  const total = books.length;

  if (total === 0) {
    return {
      total,
      averageYear: null,
      uniqueAuthors: 0,
      genres: {},
      newestBook: null,
      oldestBook: null,
    };
  }

  // Agrupamento por gênero usando reduce — padrão funcional para agregação.
  const genres = books.reduce((acc, book) => {
    const genre = book.genre || 'Sem gênero';
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  // Cálculo da média de anos de publicação.
  const yearsWithData = books.filter((b) => b.year !== null && b.year !== undefined);
  const averageYear =
    yearsWithData.length > 0
      ? yearsWithData.reduce((sum, b) => sum + b.year, 0) / yearsWithData.length
      : null;

  // Autores únicos usando Set para deduplicação automática.
  const uniqueAuthors = new Set(books.map((b) => b.author)).size;

  // Livros mais novo e mais antigo com base no createdAt.
  const sortedByDate = [...books].sort(
    (a, b) => new Date(a.createdAt) - new Date(b.createdAt)
  );

  return {
    total,
    averageYear: averageYear ? Math.round(averageYear * 100) / 100 : null,
    uniqueAuthors,
    genres,
    newestBook: sortedByDate[sortedByDate.length - 1] || null,
    oldestBook: sortedByDate[0] || null,
  };
}

module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

> **Explicação detalhada:** O armazenamento em memória é o choice mais simples para um exemplo educacional. Usamos `let nextId = 1` como contador porque IDs numéricos são mais legíveis que UUIDs para fins didáticos. A função `updateBook` implementa *partial update* (semântica PATCH) usando spread operator (`...`), permitindo que o cliente envie apenas os campos que deseja alterar. O timestamp `updatedAt` é atualizado a cada modificação, seguindo a convenção de auditoria comum em APIs reais.

