## Arquivo: `src/middleware/errorHandler.js`

```javascript
/**
 * Middleware centralizado de tratamento de erros.
 *
 * POR QUE UM MIDDLEWARE DE ERRO SEPARADO?
 * ----------------------------------------
 * Em Express, middlewares de erro têm ASSINATURA DIFERENTE dos normais:
 *   (err, req, res, next) — nota o parâmetro 'err' adicional.
 *
 * Ao centralizar o tratamento em um único middleware, conseguimos:
 *   1. Padronizar a resposta de erro para todos os tipos de falha
 *   2. Separar lógica de negócio da lógica de apresentação
 *   3. Logar erros de forma consistente
 *   4. Diferenciar erros operacionais (esperados) de bugs (inesperados)
 *
 * A convenção REST pede que respostas de erro usem códigos HTTP apropriados
 * e corpos JSON com campos estruturados (message, code, timestamp).
 */

/**
 * Middleware de tratamento de erros para a API.
 *
 * @param {Error} err - Objeto de erro capturado
 * @param {Object} req - Objeto de requisição do Express
 * @param {Object} res - Objeto de resposta do Express
 * @param {Function} next - Função para passar ao próximo middleware
 */
function errorHandler(err, req, res, next) {
  // Determina o statusCode: usa o do erro personalizado ou 500 como fallback.
  const statusCode = err.statusCode || 500;

  // Para erros operacionais (previsíveis), logamos apenas informações úteis.
  // Para erros não operacionais (bugs), logamos o stack trace completo.
  if (err.isOperational) {
    console.log(`[WARN] ${err.errorCode}: ${err.message}`);
  } else {
    // Erro de programação — algo inesperado aconteceu.
    console.error(`[ERROR] ${err.name || 'Error'}: ${err.message}`);
    console.error(err.stack);
  }

  // Construímos a resposta de erro com formato consistente.
  const errorResponse = {
    success: false,
    error: {
      message: err.message,
      statusCode,
      errorCode: err.errorCode || 'INTERNAL_ERROR',
    },
    timestamp: new Date().toISOString(),
  };

  // Para erros de validação, incluímos detalhes dos campos problemáticos.
  if (err.errors && Array.isArray(err.errors)) {
    errorResponse.error.details = err.errors;
  }

  // Em ambiente de desenvolvimento, incluímos o stack trace para debugging.
  // Em produção, isso seria omitido por segurança (não vazar internals).
  if (process.env.NODE_ENV !== 'production' && !err.isOperational) {
    errorResponse.error.stack = err.stack;
  }

  res.status(statusCode).json(errorResponse);
}

module.exports = errorHandler;
```

> **Explicação:** O middleware de erro tem 4 parâmetros — o quarto (`next`) é obrigatório para que o Express o reconheça como middleware de erro. A distinção entre `isOperational` e erros não operacionais segue a prática recomendada do Node.js production patterns: erros operacionais (como "livro não encontrado") são normais e não indicam bugs; erros não operacionais (como "cannot read property of undefined") indicam problemas no código que precisam ser corrigidos.

