```javascript
/**
 * Rotas da API de livros — implementa todos os endpoints REST.
 *
 * POR QUE USAR EXPRESS.Router()?
 * -------------------------------
 * O Express.Router() permite encapsular rotas em módulos separados, o que:
 *   1. Mantém o código organizado e modular
 *   2. Facilita testes unitários de cada conjunto de rotas
 *   3. Permite aplicar middlewares específicos por grupo de rotas
 *   4. Segue a convenção de separação de responsabilidades (SoC)
 *
 * Cada rota segue o padrão REST:
 *   - GET    /books       → Listar todos (com filtragem opcional)
 *   - GET    /books/:id   → Obter um específico
 *   - POST   /books       → Criar novo
 *   - PUT    /books/:id   → Atualizar completo
 *   - DELETE /books/:id   → Remover
 *
 * POR QUE USAR async/await?
 * --------------------------
 * Async/await torna o código assíncrono mais legível que callbacks ou
 * promessas encadeadas (.then()). Mesmo que o store atual seja síncrono,
 * usamos async/await para:
 *   1. Preparar a arquitetura para futuras operações assíncronas (DB)
 *   2. Manter consistência com padrões modernos do ecossistema Node.js
 *   3. Facilitar o uso de try/catch para tratamento de erros
 */

const express = require('express');
const router = express.Router();

// Importamos o store e as classes de erro deste módulo.
const store = require('../data/store');
const { AppError, ValidationError, NotFoundError } = require('../errors/AppError');

// ============================================================================
// CONSTANTES DE VALIDAÇÃO
// ============================================================================

/**
 * Mensagens de validação padronizadas para reutilização em múltiplos lugares.
 */
const VALIDATION_MESSAGES = {
  MISSING_ID: 'ID é obrigatório',
  INVALID_ID: 'ID deve ser um número inteiro positivo',
  MISSING_TITLE: 'Título é obrigatório',
  MISSING_AUTHOR: 'Autor é obrigatório',
  INVALID_YEAR: 'Ano deve ser um número inteiro entre 1000 e 2100',
  TITLE_MIN_LENGTH: 'Título deve ter pelo menos 2 caracteres',
  TITLE_MAX_LENGTH: 'Título não pode exceder 300 caracteres',
  AUTHOR_MIN_LENGTH: 'Autor deve ter pelo menos 1 caractere',
  AUTHOR_MAX_LENGTH: 'Autor não pode exceder 200 caracteres',
};

// ============================================================================
// FUNÇÕES AUXILIARES (PRIVATE HELPERS)
// ============================================================================

/**
 * Valida os dados de entrada para criação ou atualização de livro.
 *
 * @param {Object} data - Dados a serem validados
 * @param {boolean} isUpdate - Se true, campos obrigatórios são opcionais (PATCH)
 * @returns {Array<Object>} Array de erros de validação (vazio se válido)
 */
function validateBookData(data, isUpdate = false) {
  const errors = [];

  // Em atualização parcial (PUT com poucos campos), apenas validamos os campos presentes.
  if (!isUpdate) {
    // Para criação, título e autor são obrigatórios.
    if (!data.title || typeof data.title !== 'string') {
      errors.push({ field: 'title', message: VALIDATION_MESSAGES.MISSING_TITLE });
    }
    if (!data.author || typeof data.author !== 'string') {
      errors.push({ field: 'author', message: VALIDATION_MESSAGES.MISSING_AUTHOR });
    }
  }

  // Validações que se aplicam tanto a criação quanto atualização.
  if (data.title !== undefined) {
    if (typeof data.title !== 'string' || data.title.trim().length < 2) {
      errors.push({ field: 'title', message: VALIDATION_MESSAGES.TITLE_MIN_LENGTH });
    }
    if (data.title.length > 300) {
      errors.push({ field: 'title', message: VALIDATION_MESSAGES.TITLE_MAX_LENGTH });
    }
  }

  if (data.author !== undefined) {
    if (typeof data.author !== 'string' || data.author.trim().length < 1) {
      errors.push({ field: 'author', message: VALIDATION_MESSAGES.AUTHOR_MIN_LENGTH });
    }
    if (data.author.length > 200) {
      errors.push({ field: 'author', message: VALIDATION_MESSAGES.AUTHOR_MAX_LENGTH });
    }
  }

  // Validação opcional do ano.
  if (data.year !== undefined && data.year !== null) {
    const year = Number(data.year);
    if (!Number.isInteger(year) || year < 1000 || year > 2100) {
      errors.push({ field: 'year', message: VALIDATION_MESSAGES.INVALID_YEAR });
    }
  }

  return errors;
}

/**
 * Valida se o ID é um número inteiro positivo válido.
 *
 * @param {*} id - Valor do ID a ser validado
 * @returns {string|null} Mensagem de erro ou null se válido
 */
function validateId(id) {
  const num = Number(id);
  if (!Number.isInteger(num) || num <= 0) {
    return VALIDATION_MESSAGES.INVALID_ID;
  }
  return null;
}

/**
 * Filtra a lista de livros com base nos parâmetros de query.
 *
 * @param {Array<Object>} books - Lista completa de livros
 * @param {Object} queryParams - Parâmetros da query string
 * @returns {Array<Object>} Lista filtrada
 */
function filterBooks(books, queryParams) {
  let result = [...books]; // Criamos cópia para não mutar o array original

  // Filtragem por gênero (case-insensitive).
  if (queryParams.genre) {
    const genreLower = queryParams.genre.toLowerCase();
    result = result.filter((book) =>
      book.genre && book.genre.toLowerCase() === genreLower
    );
  }

  // Filtragem por autor (parcial, case-insensitive).
  if (queryParams.author) {
    const authorLower = queryParams.author.toLowerCase();
    result = result.filter((book) =>
      book.author && book.author.toLowerCase().includes(authorLower)
    );
  }

  // Filtragem por ano (igualdade exata).
  if (queryParams.year) {
    const year = Number(queryParams.year);
    if (Number.isInteger(year)) {
      result = result.filter((book) => book.year === year);
    }
  }

  // Ordenação: mais recente primeiro por padrão.
  if (queryParams.sort === 'year_asc') {
    result.sort((a, b) => (a.year || 0) - (b.year || 0));
  } else if (queryParams.sort === 'title') {
    result.sort((a, b) => a.title.localeCompare(b.title));
  }

  // Paginação simples com limit e offset.
  const limit = Math.min(Math.max(Number(queryParams.limit) || 10, 1), 100);
  const offset = Math.max(Number(queryParams.offset) || 0, 0);
  result = result.slice(offset, offset + limit);

  return result;
}

// ============================================================================
// GET /books — Listar todos os livros com filtragem e paginação
// ============================================================================

/**
 * @route   GET /books
 * @desc    Lista todos os livros com suporte a filtragem e paginação
 * @access  Public
 *
 * @query {string} [genre]      - Filtrar por gênero (ex: ?genre=ficcao)
 * @query {string} [author]     - Filtrar por autor (busca parcial, ex: ?author=tolkien)
 * @query {number} [year]       - Filtrar por ano de publicação
 * @query {string} [sort]       - Ordenação: 'title' ou 'year_asc'
 * @query {number} [limit=10]   - Número máximo de resultados (max 100)
 * @query {number} [offset=0]   - Posição inicial para paginação
 *
 * @example curl "http://localhost:3000/books?genre=ficcao&limit=5"
 * @example curl "http://localhost:3000/books?author=tolkien&sort=title"
 * @example curl "http://localhost:3000/books?year=1954&limit=10&offset=0"
 */
router.get('/books', async (req, res, next) => {
  try {
    // Obtemos todos os livros do store.
    const allBooks = store.getAllBooks();

    // Aplicamos a filtragem com base nos parâmetros da query string.
    const filteredBooks = filterBooks(allBooks, req.query);

    // Retornamos a lista com metadados de paginação.
    res.json({
      success: true,
      data: {
        books: filteredBooks,
        pagination: {
          total: allBooks.length,           // Total geral (antes da paginação)
          limit: Number(req.query.limit) || 10,
          offset: Number(req.query.offset) || 0,
          hasMore: (Number(req.query.offset) || 0) + filteredBooks.length < allBooks.length,
        },
      },
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    next(error); // Passa o erro para o middleware de tratamento
  }
});

// ============================================================================
// GET /books/stats — Estatísticas da coleção de livros
// ============================================================================

/**
 * @route   GET /books/stats
 * @desc    Retorna estatísticas agregadas sobre a coleção de livros
 * @access  Public
 *
 * @example curl "http://localhost:3000/books/stats"
 * @example Resposta: { success: true, data: { total: 5, averageYear: 1998, ... } }
 */
router.get('/books/stats', async (req, res, next) => {
  try {
    const stats = store.getStats();

    res.json({
      success: true,
      data: stats,
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// GET /books/:id — Obter um livro específico pelo ID
// ============================================================================

/**
 * @route   GET /books/:id
 * @desc    Busca um livro pelo seu ID numérico
 * @access  Public
 *
 * @param {number} id - ID do livro (path parameter)
 *
 * @example curl "http://localhost:3000/books/1"
 * @example Resposta: { success: true, data: { id: 1, title: "...", ... } }
 */
router.get('/books/:id', async (req, res, next) => {
  try {
    // Validamos o ID antes de fazer a busca.
    const idError = validateId(req.params.id);
    if (idError) {
      throw new ValidationError(idError, [{ field: 'id', message: idError }]);
    }

    const id = Number(req.params.id);
    const book = store.getBookById(id);

    // Se o livro não existe, lançamos NotFoundError (404).
    if (!book) {
      throw new NotFoundError('Livro', id);
    }

    res.json({
      success: true,
      data: book,
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// POST /books — Criar um novo livro
// ============================================================================

/**
 * @route   POST /books
 * @desc    Cria um novo livro na coleção
 * @access  Public
 *
 * @body {string}  title     - Título do livro (obrigatório, min 2 chars)
 * @body {string}  author    - Autor do livro (obrigatório, min 1 char)
 * @body {string}  [isbn]    - ISBN do livro (opcional)
 * @body {number}  [year]    - Ano de publicação (opcional, 1000-2100)
 * @body {string}  [genre]   - Gênero literário (opcional)
 *
 * @example curl -X POST http://localhost:3000/books \
 *            -H "Content-Type: application/json" \
 *            -d '{"title":"O Senhor dos Anéis","author":"J.R.R. Tolkien","year":1954,"genre":"Fantasia"}'
 */
router.post('/books', async (req, res, next) => {
  try {
    const { title, author, isbn, year, genre } = req.body;

    // Validamos os dados de entrada.
    const validationErrors = validateBookData({ title, author, isbn, year, genre }, false);
    if (validationErrors.length > 0) {
      throw new ValidationError('Dados inválidos para criação do livro', validationErrors);
    }

    // Criamos o livro no store.
    const newBook = store.createBook({ title, author, isbn, year, genre });

    // Retornamos 201 Created com o recurso criado no corpo da resposta.
    // A convenção REST recomenda usar 201 para criação de recursos.
    res.status(201).json({
      success: true,
      data: newBook,
      message: 'Livro criado com sucesso',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// PUT /books/:id — Atualizar um livro existente
// ============================================================================

/**
 * @route   PUT /books/:id
 * @desc    Atualiza completamente um livro existente pelo ID
 * @access  Public
 *
 * @param {number} id        - ID do livro a ser atualizado
 * @body {string}  [title]   - Novo título (opcional)
 * @body {string}  [author]  - Novo autor (opcional)
 * @body {string}  [isbn]    - Novo ISBN (opcional)
 * @body {number}  [year]    - Novo ano de publicação (opcional)
 * @body {string}  [genre]   - Novo gênero (opcional)
 *
 * @example curl -X PUT http://localhost:3000/books/1 \
 *            -H "Content-Type: application/json" \
 *            -d '{"title":"Novo Título","year":2020}'
 */
router.put('/books/:id', async (req, res, next) => {
  try {
    // Validamos o ID.
    const idError = validateId(req.params.id);
    if (idError) {
      throw new ValidationError(idError, [{ field: 'id', message: idError }]);
    }

    const id = Number(req.params.id);

    // Verificamos se o livro existe antes de atualizar.
    const existingBook = store.getBookById(id);
    if (!existingBook) {
      throw new NotFoundError('Livro', id);
    }

    // Validamos apenas os campos que estão sendo enviados (partial update).
    const validationErrors = validateBookData(req.body, true);
    if (validationErrors.length > 0) {
      throw new ValidationError('Dados inválidos para atualização do livro', validationErrors);
    }

    // Atualizamos o livro. O store preserva campos não enviados.
    const updatedBook = store.updateBook(id, req.body);

    res.json({
      success: true,
      data: updatedBook,
      message: 'Livro atualizado com sucesso',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// DELETE /books/:id — Excluir um livro
// ============================================================================

/**
 * @route   DELETE /books/:id
 * @desc    Remove um livro da coleção pelo ID
 * @access  Public
 *
 * @param {number} id - ID do livro a ser removido
 *
 * @example curl -X DELETE http://localhost:3000/books/1
 * @example Resposta: { success: true, message: 'Livro excluído com sucesso' }
 */
router.delete('/books/:id', async (req, res, next) => {
  try {
    // Validamos o ID.
    const idError = validateId(req.params.id);
    if (idError) {
      throw new ValidationError(idError, [{ field: 'id', message: idError }]);
    }

    const id = Number(req.params.id);

    // Verificamos se o livro existe antes de tentar excluir.
    const existingBook = store.getBookById(id);
    if (!existingBook) {
      throw new NotFoundError('Livro', id);
    }

    // Removemos o livro do store.
    const deleted = store.deleteBook(id);

    // Retornamos 200 OK com confirmação.
    // Alguns frameworks usam 204 No Content para DELETE, mas incluir
    // uma mensagem de confirmação é mais amigável para iniciantes.
    res.json({
      success: true,
      message: 'Livro excluído com sucesso',
      data: { id },
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    next(error);
  }
});

module.exports = router;
```

> **Explicação detalhada:** Cada rota segue o padrão REST rigorosamente. Usamos `async/await` com `try/catch` porque: (1) prepara a arquitetura para operações assíncronas futuras, (2) permite tratamento centralizado de erros via `next(error)`, e (3) torna o código mais legível que callbacks aninhados. A validação é feita em camadas — primeiro no route handler, depois no store. O helper `filterBooks` implementa filtragem por gênero, autor e ano, além de ordenação e paginação, demonstrando como expor funcionalidades avançadas via query parameters.

