## Arquivo: `src/app.js`

```javascript
/**
 * Configuração da aplicação Express.
 *
 * POR QUE SEPARAR app.js DO index.js?
 * ------------------------------------
 * Separar a configuração do Express (app.js) do ponto de entrada (index.js)
 * segue o princípio de separação de responsabilidades:
 *   - app.js: configura middleware, rotas e comportamento da aplicação
 *   - index.js: apenas inicia o servidor na porta correta
 *
 * Isso facilita testes unitários (podemos testar app sem iniciar o servidor)
 * e mantém o código organizado conforme a aplicação cresce.
 */

const express = require('express');
const booksRouter = require('./routes/books');
const notFoundMiddleware = require('./middleware/notFound');
const errorHandler = require('./middleware/errorHandler');

// Cria a instância do aplicativo Express.
const app = express();

// ============================================================================
// MIDDLEWARE GLOBAIS
// ============================================================================

/**
 * Middleware para parsing de JSON no corpo das requisições.
 *
 * Limitamos o tamanho para 10kb para prevenir ataques de negação de serviço
 * (DoS) via corpos gigantes. Em produção, ajuste conforme necessário.
 */
app.use(express.json({ limit: '10kb' }));

/**
 * Middleware para parsing de URL-encoded (para formulários HTML).
 * Também limitamos o tamanho para segurança.
 */
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================================================
// ROTAS
// ============================================================================

/**
 * Rota raiz da API com mensagem de boas-vindas.
 * Útil para verificar se a API está respondendo.
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'API de Livros — exemplo educacional Node.js + Express',
    endpoints: {
      docs: 'Veja os endpoints abaixo',
      books: 'GET /books, POST /books, GET /books/:id, PUT /books/:id, DELETE /books/:id',
      stats: 'GET /books/stats',
    },
    timestamp: new Date().toISOString(),
  });
});

// Registra as rotas de livros sob o prefixo /api/v1/books.
// O prefixo /api/v1 segue a convenção de versionamento de APIs,
// permitindo futuras evoluções sem quebrar clientes existentes.
app.use('/api/v1/books', booksRouter);

// ============================================================================
// MIDDLEWARE DE TRATAMENTO (ORDEM IMPORTA!)
// ============================================================================

/**
 * Middleware 404 — deve vir DEPOIS de todas as rotas.
 * Captura requisições para URLs inexistentes.
 */
app.use(notFoundMiddleware);

/**
 * Middleware de tratamento de erros — deve ser o ÚLTIMO middleware.
 * Express identifica middlewares de erro pela assinatura (4 parâmetros).
 */
app.use(errorHandler);

module.exports = app;
```

> **Explicação:** A ordem dos middlewares é crítica no Express. `express.json()` e `express.urlencoded()` vêm primeiro para parsing do corpo. As rotas vêm em seguida. O middleware 404 vem depois das rotas (para capturar apenas URLs não tratadas). O middleware de erro é o último (para capturar erros de qualquer lugar). O versionamento `/api/v1/` segue a convenção da indústria — se precisarmos mudar a API no futuro, criamos `/api/v2/` sem quebrar clientes existentes.

