 * Este arquivo é minimalista porque toda a configuração está em app.js.
 * Sua única responsabilidade é iniciar o servidor HTTP na porta configurada.
 */

const app = require('./app');

// Porta padrão: 3000 para desenvolvimento, pode ser sobrescrita por variável de ambiente.
const PORT = process.env.PORT || 3000;

// Inicia o servidor e faz log do endereço de acesso.
const server = app.listen(PORT, () => {
  console.log(`
╔══════════════════════════════════════════════════════════╗
║     API de Livros — Servidor rodando com sucesso!        ║
║                                                          ║
║   📍 Endereço:    http://localhost:${PORT}                  ║
║   📚 Endpoints:   /api/v1/books                          ║
║   📊 Estatísticas: /api/v1/books/stats                   ║
║                                                          ║
║   💡 Dica: Use 'npm run dev' para reinício automático    ║
╚══════════════════════════════════════════════════════════╝
  `);
});

// Tratamento de erros não capturados (uncaught exceptions).
process.on('uncaughtException', (err) => {
  console.error('[FATAL] Uncaught Exception:', err.message);
  console.error(err.stack);
  // Em produção, faríamos shutdown graceful aqui.
  process.exit(1);
});

// Tratamento de promessas rejeitadas não capturadas.
process.on('unhandledRejection', (err) => {
  console.error('[FATAL] Unhandled Rejection:', err.message);
  console.error(err.stack);
  process.exit(1);
});

module.exports = server;
