```javascript
/**
 * ============================================================================
 * BOOK ROUTES — CRUD Operations
 * ============================================================================
 *
 * WHY separate route file?
 *   - Keeps the main app.js lean and focused on wiring, not business logic.
 *   - Makes it easy to add more resources (authors, genres) as sibling files.
 *
 * DATA STRUCTURE CHOICE: In-Memory Array of Objects
 *   - Each book is a plain object with properties: id, title, author, year, genre.
 *   - An array is used because order matters (insertion order ≈ chronological).
 *   - IDs are auto-incrementing integers for simplicity; in production you'd
 *     use UUIDs or an ObjectId from MongoDB.
 *
 * REST CONVENTIONS FOLLOWED:
 *   - GET    /books          → list all (with optional query filters)
 *   - GET    /books/:id      → retrieve one by ID
 *   - POST   /books          → create a new book
 *   - PUT    /books/:id      → fully replace an existing book
 *   - DELETE /books/:id      → remove a book
 *
 * ASYNC/AWAIT PATTERN:
 *   - Every handler is `async` so we can use `await` for any future DB calls.
 *   - Even though this example uses synchronous array operations, keeping the
 *     async wrapper means swapping in a real database later requires zero
 *     route-level changes.
 */

const { NotFoundError, ValidationError } = require('../errors/CustomError');

// --------------------------------------------------------------------------
// IN-MEMORY STORAGE
// --------------------------------------------------------------------------
/**
 * The "database" — an array of book objects.
 *
 * WHY an array and not a Map or plain object?
 *   - Arrays preserve insertion order (useful for listing).
 *   - They support `.findIndex()` and `.splice()` which map naturally to
 *     CRUD operations on a single item.
 *   - For a real app, replace this variable with a DB connection; the rest
 *     of the code remains unchanged because it only reads/writes `books`.
 */
const books = [
  { id: 1, title: 'The Great Gatsby', author: 'F. Scott Fitzgerald', year: 1925, genre: 'Fiction' },
  { id: 2, title: 'To Kill a Mockingbird', author: 'Harper Lee', year: 1960, genre: 'Fiction' },
  { id: 3, title: 'A Brief History of Time', author: 'Stephen Hawking', year: 1988, genre: 'Science' },
];

/**
 * Current auto-increment counter. Starts at 4 so the next created book gets id 4.
 * In production, use a DB sequence or UUID generator instead.
 */
let nextId = 4;

// --------------------------------------------------------------------------
// VALIDATION HELPERS
// --------------------------------------------------------------------------
/**
 * Validates that a book object has all required fields with correct types.
 *
 * @param {object} book — The book data to validate.
 * @returns {string|null} — Error message string if invalid, null if valid.
 */
function validateBook(book) {
  const errors = [];

  // Title is required and must be a non-empty string.
  if (!book.title || typeof book.title !== 'string' || book.title.trim() === '') {
    errors.push('Title is required and must be a non-empty string.');
  }

  // Author is required and must be a non-empty string.
  if (!book.author || typeof book.author !== 'string' || book.author.trim() === '') {
    errors.push('Author is required and must be a non-empty string.');
  }

  // Year, if provided, must be a positive integer between 0 and current year + 1.
  if (book.year !== undefined && book.year !== null) {
    const year = Number(book.year);
    const currentYear = new Date().getFullYear();
    if (!Number.isInteger(year) || year < 0 || year > currentYear + 1) {
      errors.push('Year must be a positive integer not greater than the current year.');
    }
  }

  // Genre, if provided, must be a non-empty string.
  if (book.genre !== undefined && book.genre !== null) {
    if (typeof book.genre !== 'string' || book.genre.trim() === '') {
      errors.push('Genre must be a non-empty string.');
    }
  }

  return errors.length > 0 ? errors.join(' ') : null;
}

// --------------------------------------------------------------------------
// GET /books — List all books (with optional filtering)
// --------------------------------------------------------------------------
/**
 * Returns an array of all books. Supports optional query parameters for
 * filtering by `author`, `genre`, or `year`.
 *
 * @example
 *   // All books:
 *   GET /books
 *
 *   // Books by a specific author:
 *   GET /books?author=Harper%20Lee
 *
 *   // Books in a specific genre published after a year:
 *   GET /books?genre=Fiction&year=1950
 *
 * @param {import('express').Request} req — Express request object.
 *   Query params: author (string), genre (string), year (integer, min).
 * @param {import('express').Response} res — Express response object.
 */
async function getAllBooks(req, res) {
  // Destructure query parameters with defaults for clarity.
  const { author, genre, year } = req.query;

  // Start with the full array, then apply filters one at a time.
  let result = books;

  // Filter by author (case-insensitive partial match).
  if (author) {
    const authorLower = author.toLowerCase();
    result = result.filter((book) => book.author.toLowerCase().includes(authorLower));
  }

  // Filter by genre (exact match, case-insensitive).
  if (genre) {
    const genreLower = genre.toLowerCase();
    result = result.filter((book) => book.genre.toLowerCase() === genreLower);
  }

  // Filter by minimum year (year >= query value).
  if (year) {
    const minYear = Number(year);
    if (!isNaN(minYear)) {
      result = result.filter((book) => book.year >= minYear);
    }
  }

  // Return the (possibly filtered) list with a 200 OK status.
  res.status(200).json({
    success: true,
    count: result.length,
    data: result,
  });
}

// --------------------------------------------------------------------------
// GET /books/:id — Get a single book by ID
// --------------------------------------------------------------------------
/**
 * Retrieves one book whose `id` matches the URL parameter.
 *
 * @example
 *   // Get book with id = 1:
 *   GET /books/1
 *
 * @param {import('express').Request} req — Express request object.
 *   Params: id (string, will be coerced to integer).
 * @param {import('express').Response} res — Express response object.
 * @param {import('express').NextFunction} next — Passes errors to errorHandler.
 */
async function getBookById(req, res, next) {
  // Coerce the route parameter from string to integer.
  const id = Number(req.params.id);

  // .find() returns the first matching element or undefined.
  const book = books.find((b) => b.id === id);

  if (!book) {
    // Delegate to our custom NotFoundError so the error handler formats it.
    return next(new NotFoundError('Book', id));
  }

  res.status(200).json({
    success: true,
    data: book,
  });
}

// --------------------------------------------------------------------------
// POST /books — Create a new book
// --------------------------------------------------------------------------
/**
 * Creates a new book from the request body and appends it to storage.
 * Returns the created book with HTTP 201 (Created).
 *
 * @example Request body:
 *   { "title": "1984", "author": "George Orwell", "year": 1949, "genre": "Dystopian" }
 *
 * @param {import('express').Request} req — Express request object.
 *   Body: title (string), author (string), year (integer), genre (string).
 * @param {import('express').Response} res — Express response object.
 * @param {import('express').NextFunction} next — Passes errors to errorHandler.
 */
async function createBook(req, res, next) {
  const body = req.body;

  // Validate the incoming data before touching storage.
  const validationError = validateBook(body);
  if (validationError) {
    return next(new ValidationError(validationError));
  }

  // Assign a new auto-incremented ID.
  const id = nextId++;

  // Build the book object. Omit undefined fields to keep records clean.
  const newBook = {
    id,
    title: body.title.trim(),
    author: body.author.trim(),
    year: body.year !== undefined ? Number(body.year) : null,
    genre: body.genre !== undefined ? body.genre.trim() : null,
  };

  // Append to the in-memory array. In a real DB this would be an INSERT.
  books.push(newBook);

  // 201 Created is the standard status for resource creation.
  res.status(201).json({
    success: true,
    data: newBook,
  });
}

// --------------------------------------------------------------------------
// PUT /books/:id — Fully update an existing book
// --------------------------------------------------------------------------
/**
 * Replaces all fields of an existing book with the values from the request body.
 * Returns the updated book with HTTP 200 OK.
 *
 * NOTE: This is a FULL replacement (not a patch). Any field not provided will
 * be set to null/undefined, unlike PATCH which would preserve existing values.
 *
 * @example Request body:
 *   { "title": "The Great Gatsby (Updated)", "author": "F. Scott Fitzgerald", "year": 1925 }
 *
 * @param {import('express').Request} req — Express request object.
 *   Params: id (string). Body: title, author, year, genre.
 * @param {import('express').Response} res — Express response object.
 * @param {import('express').NextFunction} next — Passes errors to errorHandler.
 */
async function updateBook(req, res, next) {
  const id = Number(req.params.id);

  // Find the book first so we can return a clear error if it's missing.
  const bookIndex = books.findIndex((b) => b.id === id);
  if (bookIndex === -1) {
    return next(new NotFoundError('Book', id));
  }

  // Validate the incoming data.
  const validationError = validateBook(req.body);
  if (validationError) {
    return next(new ValidationError(validationError));
  }

  // Build the updated object, preserving the original ID.
  const updatedBook = {
    id,
    title: req.body.title.trim(),
    author: req.body.author.trim(),
    year: req.body.year !== undefined ? Number(req.body.year) : null,
    genre: req.body.genre !== undefined ? req.body.genre.trim() : null,
  };

  // Replace the old entry in-place. In a real DB this would be an UPDATE.
  books[bookIndex] = updatedBook;

  res.status(200).json({
    success: true,
    data: updatedBook,
  });
}

// --------------------------------------------------------------------------
// DELETE /books/:id — Delete a book by ID
// --------------------------------------------------------------------------
/**
 * Removes a book from storage and returns HTTP 204 No Content.
 * A 204 response has no body, which is the standard for successful deletions.
 *
 * @example
 *   // Delete book with id = 2:
 *   DELETE /books/2
 *
 * @param {import('express').Request} req — Express request object.
 *   Params: id (string).
 * @param {import('express').Response} res — Express response object.
 * @param {import('express').NextFunction} next — Passes errors to errorHandler.
 */
async function deleteBook(req, res, next) {
  const id = Number(req.params.id);

  // .findIndex() returns -1 if not found (faster than .find() + comparison).
  const bookIndex = books.findIndex((b) => b.id === id);
  if (bookIndex === -1) {
    return next(new NotFoundError('Book', id));
  }

  // .splice(index, 1) removes exactly one element at the given index.
  // In a real DB this would be a DELETE statement.
  books.splice(bookIndex, 1);

  // 204 No Content — standard for successful deletion with no response body.
  res.status(204).send();
}

// --------------------------------------------------------------------------
// EXPORT ROUTE HANDLERS
// --------------------------------------------------------------------------
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
};
```

**Why these patterns?**
- **Validation before mutation**: We never touch storage until we know the input is valid. This prevents dirty data from entering our "database."
- **`next(err)` instead of `res.status(500).json(...)`**: By delegating to the error handler middleware, route code stays focused on business logic and error formatting is consistent across all endpoints.
- **201 for creation, 204 for deletion**: These are the HTTP standards that signal "resource created" and "resource deleted with no body," respectively.

