```javascript
/**
 * ============================================================================
 * STATS ROUTE — Aggregate Book Statistics
 * ============================================================================
 *
 * WHY a separate route file for stats?
 *   - Stats are read-only aggregate data, not CRUD on individual resources.
 *   - Keeping it separate makes the API surface clearer: /books manages books,
 *     /stats answers questions about the collection as a whole.
 *
 * WHAT statistics do we expose?
 *   - totalBooks: how many books exist in storage.
 *   - averageYear: the mean publication year (rounded to 2 decimals).
 *   - topGenres: an array of { genre, count } sorted by count descending.
 *   - oldestBook / newestBook: the book with the min/max year.
 */

/**
 * GET /stats — Return aggregate statistics about the book collection.
 *
 * @example
 *   // Response:
 *   {
 *     "success": true,
 *     "data": {
 *       "totalBooks": 3,
 *       "averageYear": 1924.33,
 *       "topGenres": [
 *         { "genre": "Fiction", "count": 2 },
 *         { "genre": "Science", "count": 1 }
 *       ],
 *       "oldestBook": { "id": 1, "title": "The Great Gatsby", ... },
 *       "newestBook": { "id": 2, "title": "To Kill a Mockingbird", ... }
 *     }
 *   }
 *
 * @param {import('express').Request} req — Express request object (unused).
 * @param {import('express').Response} res — Express response object.
 */
async function getStats(req, res) {
  // Grab the shared in-memory array from the books route module.
  // We require it here to avoid circular dependency issues by using a getter.
  const { books } = require('./books');

  const totalBooks = books.length;

  if (totalBooks === 0) {
    // Edge case: no books exist yet — return sensible defaults.
    return res.status(200).json({
      success: true,
      data: {
        totalBooks: 0,
        averageYear: null,
        topGenres: [],
        oldestBook: null,
        newestBook: null,
      },
    });
  }

  // Compute the average publication year.
  const sumOfYears = books.reduce((sum, book) => sum + book.year, 0);
  const averageYear = Math.round((sumOfYears / totalBooks) * 100) / 100;

  // Count occurrences of each genre.
  const genreCounts = {};
  for (const book of books) {
    const genre = book.genre || 'Unknown';
    genreCounts[genre] = (genreCounts[genre] || 0) + 1;
  }

  // Convert to sorted array: [{ genre, count }, ...] descending by count.
  const topGenres = Object.entries(genreCounts)
    .map(([genre, count]) => ({ genre, count }))
    .sort((a, b) => b.count - a.count);

  // Find the oldest and newest books by year.
  const oldestBook = books.reduce((oldest, book) =>
    book.year < oldest.year ? book : oldest
  );
  const newestBook = books.reduce((newest, book) =>
    book.year > newest.year ? book : newest
  );

  res.status(200).json({
    success: true,
    data: {
      totalBooks,
      averageYear,
      topGenres,
      oldestBook,
      newestBook,
    },
  });
}

module.exports = { getStats };
```

**Why compute stats on every request?** For an in-memory educational example this is fine. In production with millions of records you'd cache these or use a materialized view, but the logic here stays simple and transparent.

