## File 6: `src/app.js`

```javascript
/**
 * ============================================================================
 * EXPRESS APPLICATION SETUP
 * ============================================================================
 *
 * WHY separate app.js from server.js?
 *   - app.js configures Express (middleware, routes) — it's framework-agnostic.
 *   - server.js starts the HTTP server on a port — it's infrastructure.
 *   - This separation makes testing easier: you can `require('./app')` in tests
 *     without actually binding to a network port.
 *
 * MIDDLEWARE ORDER MATTERS in Express:
 *   1. Body parsers (express.json) — must come BEFORE route handlers so
 *      req.body is populated when routes run.
 *   2. Route registration — wires URLs to handler functions.
 *   3. Error-handling middleware — must be LAST so it catches errors from
 *      everything above it. Express skips error middleware during normal flow.
 */

const express = require('express');
const errorHandler = require('./middleware/errorHandler');
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
} = require('./routes/books');
const { getStats } = require('./routes/stats');

// Create the Express application instance.
const app = express();

// --------------------------------------------------------------------------
// MIDDLEWARE CONFIGURATION
// --------------------------------------------------------------------------

/**
 * Built-in middleware that parses incoming JSON request bodies.
 * Makes req.body available as a JavaScript object.
 * Without this, POST/PUT bodies would be raw strings.
 */
app.use(express.json());

/**
 * Built-in middleware that logs every request to the console.
 * Format: METHOD  PATH  STATUS  TIME(ms)
 * Useful for debugging and monitoring during development.
 */
app.use((req, res, next) => {
  const start = Date.now();
  // Intercept res.end to log after the response is sent.
  const originalEnd = res.end.bind(res);
  res.end = function (...args) {
    const duration = Date.now() - start;
    console.log(`${req.method} ${req.path} ${res.statusCode} ${duration}ms`);
    originalEnd(...args);
  };
  next();
});

// --------------------------------------------------------------------------
// ROUTE REGISTRATION
// --------------------------------------------------------------------------

/**
 * GET /books — List all books with optional filtering.
 * Query params: author, genre, year (minimum).
 */
app.get('/books', getAllBooks);

/**
 * GET /books/:id — Get a single book by numeric ID.
 */
app.get('/books/:id', getBookById);

/**
 * POST /books — Create a new book from JSON body.
 */
app.post('/books', createBook);

/**
 * PUT /books/:id — Fully replace an existing book.
 */
app.put('/books/:id', updateBook);

/**
 * DELETE /books/:id — Delete a book by ID.
 */
app.delete('/books/:id', deleteBook);

/**
 * GET /stats — Return aggregate statistics about the collection.
 */
app.get('/stats', getStats);

// --------------------------------------------------------------------------
// 404 HANDLER FOR UNRECOGNIZED ROUTES
// --------------------------------------------------------------------------
/**
 * If no route matches, return a 404 with a helpful JSON message.
 * This must come AFTER all route registrations so it only catches misses.
 */
app.use((req, res, next) => {
  const { InternalError } = require('./errors/CustomError');
  // We throw an error here so the centralized errorHandler formats the response.
  next(new InternalError(`Route ${req.method} ${req.path} not found`));
});

// --------------------------------------------------------------------------
// ERROR HANDLING MIDDLEWARE (MUST BE LAST)
// --------------------------------------------------------------------------
app.use(errorHandler);

// --------------------------------------------------------------------------
// EXPORT
// --------------------------------------------------------------------------
module.exports = app;
```

**Why this order?** Express processes middleware top-to-bottom. Body parsing must happen before routes read `req.body`. The catch-all 404 handler must come after all real routes so it only triggers for truly unknown paths. The error handler must be last so it can intercept errors from every preceding layer.

