## File 7: `src/server.js`

```javascript
/**
 * ============================================================================
 * SERVER ENTRY POINT
 * ============================================================================
 *
 * WHY a separate entry point?
 *   - Keeps the port configuration isolated from app configuration.
 *   - Makes it easy to add graceful shutdown logic, health checks, etc. later.
 *
 * PORT SELECTION:
 *   - We check for a PORT environment variable (useful for deployment platforms
 *     like Heroku or Render that inject one).
 *   - Default to 3000 for local development — the de-facto standard for Node.js.
 */

const app = require('./app');

// Determine the port: env var > default 3000.
const PORT = process.env.PORT || 3000;

// Start the HTTP server and listen on the chosen port.
const server = app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`  Book REST API running on port ${PORT}`);
  console.log(`  Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`========================================`);
  console.log(`\nTest endpoints:`);
  console.log(`  GET  http://localhost:${PORT}/books`);
  console.log(`  POST http://localhost:${PORT}/books`);
  console.log(`  GET  http://localhost:${PORT}/stats`);
});

// --------------------------------------------------------------------------
// GRACEFUL SHUTDOWN
// --------------------------------------------------------------------------
/**
 * Handle SIGTERM and SIGINT so the server closes connections cleanly.
 * This prevents half-open sockets and ensures in-flight requests finish.
 */
function gracefulShutdown(signal) {
  console.log(`\n${signal} received. Shutting down gracefully...`);
  server.close(() => {
    console.log('Server closed. Process exiting.');
    process.exit(0);
  });
  // Force-exit after 10 seconds if connections are still open.
  setTimeout(() => process.exit(1), 10000);
}

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));
```

**Why graceful shutdown?** Without it, sending `Ctrl+C` or a deployment signal kills the process immediately, potentially dropping in-flight requests. The 10-second timeout is a safety valve so the process doesn't hang forever.

