## Arquivo 2: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================================
 *
 * POR QUE UM ARQUIVO SEPARADO?
 * -----------------------------
 * Separar o middleware de tratamento de erros do código principal segue o
 * princípio de responsabilidade única (Single Responsibility Principle). Isso
 * torna o código mais testável, legível e fácil de manter. Qualquer mudança
 * no comportamento de erro afeta apenas este arquivo.
 *
 * POR QUE CLASSES DE ERRO PERSONALIZADAS?
 * ----------------------------------------
 * Classes de erro personalizadas permitem:
 *   1. Diferenciar tipos de erro (notFound, validation, internal)
 *   2. Incluir metadados adicionais (campo inválido, valor recebido, etc.)
 *   3. Mapear automaticamente para códigos HTTP apropriados
 *   4. Fornecer respostas de erro consistentes e estruturadas
 *
 * POR QUE UM MIDDLEWARE ESPECIAL?
 * ---------------------------------
 * No Express, middlewares de erro têm 4 parâmetros (err, req, res, next).
 * O framework os identifica automaticamente e encadeia apenas eles após
 * um erro ser lançado. Isso evita que middlewares normais processem a
 * resposta duas vezes.
 */

// ============================================================================
// CLASSES DE ERRO PERSONALIZADAS
// ============================================================================
//
// Cada classe estende Error, herdando propriedades padrão como stack trace.
// Adicionamos campos customizados para enriquecer a resposta de erro.
// O código HTTP é definido como propriedade da instância, não hardcoded.

/**
 * Erro genérico para recursos não encontrados (HTTP 404).
 *
 * @extends Error
 */
class NotFoundError extends Error {
  /**
   * Cria uma instância de NotFoundError.
   *
   * @param {string} message - Mensagem descritiva do erro.
   * @param {string} [resource] - Nome do recurso que não foi encontrado.
   */
  constructor(message = 'Recurso não encontrado', resource) {
    super(message);
    this.name = 'NotFoundError';
    this.statusCode = 404; // HTTP 404 Not Found

    // Mantém o stack trace correto mesmo com custom error classes
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

/**
 * Erro para validação de dados inválidos (HTTP 400).
 *
 * @extends Error
 */
class ValidationError extends Error {
  /**
   * Cria uma instância de ValidationError.
   *
   * @param {string} message - Mensagem descritiva do erro.
   * @param {Object} [details] - Detalhes da validação falha (campo, valor, regra).
   */
  constructor(message = 'Erro de validação', details) {
    super(message);
    this.name = 'ValidationError';
    this.statusCode = 400; // HTTP 400 Bad Request
    this.details = details || {};

    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

/**
 * Erro para conflitos de dados (HTTP 409).
 * Usado quando um recurso já existe com o mesmo identificador único.
 *
 * @extends Error
 */
class ConflictError extends Error {
  /**
   * Cria uma instância de ConflictError.
   *
   * @param {string} message - Mensagem descritiva do erro.
   * @param {string} [field] - Campo que causou o conflito.
   */
  constructor(message = 'Conflito com recurso existente', field) {
    super(message);
    this.name = 'ConflictError';
    this.statusCode = 409; // HTTP 409 Conflict
    this.field = field;

    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ============================================================================
// FUNÇÃO DE VALIDAÇÃO
// ============================================================================
//
// Função utilitária para validar campos obrigatórios de um objeto.
// Retorna um array de erros de validação ou null se tudo estiver válido.
// Isso centraliza a lógica de validação e evita repetição nos handlers.

/**
 * Valida campos obrigatórios de um objeto.
 *
 * @param {Object} data - Objeto a ser validado.
 * @param {string[]} requiredFields - Array de nomes de campos obrigatórios.
 * @returns {null|string[]} null se válido, array de erros se inválido.
 */
function validateRequiredFields(data, requiredFields) {
  const errors = [];

  for (const field of requiredFields) {
    // Verifica se o campo existe E tem valor não vazio
    if (data[field] === undefined || data[field] === null || data[field] === '') {
      errors.push({
        field,
        message: `O campo '${field}' é obrigatório`,
        code: 'REQUIRED_FIELD'
      });
    }
  }

  return errors.length > 0 ? errors : null;
}

// ============================================================================
// MIDDLEWARE PRINCIPAL DE TRATAMENTO DE ERROS
// ============================================================================
//
 * Este middleware é o "guardião" da API. Ele intercepta todos os erros não
 * tratados e padroniza a resposta JSON, independentemente do tipo de erro.
 *
 * A estrutura da resposta de erro segue um padrão consistente:
 *   {
 *     success: false,
 *     error: {
 *       name: 'NomeDoErro',
 *       message: 'Descrição do erro',
 *       statusCode: 404,
 *       details: {}        // Opcional, para erros de validação
 *     }
 *   }
 *
 * Isso permite que o consumidor da API trate respostas de erro de forma
 * uniforme, verificando apenas o campo `success`.

/**
 * Middleware de tratamento de erros do Express.
 * Deve ser registrado APÓS todos os middlewares e rotas.
 *
 * @param {Error} err - A instância de erro lançada.
 * @param {import('express').Request} req - Objeto de requisição Express.
 * @param {import('express').Response} res - Objeto de resposta Express.
 * @param {import('express').NextFunction} next - Função para encadear middlewares.
 */
function errorHandler(err, req, res, next) {
  // Se o erro não tiver statusCode definido, assume erro interno do servidor
  const statusCode = err.statusCode || 500;

  // Monta a resposta de erro padronizada
  const errorResponse = {
    success: false,
    error: {
      name: err.name || 'Error',
      message: err.message,
      statusCode
    }
  };

  // Adiciona detalhes extras para erros de validação e conflito
  if (err.details) {
    errorResponse.error.details = err.details;
  }
  if (err.field) {
    errorResponse.error.field = err.field;
  }

  // Em desenvolvimento, inclui o stack trace para facilitar debugging
  if (process.env.NODE_ENV !== 'production') {
    errorResponse.error.stack = err.stack;
  }

  // Log do erro no servidor para fins de monitoramento
  console.error(`[${err.name}] ${err.message}`);
  if (err.stack) {
    console.error(err.stack);
  }

  // Envia a resposta JSON padronizada
  res.status(statusCode).json(errorResponse);
}

// ============================================================================
// EXPORTAÇÕES
// ============================================================================
module.exports = {
  NotFoundError,
  ValidationError,
  ConflictError,
  validateRequiredFields,
  errorHandler
};
```

