## Arquivo 3: `src/store/books.js`

```javascript
/**
 * ============================================================================
 * ARMAZENAMENTO EM MEMÓRIA (IN-MEMORY STORE)
 * ============================================================================
 *
 * POR QUE UM ARRAY?
 * ------------------
 * Um array é a estrutura de dados mais adequada para este cenário educacional
 * porque:
 *   1. Preserva a ordem de inserção dos livros
 *   2. Permite iteração eficiente para listagem e filtragem
 *   3. O método .findIndex() permite busca por ID com complexidade O(n)
 *      que é aceitável para volumes pequenos (centenas de registros)
 *   4. Operações de splice (remoção) são simples e diretas
 *
 * POR QUE NÃO USAR UM OBJETO?
 * -----------------------------
 * Um objeto { id: livro } seria mais eficiente para buscas por ID (O(1)),
 * mas perderia a ordem natural e exigiria Object.values() para listagem.
 * Para fins educacionais, o array é mais intuitivo e didático.
 *
 * POR QUE NÃO USAR BANCO DE DADOS?
 * ----------------------------------
 * Um banco de dados real adicionaria complexidade desnecessária (conexões,
 * queries, migrations) que desviaria o foco dos conceitos REST. O array em
 * memória simula perfeitamente operações CRUD para fins educacionais.
 *
 * ATENÇÃO: Em produção, este store seria substituído por um banco de dados
 * como MongoDB, PostgreSQL ou SQLite. A interface (CRUD) permaneceria a mesma.
 */

// ============================================================================
// DADOS INICIAIS (SEED DATA)
// ============================================================================
//
 * Populamos o array com alguns livros iniciais para que a API já venha
 * com dados para consulta ao ser iniciada. Isso facilita os testes
 * imediatos sem precisar criar registros manualmente primeiro.

/**
 * Array em memória que armazena todos os livros da API.
 * Cada livro é um objeto com as propriedades: id, title, author, year, genre.
 *
 * @type {Array<Object>}
 */
let books = [
  {
    id: 1,
    title: 'Dom Casmurro',
    author: 'Machado de Assis',
    year: 1899,
    genre: 'Romance'
  },
  {
    id: 2,
    title: 'Memórias Póstumas de Brás Cubas',
    author: 'Machado de Assis',
    year: 1881,
    genre: 'Romance'
  },
  {
    id: 3,
    title: 'O Cortiço',
    author: 'Aluísio Azevedo',
    year: 1890,
    genre: 'Naturalismo'
  },
  {
    id: 4,
    title: 'Capitães da Areia',
    author: 'Jorge Amado',
    year: 1937,
    genre: 'Romance Social'
  }
];

// ============================================================================
// CONTADOR DE ID AUTOMÁTICO
// ============================================================================
//
 * Usamos uma variável separada para gerar IDs únicos em vez de depender do
 * array.length porque:
 *   1. Após exclusões, o length pode ser menor que o maior ID existente
 *   2. Garante IDs sequenciais e únicos mesmo com operações de delete
 *   3. É uma prática comum em sistemas que simulam auto-incremento de BD
 *
 * Inicializamos com books.length + 1 para garantir que o próximo ID seja
 * maior que qualquer ID existente no array.

/**
 * Próximo ID a ser atribuído a um novo livro.
 * Incrementado automaticamente a cada criação.
 *
 * @type {number}
 */
let nextId = books.length + 1;

// ============================================================================
// OPERAÇÕES CRUD (Create, Read, Update, Delete)
// ============================================================================

/**
 * Retorna todos os livros armazenados.
 *
 * Esta função retorna uma cópia do array para evitar mutações externas
 * acidentais. Em JavaScript, arrays são passados por referência, então
 * retornar [...books] cria um novo array com os mesmos elementos.
 *
 * @returns {Array<Object>} Array contendo todos os livros.
 */
function getAllBooks() {
  return [...books]; // Retorna cópia para evitar mutação externa
}

/**
 * Busca um livro pelo seu ID.
 *
 * Utilizamos .find() em vez de .findIndex() porque:
 *   - .find() retorna o objeto diretamente, mais legível
 *   - Para arrays pequenos, a diferença de performance é insignificante
 *   - O código fica mais expressivo e auto-documentado
 *
 * @param {number} id - ID numérico do livro a ser buscado.
 * @returns {Object|null} O livro encontrado ou null se não existir.
 */
function getBookById(id) {
  return books.find(book => book.id === id) || null;
}

/**
 * Cria um novo livro e o adiciona ao array.
 *
 * O ID é gerado automaticamente usando o contador nextId, que é
 * incrementado após a criação. Isso garante unicidade mesmo com
 * exclusões de livros anteriores.
 *
 * @param {Object} bookData - Dados do novo livro (title, author, year, genre).
 * @returns {Object} O livro criado com ID atribuído.
 */
function createBook(bookData) {
  const newBook = {
    id: nextId++, // Atribui ID atual e incrementa para o próximo
    ...bookData   // Espalha os dados fornecidos no objeto
  };

  books.push(newBook); // Adiciona ao final do array
  return newBook;
}

/**
 * Atualiza um livro existente pelo seu ID.
 *
 * Utilizamos .findIndex() em vez de .find() porque precisamos da posição
 * do elemento para atualizá-lo diretamente no array (mutação controlada).
 *
 * @param {number} id - ID do livro a ser atualizado.
 * @param {Object} updates - Campos a serem atualizados.
 * @returns {Object|null} O livro atualizado ou null se não encontrado.
 */
function updateBook(id, updates) {
  const index = books.findIndex(book => book.id === id);

  if (index === -1) {
    return null; // Livro não encontrado
  }

  // Atualiza apenas os campos fornecidos (partial update)
  // O operador spread cria um novo objeto com os campos atualizados
  books[index] = {
    ...books[index], // Mantém todos os campos existentes
    ...updates       // Sobrescreve com os novos valores
  };

  return books[index];
}

/**
 * Remove um livro do array pelo seu ID.
 *
 * Utilizamos .splice() porque:
 *   - Permite remover elementos por índice de forma eficiente
 *   - Modifica o array original (in-place), economizando memória
 *   - É a abordagem padrão para remoção em arrays JavaScript
 *
 * @param {number} id - ID do livro a ser removido.
 * @returns {boolean} true se removido, false se não encontrado.
 */
function deleteBook(id) {
  const index = books.findIndex(book => book.id === id);

  if (index === -1) {
    return false; // Livro não encontrado
  }

  books.splice(index, 1); // Remove 1 elemento na posição encontrada
  return true;
}

// ============================================================================
// OPERAÇÕES DE ESTATÍSTICA
// ============================================================================

/**
 * Calcula estatísticas agregadas sobre os livros.
 *
 * Utilizamos .reduce() porque:
 *   - Permite calcular múltiplas métricas em uma única iteração (O(n))
 *   - É mais eficiente que fazer vários loops separados
 *   - O acumulador mantém estado entre as iterações
 *
 * @returns {Object} Estatísticas: total, porGenero, autoresUnicos, mediaAnos.
 */
function getStats() {
  return books.reduce(
    (acc, book) => {
      // Incrementa o total de livros
      acc.total++;

      // Conta livros por gênero usando um objeto acumulador
      if (!acc.byGenre[book.genre]) {
        acc.byGenre[book.genre] = 0;
      }
      acc.byGenre[book.genre]++;

      // Adiciona autor ao Set para contar únicos (Sets não permitem duplicatas)
      acc.authors.add(book.author);

      // Acumula anos para calcular média posteriormente
      acc.totalYear += book.year;

      return acc;
    },
    {
      total: 0,
      byGenre: {},
      authors: new Set(),
      totalYear: 0
    }
  );
}

// ============================================================================
// EXPORTAÇÕES
// ============================================================================
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats
};
```

