## Arquivo 4: `src/routes/books.js`

```javascript
/**
 * ============================================================================
 * ROTAS DE LIVROS (CRUD COMPLETO)
 * ============================================================================
 *
 * POR QUE ARQUIVO DE ROTA SEPARADO?
 * ------------------------------------
 * Separar rotas em arquivos distintos segue o padrão de modularização do
 * Express.js. Isso permite:
 *   1. Escalabilidade — adicionar novas rotas sem poluir app.js
 *   2. Testabilidade — cada arquivo pode ser testado isoladamente
 *   3. Manutenção — mudanças em uma rota não afetam outras
 *   4. Legibilidade — código mais organizado e fácil de navegar
 *
 * POR QUE express.Router()?
 * ---------------------------
 * O Router do Express cria um "mini-app" de rotas que pode ser montado
 * em qualquer caminho. Isso permite:
 *   - Reutilizar o mesmo conjunto de rotas em múltiplos caminhos
 *   - Aplicar middlewares específicos apenas a este grupo de rotas
 *   - Manter o namespace das rotas organizado (/books/*)
 *
 * POR QUE PADRÃO REST?
 * ----------------------
 * Cada método HTTP mapeia para uma operação CRUD específica:
 *   GET    /books       → Listar todos (Read all)
 *   GET    /books/:id   → Buscar um (Read one)
 *   POST   /books       → Criar novo (Create)
 *   PUT    /books/:id   → Atualizar completo (Update full)
 *   DELETE /books/:id   → Remover (Delete)
 *
 * Esta convenção é amplamente adotada e reconhecida por consumidores de API.
 */

const express = require('express');
const router = express.Router();
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook
} = require('../store/books');
const { ValidationError, NotFoundError, validateRequiredFields } = require('../middleware/errorHandler');

// ============================================================================
// CONSTANTES DE VALIDAÇÃO
// ============================================================================
//
 * Definimos as regras de validação como constantes no topo para:
 *   1. Centralizar a configuração em um só lugar
 *   2. Facilitar mudanças futuras (adicionar/remover campos obrigatórios)
 *   3. Tornar o código mais legível ao referenciar a constante

/**
 * Campos obrigatórios para criar um livro.
 * @type {string[]}
 */
const CREATE_REQUIRED_FIELDS = ['title', 'author'];

/**
 * Campos obrigatórios para atualizar um livro (pelo menos um deve ser fornecido).
 * @type {string[]}
 */
const UPDATE_REQUIRED_FIELDS = ['title', 'author', 'year', 'genre'];

// ============================================================================
// FUNÇÕES AUXILIARES DE HANDLER
// ============================================================================
//
 * Extraímos lógica repetida em funções auxiliares para evitar duplicação
 * e seguir o princípio DRY (Don't Repeat Yourself).

/**
 * Valida os dados de criação de um livro.
 *
 * @param {Object} body - Corpo da requisição com os dados do livro.
 * @throws {ValidationError} Se algum campo obrigatório estiver ausente.
 */
function validateCreateBook(body) {
  const errors = validateRequiredFields(body, CREATE_REQUIRED_FIELDS);
  if (errors) {
    throw new ValidationError('Dados inválidos para criação de livro', errors);
  }

  // Validações adicionais de tipo
  if (typeof body.title !== 'string' || body.title.trim() === '') {
    throw new ValidationError('O campo title deve ser uma string não vazia', [
      { field: 'title', message: 'Deve ser uma string válida', code: 'INVALID_TYPE' }
    ]);
  }

  if (typeof body.author !== 'string' || body.author.trim() === '') {
    throw new ValidationError('O campo author deve ser uma string não vazia', [
      { field: 'author', message: 'Deve ser uma string válida', code: 'INVALID_TYPE' }
    ]);
  }

  // Ano é opcional, mas se fornecido deve ser um número válido
  if (body.year !== undefined && body.year !== null) {
    const year = Number(body.year);
    if (!Number.isInteger(year) || year < 0 || year > new Date().getFullYear() + 1) {
      throw new ValidationError('O campo year deve ser um número inteiro válido', [
        { field: 'year', message: 'Deve ser um ano válido (0 a ano atual)', code: 'INVALID_RANGE' }
      ]);
    }
  }

  // Gênero é opcional, mas se fornecido deve ser string
  if (body.genre !== undefined && body.genre !== null) {
    if (typeof body.genre !== 'string' || body.genre.trim() === '') {
      throw new ValidationError('O campo genre deve ser uma string não vazia', [
        { field: 'genre', message: 'Deve ser uma string válida', code: 'INVALID_TYPE' }
      ]);
    }
  }
}

/**
 * Valida os dados de atualização de um livro.
 *
 * @param {Object} body - Corpo da requisição com os campos a atualizar.
 * @throws {ValidationError} Se nenhum campo válido for fornecido.
 */
function validateUpdateBook(body) {
  // Pelo menos um campo deve ser fornecido para atualização
  const hasValidField = UPDATE_REQUIRED_FIELDS.some(field => body[field] !== undefined);
  if (!hasValidField) {
    throw new ValidationError('Nenhum campo válido fornecido para atualização', [
      { field: 'body', message: 'Forneça pelo menos um campo para atualizar', code: 'EMPTY_UPDATE' }
    ]);
  }

  // Valida cada campo individualmente se presente
  if (body.title !== undefined) {
    if (typeof body.title !== 'string' || body.title.trim() === '') {
      throw new ValidationError('O campo title deve ser uma string não vazia', [
        { field: 'title', message: 'Deve ser uma string válida', code: 'INVALID_TYPE' }
      ]);
    }
  }

  if (body.author !== undefined) {
    if (typeof body.author !== 'string' || body.author.trim() === '') {
      throw new ValidationError('O campo author deve ser uma string não vazia', [
        { field: 'author', message: 'Deve ser uma string válida', code: 'INVALID_TYPE' }
      ]);
    }
  }

  if (body.year !== undefined) {
    const year = Number(body.year);
    if (!Number.isInteger(year) || year < 0 || year > new Date().getFullYear() + 1) {
      throw new ValidationError('O campo year deve ser um número inteiro válido', [
        { field: 'year', message: 'Deve ser um ano válido (0 a ano atual)', code: 'INVALID_RANGE' }
      ]);
    }
  }

  if (body.genre !== undefined) {
    if (typeof body.genre !== 'string' || body.genre.trim() === '') {
      throw new ValidationError('O campo genre deve ser uma string não vazia', [
        { field: 'genre', message: 'Deve ser uma string válida', code: 'INVALID_TYPE' }
      ]);
    }
  }
}

// ============================================================================
// GET /books — LISTAR TODOS OS LIVROS COM FILTRAGEM
// ============================================================================
//
 * Exemplo de requisição (curl):
 *   curl http://localhost:3000/books
 *
 * Exemplo com filtragem (Postman):
 *   GET http://localhost:3000/books?author=Machado%20de%20Assis&genre=Romance
 *
 * A filtragem é feita via query parameters (req.query), que são strings.
 * Filtramos por author e genre de forma case-insensitive para melhor UX.

/**
 * @route   GET /books
 * @desc    Lista todos os livros com suporte a filtragem por query params
 * @access  Public
 * @query   {string} [author] - Filtra por autor (parcial, case-insensitive)
 * @query   {string} [genre]  - Filtra por gênero (exato, case-insensitive)
 * @returns {200} {Object} Resposta com lista de livros e metadados
 * @returns {400} {Object} Erro de validação se parâmetros inválidos
 *
 * Exemplo de resposta:
 * {
 *   "success": true,
 *   "data": [
 *     { "id": 1, "title": "Dom Casmurro", "author": "Machado de Assis", "year": 1899, "genre": "Romance" }
 *   ],
 *   "metadata": { "total": 4, "filtered": 2 }
 * }
 */
router.get('/', (req, res) => {
  // Obtém todos os livros do store
  let result = getAllBooks();

  // Filtra por autor se o parâmetro query 'author' for fornecido
  if (req.query.author) {
    const authorFilter = req.query.author.toLowerCase();
    result = result.filter(book =>
      book.author.toLowerCase().includes(authorFilter)
    );
  }

  // Filtra por gênero se o parâmetro query 'genre' for fornecido
  if (req.query.genre) {
    const genreFilter = req.query.genre.toLowerCase();
    result = result.filter(book =>
      book.genre.toLowerCase() === genreFilter
    );
  }

  // Retorna a resposta padronizada com metadados
  res.json({
    success: true,
    data: result,
    metadata: {
      total: result.length,
      filtered: req.query.author || req.query.genre ? true : false
    }
  });
});

// ============================================================================
// GET /books/:id — OBTER LIVRO POR ID
// ============================================================================
//
 * Exemplo de requisição (curl):
 *   curl http://localhost:3000/books/1
 *
 * O parâmetro :id é extraído de req.params, que contém valores das rotas
 * com placeholders. No Express, params são sempre strings, então usamos
 * Number() para converter para número antes da comparação.

/**
 * @route   GET /books/:id
 * @desc    Busca um livro específico pelo seu ID numérico
 * @access  Public
 * @param   {number} id - ID do livro (deve ser um número inteiro positivo)
 * @returns {200} {Object} Livro encontrado
 * @returns {400} {Object} Erro se o ID for inválido
 * @returns {404} {Object} Erro se o livro não existir
 *
 * Exemplo de resposta:
 * {
 *   "success": true,
 *   "data": { "id": 1, "title": "Dom Casmurro", "author": "Machado de Assis", "year": 1899, "genre": "Romance" }
 * }
 */
router.get('/:id', (req, res) => {
  // Converte o ID de string (params são strings) para número
  const id = Number(req.params.id);

  // Valida se o ID é um número válido e positivo
  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('ID inválido. Deve ser um número inteiro positivo.', [
      { field: 'id', message: `Valor '${req.params.id}' não é um número inteiro válido`, code: 'INVALID_ID' }
    ]);
  }

  // Busca o livro no store
  const book = getBookById(id);

  if (!book) {
    throw new NotFoundError(`Livro com ID ${id} não encontrado`);
  }

  res.json({ success: true, data: book });
});

// ============================================================================
// POST /books — CRIAR NOVO LIVRO
// ============================================================================
//
 * Exemplo de requisição (curl):
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Grande Sertão: Veredas","author":"Guimarães Rosa","year":1956,"genre":"Romance"}'
 *
 * Usamos POST porque:
 *   1. Criamos um novo recurso no servidor
 *   2. O ID é gerado pelo servidor (não pelo cliente)
 *   3. Os dados são enviados no corpo da requisição (JSON)
 *
 * A validação ocorre ANTES de chamar o store, seguindo o princípio de
 * "falhar rápido" (fail-fast). Isso evita operações desnecessárias no
 * armazenamento quando os dados estão inválidos.

/**
 * @route   POST /books
 * @desc    Cria um novo livro no sistema
 * @access  Public
 * @body    {string} title  - Título do livro (obrigatório)
 * @body    {string} author - Autor do livro (obrigatório)
 * @body    {number} [year] - Ano de publicação (opcional)
 * @body    {string} [genre]- Gênero literário (opcional)
 * @returns {201} {Object} Livro criado com ID atribuído
 * @returns {400} {Object} Erro de validação se dados inválidos
 *
 * Exemplo de resposta (201 Created):
 * {
 *   "success": true,
 *   "data": { "id": 5, "title": "Grande Sertão: Veredas", "author": "Guimarães Rosa", "year": 1956, "genre": "Romance" },
 *   "message": "Livro criado com sucesso"
 * }
 */
router.post('/', (req, res) => {
  // Valida os dados antes de criar
  validateCreateBook(req.body);

  // Cria o livro no store
  const newBook = createBook({
    title: req.body.title.trim(),
    author: req.body.author.trim(),
    year: req.body.year ? Number(req.body.year) : null,
    genre: req.body.genre ? req.body.genre.trim() : null
  });

  // Retorna 201 Created (padrão REST para criação de recursos)
  res.status(201).json({
    success: true,
    data: newBook,
    message: 'Livro criado com sucesso'
  });
});

// ============================================================================
// PUT /books/:id — ATUALIZAR LIVRO EXISTENTE
// ============================================================================
//
 * Exemplo de requisição (curl):
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Dom Casmurro - Edição Crítica","year":2020}'
 *
 * Usamos PUT (não PATCH) porque:
 *   1. PUT substitui o recurso completo — mas aqui implementamos partial update
 *      para praticidade, atualizando apenas os campos fornecidos
 *   2. Em uma API real, PUT seria usado para atualização completa e PATCH
 *      para parcial. Aqui combinamos ambos para simplicidade educacional.
 *
 * A diferença entre PUT e PATCH:
 *   - PUT: substitui TODOS os campos (campos não enviados viram null)
 *   - PATCH: atualiza APENAS os campos enviados (demais permanecem inalterados)

/**
 * @route   PUT /books/:id
 * @desc    Atualiza um livro existente (partial update — apenas campos enviados)
 * @access  Public
 * @param   {number} id       - ID do livro a atualizar
 * @body    {string} [title]  - Novo título
 * @body    {string} [author] - Novo autor
 * @body    {number} [year]   - Novo ano de publicação
 * @body    {string} [genre]  - Novo gênero
 * @returns {200} {Object} Livro atualizado
 * @returns {400} {Object} Erro se dados inválidos ou ID inválido
 * @returns {404} {Object} Erro se livro não encontrado
 *
 * Exemplo de resposta:
 * {
 *   "success": true,
 *   "data": { "id": 1, "title": "Dom Casmurro - Edição Crítica", "author": "Machado de Assis", "year": 2020, "genre": "Romance" },
 *   "message": "Livro atualizado com sucesso"
 * }
 */
router.put('/:id', (req, res) => {
  // Converte e valida o ID
  const id = Number(req.params.id);
  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('ID inválido. Deve ser um número inteiro positivo.', [
      { field: 'id', message: `Valor '${req.params.id}' não é um número inteiro válido`, code: 'INVALID_ID' }
    ]);
  }

  // Valida os dados de atualização
  validateUpdateBook(req.body);

  // Busca o livro antes de atualizar (para verificar existência)
  const existingBook = getBookById(id);
  if (!existingBook) {
    throw new NotFoundError(`Livro com ID ${id} não encontrado`);
  }

  // Prepara os dados de atualização (apenas campos fornecidos)
  const updates = {};
  if (req.body.title !== undefined) updates.title = req.body.title.trim();
  if (req.body.author !== undefined) updates.author = req.body.author.trim();
  if (req.body.year !== undefined) updates.year = Number(req.body.year);
  if (req.body.genre !== undefined) updates.genre = req.body.genre.trim();

  // Atualiza no store
  const updatedBook = updateBook(id, updates);

  res.json({
    success: true,
    data: updatedBook,
    message: 'Livro atualizado com sucesso'
  });
});

// ============================================================================
// DELETE /books/:id — EXCLUIR LIVRO
// ============================================================================
//
 * Exemplo de requisição (curl):
 *   curl -X DELETE http://localhost:3000/books/3
 *
 * Usamos DELETE porque:
 *   1. Removemos um recurso existente pelo seu identificador
 *   2. Não enviamos corpo na requisição (padrão REST)
 *   3. O servidor decide o que fazer com os dados relacionados (se houver)
 *
 * Retornamos 200 OK com a representação do livro removido, pois isso é
 * útil para o cliente confirmar exatamente o que foi excluído. Algumas
 * APIs retornam 204 No Content — ambas são válidas conforme RFC 7231.

/**
 * @route   DELETE /books/:id
 * @desc    Remove um livro do sistema pelo seu ID
 * @access  Public
 * @param   {number} id - ID do livro a remover
 * @returns {200} {Object} Livro removido
 * @returns {400} {Object} Erro se o ID for inválido
 * @returns {404} {Object} Erro se o livro não existir
 *
 * Exemplo de resposta:
 * {
 *   "success": true,
 *   "data": { "id": 3, "title": "O Cortiço", "author": "Aluísio Azevedo", "year": 1890, "genre": "Naturalismo" },
 *   "message": "Livro removido com sucesso"
 * }
 */
router.delete('/:id', (req, res) => {
  // Converte e valida o ID
  const id = Number(req.params.id);
  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('ID inválido. Deve ser um número inteiro positivo.', [
      { field: 'id', message: `Valor '${req.params.id}' não é um número inteiro válido`, code: 'INVALID_ID' }
    ]);
  }

  // Busca o livro antes de deletar (para retorná-lo na resposta)
  const bookToDelete = getBookById(id);
  if (!bookToDelete) {
    throw new NotFoundError(`Livro com ID ${id} não encontrado`);
  }

  // Remove do store
  deleteBook(id);

  res.json({
    success: true,
    data: bookToDelete,
    message: 'Livro removido com sucesso'
  });
});

// ============================================================================
// EXPORTAÇÃO DO ROUTER
// ============================================================================
module.exports = router;
```

