/**
 * ============================================================================
 * ROTAS DE ESTATÍSTICAS
 * ============================================================================
 *
 * As estatísticas são uma operação de leitura (GET) que não modifica dados,
 * mas calcula métricas agregadas a partir do store. Isso justifica:
 *   1. Ser um endpoint separado das rotas CRUD principais
 *   2. Não exigir parâmetros de path (apenas query params opcionais)
 *   3. Ter uma resposta com estrutura diferente (métricas, não recursos)
 */

const { getStats } = require('../store/books');

/**
 * @route   GET /stats
 * @desc    Retorna estatísticas agregadas sobre os livros
 * @access  Public
 * @query   {string} [genre] - Filtra estatísticas por gênero (opcional)
 * @returns {200} {Object} Estatísticas: total, porGenero, autoresUnicos, mediaAnos
 *
 * Exemplo de requisição (curl):
 *   curl http://localhost:3000/stats
 *
 * Exemplo com filtragem (Postman):
 *   GET http://localhost:3000/stats?genre=Romance
 *
 * Exemplo de resposta:
 * {
 *   "success": true,
 *   "data": {
 *     "total": 4,
 *     "byGenre": { "Romance": 2, "Naturalismo": 1, "Romance Social": 1 },
 *     "uniqueAuthors": 3,
 *     "averageYear": 1901.75
 *   }
 * }
 */
const express = require('express');
const router = express.Router();

router.get('/', (req, res) => {
  // Obtém estatísticas do store
  const stats = getStats();

  // Se houver filtro por gênero, recalcula apenas para aquele gênero
  if (req.query.genre) {
    const genreFilter = req.query.genre.toLowerCase();
    const filteredBooks = require('../store/books').getAllBooks().filter(
      book => book.genre.toLowerCase() === genreFilter
    );

    // Recalcula estatísticas manualmente para o filtro
    const filteredStats = filteredBooks.reduce(
      (acc, book) => {
        acc.total++;
        if (!acc.byGenre[book.genre]) acc.byGenre[book.genre] = 0;
        acc.byGenre[book.genre]++;
        acc.authors.add(book.author);
        acc.totalYear += book.year;
        return acc;
      },
      { total: 0, byGenre: {}, authors: new Set(), totalYear: 0 }
    );

    res.json({
      success: true,
      data: {
        total: filteredStats.total,
        byGenre: filteredStats.byGenre,
        uniqueAuthors: filteredStats.authors.size,
        averageYear: filteredStats.total > 0
          ? parseFloat((filteredStats.totalYear / filteredStats.total).toFixed(2))
          : 0
      }
    });
    return;
  }

  // Resposta padrão sem filtragem
  res.json({
    success: true,
    data: {
      total: stats.total,
      byGenre: stats.byGenre,
      uniqueAuthors: stats.authors.size,
      averageYear: stats.total > 0
        ? parseFloat((stats.totalYear / stats.total).toFixed(2))
        : 0
    }
  });
});

module.exports = router;
```

