## Arquivo 6: `src/app.js`

```javascript
/**
 * ============================================================================
 * CONFIGURAÇÃO PRINCIPAL DA API
 * ============================================================================
 *
 * POR QUE SEPARAR app.js DAS ROTAS?
 * ------------------------------------
 * O arquivo app.js é o "orquestrador" da aplicação. Ele:
 *   1. Configura o servidor Express
 *   2. Registra middlewares globais (JSON parsing, CORS, etc.)
 *   3. Monta as rotas a partir dos arquivos separados
 *   4. Registra o middleware de tratamento de erros por último
 *
 * A ordem de registro é CRÍTICA no Express:
 *   - Middlewares globais primeiro (parse, logging)
 *   - Rotas em seguida
 *   - Middleware de erro POR ÚLTIMO (só então o Express o reconhece)
 *
 * POR QUE MIDDLEWARE JSON?
 * --------------------------
 * O middleware express.json() é necessário para:
 *   1. Parsear o corpo de requisições com Content-Type: application/json
 *   2. Disponibilizar req.body como um objeto JavaScript
 *   3. Sem ele, req.body seria undefined em requisições POST/PUT
 *
 * POR QUE CORS?
 * --------------
 * O CORS (Cross-Origin Resource Sharing) permite que a API seja acessada
 * por aplicações frontend em domínios diferentes. Em produção, deve-se
 * restringir os origens permitidas. Aqui deixamos aberto para facilitar
 * testes com Postman e curl.
 */

const express = require('express');
const bookRoutes = require('./routes/books');
const statsRoutes = require('./routes/stats');
const { errorHandler } = require('./middleware/errorHandler');

// ============================================================================
// INICIALIZAÇÃO DO APP EXPRESS
// ============================================================================
const app = express();

// ============================================================================
// MIDDLEWARES GLOBAIS
// ============================================================================

/**
 * Middleware para parsear JSON no corpo das requisições.
 * Limitamos o tamanho a 10kb para evitar requisições excessivamente grandes.
 */
app.use(express.json({ limit: '10kb' }));

/**
 * Middleware de logging simples para fins educacionais.
 * Registra método, URL e timestamp de cada requisição.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next();
});

// ============================================================================
// MONTAGEM DAS ROTAS
// ============================================================================
//
 * As rotas são montadas usando app.use() com o caminho base.
 * O Express encadeia automaticamente as rotas do router.
 *
 * A ordem importa: rotas mais específicas devem vir antes de rotas genéricas.

/**
 * Montagem das rotas de livros em /books.
 * Todas as rotas definidas em src/routes/books.js ficam disponíveis
 * sob o prefixo /books (GET /books, POST /books, GET /books/:id, etc.)
 */
app.use('/books', bookRoutes);

/**
 * Montagem das rotas de estatísticas em /stats.
 * Endpoint separado para manter as métricas isoladas das operações CRUD.
 */
app.use('/stats', statsRoutes);

// ============================================================================
// ROTA DE HEALTH CHECK (RAIZ)
// ============================================================================
//
 * A rota raiz (/) serve como health check e documentação básica.
 * É útil para verificar se a API está respondendo e para testadores
 * descobrirem os endpoints disponíveis.

/**
 * @route   GET /
 * @desc    Health check da API — retorna informações de status
 * @access  Public
 * @returns {200} {Object} Status da API e lista de endpoints
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'API de Livros REST — Servidor rodando!',
    endpoints: {
      books: {
        GET: '/books',
        'GET /:id': '/books/:id',
        POST: '/books',
        PUT: '/books/:id',
        DELETE: '/books/:id'
      },
      stats: {
        GET: '/stats'
      }
    }
  });
});

// ============================================================================
// ROTA 404 PARA RECURSOS NÃO ENCONTRADOS
// ============================================================================
//
 * Esta rota captura todas as requisições para caminhos inexistentes.
 * Deve vir DEPOIS de todas as outras rotas, mas ANTES do middleware de erro.
 * Lançamos um NotFoundError para que o middleware de tratamento de erros
 * formate a resposta corretamente.

/**
 * Middleware para rotas não encontradas (404).
 * Captura requisições para caminhos inexistentes.
 */
app.use((req, res, next) => {
  const { NotFoundError } = require('./middleware/errorHandler');
  next(new NotFoundError(`Rota ${req.method} ${req.url} não encontrada`));
});

// ============================================================================
// MIDDLEWARE DE TRATAMENTO DE ERROS (SEMPRE POR ÚLTIMO)
// ============================================================================
//
 * O middleware de erro deve ser o ÚLTIMO app.use() registrado.
 * O Express identifica middlewares de erro pelo número de parâmetros (4).
 * Apenas middlewares com 4 parâmetros são tratados como handlers de erro.
 */
app.use(errorHandler);

// ============================================================================
// INICIALIZAÇÃO DO SERVIDOR
// ============================================================================
const PORT = process.env.PORT || 3000;

/**
 * Inicia o servidor HTTP e faz listen na porta configurada.
 * A mensagem de inicialização confirma que a API está pronta para receber requisições.
 */
app.listen(PORT, () => {
  console.log(`\n✅ API de Livros REST rodando na porta ${PORT}`);
  console.log(`📚 Endpoints disponíveis:`);
  console.log(`   GET    http://localhost:${PORT}/books`);
  console.log(`   POST   http://localhost:${PORT}/books`);
  console.log(`   PUT    http://localhost:${PORT}/books/:id`);
  console.log(`   DELETE http://localhost:${PORT}/books/:id`);
  console.log(`   GET    http://localhost:${PORT}/stats`);
  console.log(`\n📖 Execute 'npm run dev' para rodar em modo desenvolvimento com recarga automática\n`);
});

module.exports = app;
```

