## File 2: `data/books.js` — In-Memory Data Layer

```javascript
/**
 * @fileoverview In-memory data store for books.
 *
 * WHY IN-MEMORY? For an educational API, an in-memory array avoids the complexity
 * of database setup while still demonstrating CRUD operations, ID generation, and
 * data validation. In production, you would replace this module with a database
 * driver (MongoDB, PostgreSQL, etc.) but keep the same interface — this is the
 * Repository Pattern in action.
 *
 * DESIGN CHOICES:
 * - Array of objects: Simple, ordered, easy to iterate for stats/filtering.
 * - Auto-incrementing numeric IDs: Human-readable and intuitive for learners.
 * - Immutable operations (no direct mutation): We return new arrays where possible
 *   to avoid accidental side effects — a good habit even in simple apps.
 */

// ---------------------------------------------------------------------------
// DATA STRUCTURE
// ---------------------------------------------------------------------------
/**
 * @typedef {Object} Book
 * @property {number} id - Unique numeric identifier (auto-incremented).
 * @property {string} title - Book title (required, 1-200 characters).
 * @property {string} author - Author name (required, 1-100 characters).
 * @property {string} [genre] - Book genre (optional, e.g., "Fiction", "Science").
 * @property {number} [publishedYear] - Year of publication (optional, 1000-2100).
 * @property {number} [rating] - Average rating from 1.0 to 5.0 (optional).
 */

/**
 * @type {Book[]} In-memory storage — behaves like a table in a database.
 *
 * WHY AN ARRAY? Arrays provide O(1) access by index and are the most natural
 * representation for a list of books. For a real app with thousands of records,
 * you'd use a database with indexes; here, simplicity wins.
 */
const books = [
  {
    id: 1,
    title: "The Great Gatsby",
    author: "F. Scott Fitzgerald",
    genre: "Fiction",
    publishedYear: 1925,
    rating: 4.5,
  },
  {
    id: 2,
    title: "A Brief History of Time",
    author: "Stephen Hawking",
    genre: "Science",
    publishedYear: 1988,
    rating: 4.8,
  },
  {
    id: 3,
    title: "To Kill a Mockingbird",
    author: "Harper Lee",
    genre: "Fiction",
    publishedYear: 1960,
    rating: 4.9,
  },
];

// ---------------------------------------------------------------------------
// ID GENERATOR
// ---------------------------------------------------------------------------
/**
 * Tracks the highest assigned ID to ensure uniqueness.
 * In production with a database, the DB handles this via AUTO_INCREMENT or UUIDs.
 */
let nextId = 4; // Start after the last seeded ID (3)

/**
 * Generates the next unique book ID.
 * @returns {number} The next available integer ID.
 */
function getNextId() {
  return nextId++;
}

// ---------------------------------------------------------------------------
// CRUD OPERATIONS
// ---------------------------------------------------------------------------

/**
 * Retrieves all books, optionally filtered by query parameters.
 *
 * FILTERING LOGIC:
 * - genre: exact match (case-insensitive)
 * - author: substring match (case-insensitive)
 * - minRating / maxRating: numeric range on the rating field
 * - publishedAfter / publishedBefore: year range
 *
 * WHY RETURN A NEW ARRAY? We use filter() which creates a copy, preserving
 * the original data. This is safer than mutating state directly.
 *
 * @param {Object} [filters] - Optional query parameters for filtering.
 * @param {string} [filters.genre] - Filter by genre (exact match).
 * @param {string} [filters.author] - Filter by author name (substring).
 * @param {number} [filters.minRating] - Minimum rating (1-5).
 * @param {number} [filters.maxRating] - Maximum rating (1-5).
 * @param {number} [filters.publishedAfter] - Published after this year.
 * @param {number} [filters.publishedBefore] - Published before this year.
 * @returns {Book[]} Array of matching books.
 */
function getAllBooks(filters = {}) {
  let result = [...books]; // Copy to avoid mutating the original

  const {
    genre,
    author,
    minRating,
    maxRating,
    publishedAfter,
    publishedBefore,
  } = filters;

  // Apply each filter only if the corresponding parameter was provided.
  // This allows partial filtering — users can mix and match criteria.
  if (genre) {
    result = result.filter(
      (book) => book.genre?.toLowerCase() === genre.toLowerCase()
    );
  }

  if (author) {
    result = result.filter((book) =>
      book.author.toLowerCase().includes(author.toLowerCase())
    );
  }

  if (minRating !== undefined) {
    result = result.filter((book) => book.rating >= minRating);
  }

  if (maxRating !== undefined) {
    result = result.filter((book) => book.rating <= maxRating);
  }

  if (publishedAfter !== undefined) {
    result = result.filter(
      (book) => book.publishedYear > publishedAfter
    );
  }

  if (publishedBefore !== undefined) {
    result = result.filter(
      (book) => book.publishedYear < publishedBefore
    );
  }

  return result;
}

/**
 * Finds a single book by its numeric ID.
 *
 * WHY find() over filter()[0]? The `find()` method is semantically clearer
 * when we expect exactly one match. It also short-circuits (stops at first hit),
 * making it slightly more efficient for large datasets.
 *
 * @param {number} id - The book's unique identifier.
 * @returns {Book | undefined} The matching book, or undefined if not found.
 */
function getBookById(id) {
  return books.find((book) => book.id === id);
}

/**
 * Creates a new book and appends it to the in-memory store.
 *
 * WHY SPREAD OPERATOR? `{ ...newBookData, id: getNextId() }` creates a new
 * object with all properties from `newBookData` plus an auto-generated ID.
 * This avoids mutating the input object — a best practice for pure functions.
 *
 * @param {Omit<Book, 'id'>} bookData - Book data without the id field.
 * @returns {Book} The newly created book with its assigned ID.
 */
function createBook(bookData) {
  const newBook = {
    ...bookData, // Copy all provided properties
    id: getNextId(), // Assign a unique, incrementing ID
  };
  books.push(newBook); // Append to the in-memory array
  return newBook;
}

/**
 * Updates an existing book by ID with partial or full data.
 *
 * WHY PARTIAL UPDATE (PATCH semantics via PUT)? In REST, PUT is traditionally
 * a full replacement, but for simplicity and usability we allow partial updates.
 * The `Object.assign()` pattern merges provided fields while preserving others.
 *
 * @param {number} id - The ID of the book to update.
 * @param {Partial<Book>} updateData - Fields to update (any subset of Book properties).
 * @returns {Book | undefined} The updated book, or undefined if not found.
 */
function updateBook(id, updateData) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return undefined; // Not found

  // Merge existing data with updates — only overwrite provided fields.
  books[index] = { ...books[index], ...updateData };
  return books[index];
}

/**
 * Deletes a book by its ID.
 *
 * WHY splice()? Arrays in JavaScript don't have a built-in `removeById` method,
 * so we find the index and use `splice()` to remove it in-place. This is O(n)
 * but acceptable for small educational datasets.
 *
 * @param {number} id - The ID of the book to delete.
 * @returns {boolean} True if the book was found and deleted, false otherwise.
 */
function deleteBook(id) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1); // Remove one element at the found index
  return true;
}

/**
 * Computes aggregate statistics about the book collection.
 *
 * STATS CALCULATIONS:
 * - totalBooks: Count of all books.
 * - averageRating: Mean of all ratings (excluding undefined).
 * - genreCounts: Object mapping each genre to its book count.
 * - newestBook: Book with the highest publishedYear.
 * - oldestBook: Book with the lowest publishedYear.
 *
 * WHY SEPARATE FUNCTION? Statistics logic is complex and changes independently
 * from CRUD operations. Keeping it separate follows the Single Responsibility
 * Principle and makes testing easier.
 *
 * @returns {Object} Aggregated statistics about the book collection.
 */
function getStats() {
  const totalBooks = books.length;

  // Filter out books without ratings before averaging.
  const ratedBooks = books.filter((book) => book.rating !== undefined);
  const averageRating =
    ratedBooks.length > 0
      ? parseFloat(
          (ratedBooks.reduce((sum, b) => sum + b.rating, 0) / ratedBooks.length).toFixed(2)
        )
      : null;

  // Count books per genre using reduce — a functional programming pattern.
  const genreCounts = books.reduce((acc, book) => {
    const genre = book.genre || "Unknown";
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  // Find newest and oldest by publishedYear.
  const newestBook =
    books.length > 0
      ? books.reduce((newest, book) =>
          (!newest.publishedYear || book.publishedYear > newest.publishedYear)
            ? book
            : newest
        )
      : null;

  const oldestBook =
    books.length > 0
      ? books.reduce((oldest, book) =>
          (!oldest.publishedYear || book.publishedYear < oldest.publishedYear)
            ? book
            : oldest
        )
      : null;

  return {
    totalBooks,
    averageRating,
    genreCounts,
    newestBook,
    oldestBook,
  };
}

// ---------------------------------------------------------------------------
// MODULE EXPORTS
// ---------------------------------------------------------------------------
/**
 * Exports all data-layer functions for use in route handlers.
 *
 * WHY NAMED EXPORTS? Named exports make it explicit which functions are being
 * used where, improving code readability and enabling tree-shaking in bundlers.
 */
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

**Key Design Decisions Explained:**

1. **Repository Pattern**: This module acts as a "repository" — an abstraction over data access. In production, you'd swap this for a MongoDB/PostgreSQL driver without changing the routes.
2. **Pure Functions**: Each function is pure (no side effects except `createBook`/`updateBook`/`deleteBook` which intentionally mutate state). This makes testing trivial.
3. **Immutability Where Possible**: `getAllBooks()` returns a new array via `[...books]`, preventing accidental mutation of the source data.
4. **Filtering Flexibility**: Query parameters are optional — users can filter by any combination or none at all.

