## File 6: `routes/books.js` — Book Route Handlers

```javascript
/**
 * @fileoverview REST route handlers for book resources.
 *
 * ROUTE CONVENTIONS:
 * - GET /books → List all books (with optional filtering)
 * - GET /books/:id → Get a single book by ID
 * - POST /books → Create a new book
 * - PUT /books/:id → Update an existing book (partial update supported)
 * - DELETE /books/:id → Delete a book by ID
 *
 * WHY SEPARATE ROUTE FILE? Keeping routes in their own module follows the
 * separation of concerns principle. The server.js file stays clean, and routes
 * can be tested independently. This also mirrors how Express generators structure
 * real projects.
 *
 * VALIDATION STRATEGY: We validate input in the route handlers using the custom
 * ValidationError class. In a larger app, you might use a library like Joi or
 * Zod for schema validation, but manual validation keeps dependencies minimal.
 */

const express = require("express");
const router = express.Router(); // Creates an independent route handler

const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
} = require("../data/books");
const { ValidationError, NotFoundError } = require("../errors/customErrors");

// ---------------------------------------------------------------------------
// GET /books — List all books with optional filtering
// ---------------------------------------------------------------------------

/**
 * @route GET /books
 * @description Retrieve a list of all books, optionally filtered by query parameters.
 *
 * QUERY PARAMETERS (all optional):
 * - genre: Filter by exact genre match (case-insensitive).
 *   Example: ?genre=Fiction
 * - author: Filter by author name substring (case-insensitive).
 *   Example: ?author=hawking
 * - minRating: Minimum rating (1-5).
 *   Example: ?minRating=4.0
 * - maxRating: Maximum rating (1-5).
 *   Example: ?maxRating=4.5
 * - publishedAfter: Filter books published after this year.
 *   Example: ?publishedAfter=1950
 * - publishedBefore: Filter books published before this year.
 *   Example: ?publishedBefore=2000
 *
 * RESPONSE FORMAT (200 OK):
 * {
 *   "success": true,
 *   "data": [
 *     { "id": 1, "title": "...", "author": "...", ... }
 *   ],
 *   "count": 3
 * }
 *
 * EXAMPLE CURL:
 *   curl http://localhost:3000/books?genre=Fiction&minRating=4.0
 *
 * EXAMPLE POSTMAN:
 *   GET http://localhost:3000/books
 *   Query Params: genre=Fiction, minRating=4.0
 */
router.get("/", (req, res) => {
  try {
    // Extract filter parameters from the query string.
    // Destructuring makes the code readable and ensures we only pass known params.
    const filters = {
      genre: req.query.genre,
      author: req.query.author,
      minRating: req.query.minRating ? parseFloat(req.query.minRating) : undefined,
      maxRating: req.query.maxRating ? parseFloat(req.query.maxRating) : undefined,
      publishedAfter: req.query.publishedAfter ? parseInt(req.query.publishedAfter, 10) : undefined,
      publishedBefore: req.query.publishedBefore ? parseInt(req.query.publishedBefore, 10) : undefined,
    };

    // Call the data layer to get filtered results.
    const books = getAllBooks(filters);

    // Return formatted response with count for easy pagination later.
    res.json({
      success: true,
      data: books,
      count: books.length,
    });
  } catch (error) {
    // If anything goes wrong, pass to the global error handler.
    next(error);
  }
});

// ---------------------------------------------------------------------------
// GET /books/:id — Get a single book by ID
// ---------------------------------------------------------------------------

/**
 * @route GET /books/:id
 * @description Retrieve a single book by its numeric ID.
 *
 * URL PARAMETERS:
 * - id: Numeric book identifier (required).
 *
 * RESPONSE FORMAT (200 OK):
 * {
 *   "success": true,
 *   "data": { "id": 1, "title": "...", ... }
 * }
 *
 * ERROR RESPONSES:
 * - 400 Bad Request: Invalid ID format (not a number).
 * - 404 Not Found: Book with given ID does not exist.
 *
 * EXAMPLE CURL:
 *   curl http://localhost:3000/books/1
 *
 * EXAMPLE POSTMAN:
 *   GET http://localhost:3000/books/1
 */
router.get("/:id", (req, res) => {
  try {
    // Validate that the ID is a valid positive integer.
    const id = parseInt(req.params.id, 10);
    if (isNaN(id) || id < 1) {
      throw new ValidationError("Invalid book ID. Must be a positive integer.", {
        id: "must be a positive integer",
      });
    }

    // Look up the book in the data layer.
    const book = getBookById(id);

    // If not found, throw a NotFoundError (caught by global error handler).
    if (!book) {
      throw new NotFoundError("Book", id);
    }

    res.json({
      success: true,
      data: book,
    });
  } catch (error) {
    next(error);
  }
});

// ---------------------------------------------------------------------------
// POST /books — Create a new book
// ---------------------------------------------------------------------------

/**
 * @route POST /books
 * @description Create a new book with the provided details.
 *
 * REQUEST BODY (JSON):
 * {
 *   "title": "The Catcher in the Rye",    // Required: string, 1-200 chars
 *   "author": "J.D. Salinger",            // Required: string, 1-100 chars
 *   "genre": "Fiction",                   // Optional: string
 *   "publishedYear": 1951,                // Optional: number, 1000-2100
 *   "rating": 4.2                         // Optional: number, 1.0-5.0
 * }
 *
 * RESPONSE FORMAT (201 Created):
 * {
 *   "success": true,
 *   "data": { "id": 4, "title": "...", ... }
 * }
 *
 * ERROR RESPONSES:
 * - 400 Bad Request: Missing or invalid required fields.
 *
 * EXAMPLE CURL:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"1984","author":"George Orwell","genre":"Dystopian","publishedYear":1949,"rating":4.7}'
 *
 * EXAMPLE POSTMAN:
 *   POST http://localhost:3000/books
 *   Headers: Content-Type: application/json
 *   Body (JSON): { "title": "1984", "author": "George Orwell", ... }
 */
router.post("/", (req, res) => {
  try {
    const { title, author, genre, publishedYear, rating } = req.body;

    // Validate required fields.
    if (!title || typeof title !== "string" || title.trim().length < 1) {
      throw new ValidationError("Title is required and must be a non-empty string.", {
        title: "required",
      });
    }
    if (title.length > 200) {
      throw new ValidationError("Title must be at most 200 characters.", {
        title: "max 200 characters",
      });
    }

    if (!author || typeof author !== "string" || author.trim().length < 1) {
      throw new ValidationError("Author is required and must be a non-empty string.", {
        author: "required",
      });
    }
    if (author.length > 100) {
      throw new ValidationError("Author must be at most 100 characters.", {
        author: "max 100 characters",
      });
    }

    // Validate optional numeric fields if provided.
    if (publishedYear !== undefined) {
      const year = parseInt(publishedYear, 10);
      if (isNaN(year) || year < 1000 || year > 2100) {
        throw new ValidationError("Published year must be between 1000 and 2100.", {
          publishedYear: "must be 1000-2100",
        });
      }
    }

    if (rating !== undefined) {
      const ratingNum = parseFloat(rating);
      if (isNaN(ratingNum) || ratingNum < 1.0 || ratingNum > 5.0) {
        throw new ValidationError("Rating must be between 1.0 and 5.0.", {
          rating: "must be 1.0-5.0",
        });
      }
    }

    // Create the book via the data layer.
    const newBook = createBook({
      title: title.trim(),
      author: author.trim(),
      genre: genre ? genre.trim() : undefined,
      publishedYear: publishedYear ? parseInt(publishedYear, 10) : undefined,
      rating: rating ? parseFloat(rating) : undefined,
    });

    // Return 201 Created with the new book data.
    res.status(201).json({
      success: true,
      data: newBook,
    });
  } catch (error) {
    next(error);
  }
});

// ---------------------------------------------------------------------------
// PUT /books/:id — Update an existing book
// ---------------------------------------------------------------------------

/**
 * @route PUT /books/:id
 * @description Update an existing book by ID with partial or full data.
 *
 * URL PARAMETERS:
 * - id: Numeric book identifier (required).
 *
 * REQUEST BODY (JSON) — all fields optional:
 * {
 *   "title": "Updated Title",
 *   "author": "Updated Author",
 *   "genre": "New Genre",
 *   "publishedYear": 2024,
 *   "rating": 4.5
 * }
 *
 * RESPONSE FORMAT (200 OK):
 * {
 *   "success": true,
 *   "data": { "id": 1, "title": "...", ... }
 * }
 *
 * ERROR RESPONSES:
 * - 400 Bad Request: Invalid ID or invalid field values.
 * - 404 Not Found: Book with given ID does not exist.
 *
 * EXAMPLE CURL:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"rating": 4.8}'
 *
 * EXAMPLE POSTMAN:
 *   PUT http://localhost:3000/books/1
 *   Headers: Content-Type: application/json
 *   Body (JSON): { "rating": 4.8 }
 */
router.put("/:id", (req, res) => {
  try {
    // Validate ID format.
    const id = parseInt(req.params.id, 10);
    if (isNaN(id) || id < 1) {
      throw new ValidationError("Invalid book ID. Must be a positive integer.", {
        id: "must be a positive integer",
      });
    }

    // Check if the book exists before attempting update.
    const existingBook = getBookById(id);
    if (!existingBook) {
      throw new NotFoundError("Book", id);
    }

    // Build update object from request body (only include defined fields).
    const updateData = {};
    if (req.body.title !== undefined) {
      if (typeof req.body.title !== "string" || req.body.title.trim().length < 1) {
        throw new ValidationError("Title must be a non-empty string.", {
          title: "required",
        });
      }
      updateData.title = req.body.title.trim();
    }
    if (req.body.author !== undefined) {
      if (typeof req.body.author !== "string" || req.body.author.trim().length < 1) {
        throw new ValidationError("Author must be a non-empty string.", {
          author: "required",
        });
      }
      updateData.author = req.body.author.trim();
    }
    if (req.body.genre !== undefined) {
      updateData.genre = typeof req.body.genre === "string" ? req.body.genre.trim() : undefined;
    }
    if (req.body.publishedYear !== undefined) {
      const year = parseInt(req.body.publishedYear, 10);
      if (isNaN(year) || year < 1000 || year > 2100) {
        throw new ValidationError("Published year must be between 1000 and 2100.", {
          publishedYear: "must be 1000-2100",
        });
      }
      updateData.publishedYear = year;
    }
    if (req.body.rating !== undefined) {
      const ratingNum = parseFloat(req.body.rating);
      if (isNaN(ratingNum) || ratingNum < 1.0 || ratingNum > 5.0) {
        throw new ValidationError("Rating must be between 1.0 and 5.0.", {
          rating: "must be 1.0-5.0",
        });
      }
      updateData.rating = ratingNum;
    }

    // Perform the update.
    const updatedBook = updateBook(id, updateData);

    res.json({
      success: true,
      data: updatedBook,
    });
  } catch (error) {
    next(error);
  }
});

// ---------------------------------------------------------------------------
// DELETE /books/:id — Delete a book
// ---------------------------------------------------------------------------

/**
 * @route DELETE /books/:id
 * @description Delete a book by its numeric ID.
 *
 * URL PARAMETERS:
 * - id: Numeric book identifier (required).
 *
 * RESPONSE FORMAT (200 OK):
 * {
 *   "success": true,
 *   "data": { "id": 1, "title": "...", ... }  // The deleted book
 * }
 *
 * ERROR RESPONSES:
 * - 400 Bad Request: Invalid ID format.
 * - 404 Not Found: Book with given ID does not exist.
 *
 * EXAMPLE CURL:
 *   curl -X DELETE http://localhost:3000/books/1
 *
 * EXAMPLE POSTMAN:
 *   DELETE http://localhost:3000/books/1
 */
router.delete("/:id", (req, res) => {
  try {
    // Validate ID format.
    const id = parseInt(req.params.id, 10);
    if (isNaN(id) || id < 1) {
      throw new ValidationError("Invalid book ID. Must be a positive integer.", {
        id: "must be a positive integer",
      });
    }

    // Check if the book exists before attempting deletion.
    const existingBook = getBookById(id);
    if (!existingBook) {
      throw new NotFoundError("Book", id);
    }

    // Perform the deletion.
    const deleted = deleteBook(id);

    // Return the deleted book data for confirmation.
    res.json({
      success: true,
      data: existingBook,
    });
  } catch (error) {
    next(error);
  }
});

// ---------------------------------------------------------------------------
// MODULE EXPORTS
// ---------------------------------------------------------------------------
module.exports = router;
```

**Route Design Decisions:**

1. **REST Conventions**: We use standard HTTP methods (`GET` for read, `POST` for create, `PUT` for update, `DELETE` for remove). This is universally understood by API consumers and tools like Postman/curl.
2. **Consistent Response Shape**: Every response follows `{ success: boolean, data?: any }` so clients can handle all endpoints with the same parsing logic.
3. **Validation in Routes**: Input validation happens at the route level (not in the data layer) because it's a concern of the API contract, not the storage mechanism. This separation lets you swap the data layer without changing validation logic.
4. **`next(error)` Pattern**: Instead of try/catch in every handler, we throw errors and let the global error handler format responses. This keeps route handlers clean and focused on business logic.

