/**
 * ============================================================
 * MÓDULO: Armazenamento em Memória (Data Store)
 * ============================================================
 *
 * ESCOLHA DA ESTRUTURA DE DADOS:
 *
 * Por que usar um ARRAY em vez de um MAP/Objeto?
 * ------------------------------------------------
 * 1. ORDENAÇÃO IMPLÍCITA: Arrays mantêm a ordem de inserção,
 *    o que é natural para listas de livros (mais recentes primeiro).
 *
 * 2. MÉTODOS NATIVOS RICOS: Arrays oferecem filter(), map(),
 *    findIndex(), splice() etc., facilitando operações CRUD sem
 *    dependências externas.
 *
 * 3. SIMPLICIDADE EDUCACIONAL: Um array é mais fácil de visualizar
 *    e depurar do que um mapa, especialmente para iniciantes.
 *
 * 4. QUANDO USAR MAP EM VEZ DE ARRAY? Em produção com milhares
 *    de registros, um Map oferece busca O(1) por chave. Aqui,
 *    o array é suficiente pois a API é educacional e lida com
 *    dezenas de livros no máximo.
 *
 * POR QUE NÃO USAR BANCO DE DADOS?
 * ---------------------------------
 * Para este exemplo educacional, um banco de dados adicionaria
 * complexidade desnecessária (conexões, migrations, queries SQL).
 * O array em memória permite focar nos conceitos de REST,
 * middleware e tratamento de erros. Em produção, basta substituir
 * este módulo por uma camada de repositório que use PostgreSQL,
 * MongoDB, etc.
 */

/**
 * Array principal que armazena todos os livros.
 * Cada livro é um objeto com as seguintes propriedades:
 *   - id: number (identificador único auto-incrementado)
 *   - title: string (título do livro)
 *   - author: string (autor do livro)
 *   - year: number (ano de publicação)
 *   - genre: string (gênero literário)
 *   - createdAt: string (timestamp ISO da criação)
 *   - updatedAt: string (timestamp ISO da última atualização)
 */
const books = [];

/**
 * Contador privado para gerar IDs únicos.
 * Usamos uma variável closure (não exportada) para garantir que
 * os IDs sejam sempre incrementais e nunca se repitam, mesmo após
 * exclusões. Isso evita colisões de ID que poderiam ocorrer se
 * usássemos Date.now() ou Math.random().
 */
let nextId = 1;

/**
 * ============================================================
 * FUNÇÕES DO STORE
 * ============================================================
 */

/**
 * Retorna todos os livros armazenados.
 * @returns {Array<Object>} Lista de todos os livros
 */
function getAllBooks() {
  return books;
}

/**
 * Busca um livro pelo seu ID numérico.
 * Usa Array.prototype.find() que retorna o PRIMEIRO elemento
 * que satisfaz a condição, ou undefined se não encontrar.
 *
 * @param {number} id - O ID do livro a ser buscado
 * @returns {Object|undefined} O livro encontrado ou undefined
 */
function getBookById(id) {
  return books.find(book => book.id === id);
}

/**
 * Insere um novo livro no array e retorna o objeto completo
 * com os timestamps de criação.
 *
 * A função cloneia o objeto de entrada para evitar mutações
 * externas acidentais ao array interno (imutabilidade parcial).
 *
 * @param {Object} bookData - Dados do novo livro
 * @param {string} bookData.title - Título do livro
 * @param {string} bookData.author - Autor do livro
 * @param {number} bookData.year - Ano de publicação
 * @param {string} bookData.genre - Gênero do livro
 * @returns {Object} O livro criado com id e timestamps
 */
function createBook(bookData) {
  const newBook = {
    id: nextId++,                          // ID único auto-incrementado
    title: bookData.title,
    author: bookData.author,
    year: bookData.year,
    genre: bookData.genre,
    createdAt: new Date().toISOString(),   // Timestamp ISO 8601
    updatedAt: new Date().toISOString()
  };

  books.push(newBook);                     // Adiciona ao final do array
  return newBook;
}

/**
 * Atualiza um livro existente pelo ID.
 * Usa Object.assign() para mesclar os campos fornecidos com o
 * objeto existente, preservando campos não fornecidos (partial update).
 * O timestamp updatedAt é sempre atualizado.
 *
 * @param {number} id - ID do livro a atualizar
 * @param {Object} updates - Campos a serem atualizados
 * @returns {Object|undefined} O livro atualizado ou undefined se não encontrado
 */
function updateBook(id, updates) {
  const index = books.findIndex(book => book.id === id);

  if (index === -1) {
    return undefined;                      // Livro não encontrado
  }

  // Mescla os campos existentes com as atualizações
  books[index] = {
    ...books[index],                       // Espalha campos existentes
    ...updates,                            // Sobrescreve com novos valores
    id: books[index].id,                   // Garante que o ID não mude
    createdAt: books[index].createdAt,     // Preserva timestamp de criação
    updatedAt: new Date().toISOString()    // Atualiza timestamp de modificação
  };

  return books[index];
}

/**
 * Remove um livro do array pelo ID.
 * Usa Array.prototype.splice() que modifica o array original
 * removendo o elemento na posição encontrada.
 *
 * @param {number} id - ID do livro a remover
 * @returns {boolean} true se removido, false se não encontrado
 */
function deleteBook(id) {
  const index = books.findIndex(book => book.id === id);

  if (index === -1) {
    return false;                          // Livro não encontrado
  }

  books.splice(index, 1);                  // Remove 1 elemento na posição encontrada
  return true;
}

/**
 * Calcula estatísticas agregadas sobre o acervo de livros.
 *
 * As estatísticas incluem:
 *   - totalBooks: quantidade total de livros
 *   - totalAuthors: quantidade de autores únicos (Set remove duplicatas)
 *   - averageYear: ano médio de publicação (arredondado)
 *   - booksByGenre: contagem de livros por gênero
 *   - oldestBook: livro mais antigo (menor year)
 *   - newestBook: livro mais recente (maior year)
 *
 * @returns {Object} Estatísticas do acervo
 */
function getStats() {
  const totalBooks = books.length;

  if (totalBooks === 0) {
    return {
      totalBooks: 0,
      totalAuthors: 0,
      averageYear: null,
      booksByGenre: {},
      oldestBook: null,
      newestBook: null
    };
  }

  // Set coleta autores únicos automaticamente (elimina duplicatas)
  const uniqueAuthors = new Set(books.map(book => book.author)).size;

  // Cálculo da média do ano de publicação
  const averageYear = Math.round(
    books.reduce((sum, book) => sum + book.year, 0) / totalBooks
  );

  // Agrupamento por gênero usando reduce (padrão funcional)
  const booksByGenre = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  // Livros mais antigo e mais recente por ano de publicação
  const oldestBook = books.reduce((min, book) =>
    book.year < min.year ? book : min
  );
  const newestBook = books.reduce((max, book) =>
    book.year > max.year ? book : max
  );

  return {
    totalBooks,
    totalAuthors,
    averageYear,
    booksByGenre,
    oldestBook,
    newestBook
  };
}

/**
 * Exporta todas as funções do store como um módulo CommonJS.
 * Usamos exports em vez de module.exports = {} para permitir
 * que novos módulos importem apenas o que precisam (tree-shaking
 * em bundlers modernos).
 */
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats
};
```

