## Arquivo 3: `src/middleware/errors.js`

```javascript
/**
 * ============================================================
 * MÓDULO: Middleware de Tratamento de Erros
 * ============================================================
 *
 * PADRÃO ADOTADO: Classe Error Personalizada + Middleware Express
 *
 * Por que criar uma classe Error personalizada?
 * ----------------------------------------------
 * 1. CÓDIGO DE STATUS SEMÂNTICO: Cada subclasse carrega seu
 *    próprio HTTP status code, eliminando a necessidade de
 *    passar o código manualmente em cada throw.
 *
 * 2. PROPRIEDADES RICAS: Podemos adicionar campos como
 *    `isOperational` (erro esperado vs. erro do sistema) e
 *    `details` (informações adicionais para debugging).
 *
 * 3. CENTRALIZAÇÃO: O middleware de erros captura TODOS os
 *    erros não tratados, garantindo que a API nunca retorne
 *    o stack trace bruto em produção (segurança).
 *
 * POR QUE USAR MIDDLEWARE DE ERROS NO EXPRESS?
 * ---------------------------------------------
 * Express tem um padrão especial para middlewares de erro:
 * funções com 4 parâmetros (err, req, res, next). Quando um
 * erro é passado via next(err), o Express pula todos os
 * middlewares normais e vai direto para este. Isso permite
 * tratar erros de forma centralizada em UM único lugar,
 * em vez de repetir try/catch em cada rota.
 */

/**
 * Classe base para erros operacionais da aplicação.
 * Erros operacionais são aqueles esperados (input inválido,
 * recurso não encontrado) e devem ser tratados com mensagens
 * amigáveis ao usuário, sem expor detalhes internos.
 *
 * @extends Error
 */
class AppError extends Error {
  /**
   * @param {string} message - Mensagem de erro para o cliente
   * @param {number} statusCode - Código HTTP de status (padrão: 500)
   */
  constructor(message, statusCode = 500) {
    super(message);                       // Chama construtor da classe Error
    this.statusCode = statusCode;          // Código HTTP para resposta
    this.isOperational = true;             // Indica que é erro esperado
  }
}

/**
 * Subclasse para erros de recurso não encontrado.
 * Padrão REST: 404 Not Found quando o recurso solicitado não existe.
 */
class NotFoundError extends AppError {
  constructor(resource) {
    super(`${resource} não encontrado`, 404);
  }
}

/**
 * Subclasse para erros de validação de input.
 * Padrão REST: 400 Bad Request quando o cliente envia dados inválidos.
 */
class ValidationError extends AppError {
  constructor(message) {
    super(message, 400);
  }
}

/**
 * Subclasse para erros de método não permitido.
 * Padrão REST: 405 Method Not Allowed quando a rota existe mas o
 * método HTTP usado não é suportado.
 */
class MethodNotAllowedError extends AppError {
  constructor(method) {
    super(`Método ${method} não permitido para este endpoint`, 405);
  }
}

/**
 * ============================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS (Express)
 * ============================================================
 *
 * Este middleware deve ser o ÚLTIMO a ser registrado no Express,
 * após todas as rotas. Ele captura erros lançados em qualquer
 * rota ou middleware anterior.
 *
 * A função verifica se o erro é uma instância de AppError:
 *   - Se SIM (erro operacional): retorna JSON amigável com status correto
 *   - Se NÃO (erro inesperado): retorna 500 genérico sem expor detalhes
 *
 * Isso protege a aplicação de vazar stack traces e informações
 * internas para o cliente em produção.
 */

/**
 * Middleware central de tratamento de erros do Express.
 *
 * @param {Error} err - O erro capturado
 * @param {import('express').Request} req - Objeto Request do Express
 * @param {import('express').Response} res - Objeto Response do Express
 * @param {import('express').NextFunction} next - Função next do Express
 */
function errorHandler(err, req, res, next) {
  // Log do erro no servidor para debugging (nunca enviar ao cliente)
  console.error(`[ERROR] ${err.message}`);
  if (process.env.NODE_ENV === 'development') {
    console.error(err.stack);             // Stack trace apenas em dev
  }

  // Erros operacionais (esperados): resposta amigável
  if (err.isOperational) {
    return res.status(err.statusCode).json({
      success: false,
      error: err.message,
      statusCode: err.statusCode
    });
  }

  // Erros não operacionais (bugs do sistema): resposta genérica segura
  return res.status(500).json({
    success: false,
    error: 'Erro interno do servidor. Por favor, tente novamente mais tarde.',
    statusCode: 500
  });
}

/**
 * Middleware de validação de input para campos obrigatórios.
 *
 * Este middleware é reutilizável em qualquer rota que precise
 * validar campos obrigatórios no body da requisição.
 *
 * @param {Array<string>} fields - Lista de campos obrigatórios a verificar
 * @returns {Function} Middleware Express
 */
function validateRequiredFields(fields) {
  return (req, res, next) => {
    // Filtra os campos que estão ausentes ou vazios
    const missing = fields.filter(field => {
      const value = req.body[field];
      return value === undefined || value === null || value === '';
    });

    if (missing.length > 0) {
      // Retorna erro de validação com lista dos campos faltantes
      return next(new ValidationError(
        `Campos obrigatórios ausentes: ${missing.join(', ')}`
      ));
    }

    next();                               // Todos os campos presentes, continua
  };
}

/**
 * Middleware para validar o formato do ID na URL.
 *
 * Em REST, IDs numéricos são convencionais para recursos simples.
 * Este middleware garante que o parâmetro :id seja um número
 * inteiro positivo antes de chegar à rota.
 *
 * @returns {Function} Middleware Express
 */
function validateIdParam() {
  return (req, res, next) => {
    const id = parseInt(req.params.id, 10);

    // Verifica se o parsing foi bem-sucedido e é um número válido
    if (isNaN(id) || id < 1 || !Number.isInteger(id)) {
      return next(new ValidationError('ID deve ser um número inteiro positivo'));
    }

    // Substitui o parâmetro string pelo número parseado
    req.params.id = id;
    next();
  };
}

/**
 * Middleware para logging de requisições (debug).
 *
 * Registra método, URL e timestamp de cada requisição.
 * Útil para debugging e monitoramento básico.
 *
 * @param {import('express').Request} req
 * @param {import('express').Response} res
 * @param {import('express').NextFunction} next
 */
function requestLogger(req, res, next) {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.url}`);
  next();
}

/**
 * Middleware para lidar com rotas não encontradas (404).
 *
 * Se nenhuma rota corresponder à URL solicitada, este middleware
 * é chamado após todas as rotas definidas. Retorna 404 com JSON.
 *
 * @param {import('express').Request} req
 * @param {import('express').Response} res
 * @param {import('express').NextFunction} next
 */
function notFoundHandler(req, res, next) {
  next(new NotFoundError(`Rota ${req.method} ${req.url}`));
}

// Exporta classes de erro e middlewares
module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  MethodNotAllowedError,
  errorHandler,
  validateRequiredFields,
  validateIdParam,
  requestLogger,
  notFoundHandler
};
```

