```javascript
/**
 * ============================================================
 * MÓDULO: Rotas de Livros (RESTful)
 * ============================================================
 *
 * CONVENÇÕES REST ADOTADAS:
 *
 * 1. NOMENCLATURA DE ROTAS: Usamos substantivos no plural (/books)
 *    para representar coleções, e singular com ID (/books/:id)
 *    para recursos individuais. Isso segue a convenção padrão da
 *    indústria (RFC 7231, REST API Design).
 *
 * 2. MÉTODOS HTTP SEMÂNTICOS:
 *    - GET    = leitura (seguro e idempotente)
 *    - POST   = criação (não idempotente, gera novo recurso)
 *    - PUT    = atualização completa (idempotente)
 *    - DELETE = remoção (idempotente)
 *
 * 3. CÓDIGOS DE STATUS:
 *    - 200 OK       = sucesso em leitura/atualização
 *    - 201 Created  = sucesso em criação (com Location header)
 *    - 204 No Content = sucesso em remoção (sem body)
 *    - 400 Bad Request = input inválido
 *    - 404 Not Found = recurso inexistente
 *
 * 4. FILTRAGEM: Query parameters (?author=...&genre=...) permitem
 *    filtragem sem criar novas rotas, mantendo a API RESTful.
 *
 * POR QUE USAR express.Router()?
 * -------------------------------
 * O Router permite encapsular um conjunto de rotas em um módulo
 * separado, facilitando a organização e reutilização. Em projetos
 * maiores, cada entidade teria seu próprio arquivo de rotas.
 */

const express = require('express');

// Importa o store (camada de dados)
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats
} = require('../data/store');

// Importa middlewares de validação e erro
const {
  validateRequiredFields,
  validateIdParam,
  ValidationError
} = require('../middleware/errors');

// Cria um roteador Express para as rotas de livros
const router = express.Router();

/**
 * ============================================================
 * GET /books
 * Listar todos os livros com filtragem opcional
 * ============================================================
 *
 * QUERY PARAMETERS (opcionais):
 *   - author: filtra por autor (case-insensitive)
 *   - genre:  filtra por gênero
 *   - minYear: ano mínimo de publicação
 *   - maxYear: ano máximo de publicação
 *
 * EXEMPLOS DE USO:
 *
 *   curl http://localhost:3000/books
 *   // Retorna todos os livros
 *
 *   curl "http://localhost:3000/books?author=Clarice&genre=Ficção"
 *   // Filtra por autor E gênero
 *
 *   curl "http://localhost:3000/books?minYear=2000&maxYear=2010"
 *   // Filtra por faixa de ano
 *
 * RESPOSTA (200 OK):
 * {
 *   "success": true,
 *   "count": 2,
 *   "data": [ ...livros... ]
 * }
 */
router.get('/books', (req, res) => {
  // Obtém todos os livros do store
  let result = getAllBooks();

  // Filtragem por autor (case-insensitive usando toLowerCase)
  if (req.query.author) {
    const authorFilter = req.query.author.toLowerCase();
    result = result.filter(book =>
      book.author.toLowerCase().includes(authorFilter)
    );
  }

  // Filtragem por gênero
  if (req.query.genre) {
    const genreFilter = req.query.genre.toLowerCase();
    result = result.filter(book =>
      book.genre.toLowerCase() === genreFilter
    );
  }

  // Filtragem por faixa de ano
  if (req.query.minYear) {
    const minYear = parseInt(req.query.minYear, 10);
    result = result.filter(book => book.year >= minYear);
  }

  if (req.query.maxYear) {
    const maxYear = parseInt(req.query.maxYear, 10);
    result = result.filter(book => book.year <= maxYear);
  }

  // Resposta padronizada com metadados de contagem
  res.json({
    success: true,
    count: result.length,
    data: result
  });
});

/**
 * ============================================================
 * GET /books/stats
 * Retornar estatísticas do acervo
 * ============================================================
 *
 * EXEMPLO DE USO:
 *
 *   curl http://localhost:3000/books/stats
 *
 * RESPOSTA (200 OK):
 * {
 *   "success": true,
 *   "data": {
 *     "totalBooks": 5,
 *     "totalAuthors": 4,
 *     "averageYear": 2005,
 *     "booksByGenre": { "Ficção": 2, "Não-ficção": 3 },
 *     "oldestBook": { ... },
 *     "newestBook": { ... }
 *   }
 * }
 */
router.get('/books/stats', (req, res) => {
  const stats = getStats();

  res.json({
    success: true,
    data: stats
  });
});

/**
 * ============================================================
 * GET /books/:id
 * Obter um livro específico pelo ID
 * ============================================================
 *
 * PARÂMETROS DE URL:
 *   - id: número inteiro positivo (validado pelo middleware)
 *
 * EXEMPLOS DE USO:
 *
 *   curl http://localhost:3000/books/1
 *   // Retorna o livro com ID 1
 *
 *   curl http://localhost:3000/books/999
 *   // Retorna 404 (livro não encontrado)
 *
 * RESPOSTA (200 OK):
 * {
 *   "success": true,
 *   "data": {
 *     "id": 1,
 *     "title": "Dom Casmurro",
 *     "author": "Machado de Assis",
 *     "year": 1899,
 *     "genre": "Romance",
 *     "createdAt": "2024-01-15T10:30:00.000Z",
 *     "updatedAt": "2024-01-15T10:30:00.000Z"
 *   }
 * }
 */
router.get('/books/:id', validateIdParam(), (req, res) => {
  const book = getBookById(req.params.id);

  if (!book) {
    // Lança erro que será capturado pelo middleware de erros
    throw new ValidationError(`Livro com ID ${req.params.id} não encontrado`);
  }

  res.json({
    success: true,
    data: book
  });
});

/**
 * ============================================================
 * POST /books
 * Criar um novo livro
 * ============================================================
 *
 * BODY (JSON):
 * {
 *   "title": "String obrigatória",
 *   "author": "String obrigatória",
 *   "year": 2024,
 *   "genre": "String obrigatória"
 * }
 *
 * EXEMPLOS DE USO:
 *
 *   curl -X POST http://localhost:3000/books \
 *     -H "Content-Type: application/json" \
 *     -d '{"title":"1984","author":"George Orwell","year":1949,"genre":"Distopia"}'
 *
 * RESPOSTA (201 Created):
 * {
 *   "success": true,
 *   "data": { ...livro criado com id e timestamps... },
 *   "message": "Livro criado com sucesso"
 * }
 */
router.post('/books',
  // Valida campos obrigatórios antes de processar a requisição
  validateRequiredFields(['title', 'author', 'year', 'genre']),
  (req, res) => {
    const bookData = req.body;

    // Validação adicional: ano deve ser um número válido
    if (typeof bookData.year !== 'number' || bookData.year < 0 || bookData.year > new Date().getFullYear() + 1) {
      throw new ValidationError('Ano de publicação deve ser um número entre 0 e o ano atual');
    }

    // Cria o livro no store
    const newBook = createBook(bookData);

    // 201 Created é o código padrão para recursos criados com sucesso
    res.status(201).json({
      success: true,
      data: newBook,
      message: 'Livro criado com sucesso'
    });
  }
);

/**
 * ============================================================
 * PUT /books/:id
 * Atualizar completamente um livro existente
 * ============================================================
 *
 * NOTA SOBRE PUT vs PATCH:
 * - PUT = atualização COMPLETA (o cliente envia todos os campos)
 * - PATCH = atualização PARCIAL (apenas os campos que mudam)
 *
 * Para este exemplo educacional, usamos PUT com comportamento
 * de partial update (campos não enviados são preservados).
 * Em produção, você poderia ter rotas separadas para PUT e PATCH.
 *
 * BODY (JSON):
 * {
 *   "title": "Novo título",
 *   "author": "Novo autor",
 *   "year": 2025,
 *   "genre": "Novo gênero"
 * }
 *
 * EXEMPLOS DE USO:
 *
 *   curl -X PUT http://localhost:3000/books/1 \
 *     -H "Content-Type: application/json" \
 *     -d '{"title":"Dom Casmurro (Ed. Definitiva)","year":1902}'
 *
 * RESPOSTA (200 OK):
 * {
 *   "success": true,
 *   "data": { ...livro atualizado... },
 *   "message": "Livro atualizado com sucesso"
 * }
 */
router.put('/books/:id',
  validateIdParam(),
  (req, res) => {
    const updatedBook = updateBook(req.params.id, req.body);

    if (!updatedBook) {
      throw new ValidationError(`Livro com ID ${req.params.id} não encontrado`);
    }

    res.json({
      success: true,
      data: updatedBook,
      message: 'Livro atualizado com sucesso'
    });
  }
);

/**
 * ============================================================
 * DELETE /books/:id
 * Excluir um livro pelo ID
 * ============================================================
 *
 * EXEMPLOS DE USO:
 *
 *   curl -X DELETE http://localhost:3000/books/1
 *
 * RESPOSTA (204 No Content):
 * // Corpo vazio — padrão REST para operações de remoção bem-sucedidas
 */
router.delete('/books/:id',
  validateIdParam(),
  (req, res) => {
    const deleted = deleteBook(req.params.id);

    if (!deleted) {
      throw new ValidationError(`Livro com ID ${req.params.id} não encontrado`);
    }

    // 204 No Content: sucesso sem corpo de resposta
    res.status(204).send();
  }
);

// Exporta o roteador para ser usado no app principal
module.exports = router;
```

