```javascript
/**
 * ============================================================
 * MÓDULO: Configuração da Aplicação Express
 * ============================================================
 *
 * PADRÃO ADOTADO: Separação de responsabilidades
 *
 * Por que separar app.js do index.js?
 * ------------------------------------
 * - index.js = ponto de entrada (inicia o servidor, define porta)
 * - app.js   = configuração da aplicação (middlewares, rotas)
 *
 * Esta separação segue a convenção do boilerplate Express padrão
 * e facilita testes unitários (podemos testar o app sem iniciar
 * o servidor).
 */

const express = require('express');

// Importa as rotas de livros
const bookRoutes = require('./routes/books');

// Importa middlewares de erro
const { errorHandler, requestLogger, notFoundHandler } = require('./middleware/errors');

// Cria a instância do aplicativo Express
const app = express();

/**
 * ============================================================
 * MIDDLEWARES GLOBAIS
 * ============================================================
 *
 * ORDEM DE REGISTRO É IMPORTANTE no Express:
 * 1. Middlewares de parsing (body-parser) — devem vir primeiro
 * 2. Middlewares de logging/debug — antes das rotas
 * 3. Rotas — após middlewares globais
 * 4. Middleware de erros — SEMPRE por último
 */

/**
 * express.json() — Parser de body JSON.
 *
 * Este middleware analisa o corpo da requisição quando o Content-Type
 * é application/json e popula req.body com o objeto JavaScript.
 * Limitamos a 10kb para evitar requisições excessivamente grandes.
 */
app.use(express.json({ limit: '10kb' }));

/**
 * express.urlencoded() — Parser de body URL-encoded.
 *
 * Útil para formulários HTML ou requests com Content-Type
 * application/x-www-form-urlencoded.
 */
app.use(express.urlencoded({ extended: true }));

/**
 * Middleware de logging de requisições.
 * Registra método, URL e timestamp de cada request.
 */
app.use(requestLogger);

/**
 * ============================================================
 * ROTAS
 * ============================================================
 *
 * As rotas são registradas APÓS os middlewares globais.
 * O Router importado de ./routes/books já contém todas as
 * rotas definidas com seus métodos HTTP e handlers.
 */
app.use('/books', bookRoutes);

/**
 * ============================================================
 * MIDDLEWARES DE ERRO (SEMPRE POR ÚLTIMO)
 * ============================================================
 *
 * ORDEM CRÍTICA:
 * 1. notFoundHandler — captura rotas inexistentes (404)
 * 2. errorHandler — captura erros lançados em rotas/middlewares
 *
 * Se errorHandler viesse antes de notFoundHandler, ele capturaria
 * o erro 404 antes que a rota específica fosse verificada.
 */
app.use(notFoundHandler);
app.use(errorHandler);

// Exporta a instância do app para testes e para index.js
module.exports = app;
```

