/**
 * ============================================================
 * PONTO DE ENTRADA DA APLICAÇÃO
 * ============================================================
 *
 * Este arquivo é o "main" da aplicação. Sua única responsabilidade
 * é iniciar o servidor HTTP e ouvir na porta configurada.
 *
 * POR QUE USAR process.env.PORT || 3000?
 * ----------------------------------------
 * Em ambientes de produção (Heroku, AWS, Docker), a porta é
 * frequentemente definida pela variável de ambiente PORT.
 * O operador || fornece um fallback para 3000 em desenvolvimento
 * local, onde nenhuma variável de ambiente está configurada.
 */

const app = require('./app');

// Define a porta com fallback para 3000
const PORT = process.env.PORT || 3000;

/**
 * Inicia o servidor HTTP e faz log do endereço de escuta.
 *
 * O callback é executado SOMENTE quando o servidor começa a
 * aceitar conexões, garantindo que não tentamos fazer nada
 * antes da rede estar pronta.
 */
const server = app.listen(PORT, () => {
  console.log(`
╔══════════════════════════════════════════════════════╗
║     API REST de Livros — Servidor Rodando!           ║
║                                                      ║
║  Endereço: http://localhost:${PORT}                   ║
║  Ambiente: ${process.env.NODE_ENV || 'development'}                          ║
╚══════════════════════════════════════════════════════╝
  `);
});

/**
 * Tratamento de erros não capturados no processo Node.js.
 *
 * process.on('uncaughtException') captura erros que escaparam
 * de todos os try/catch e middlewares. Em produção, o ideal é
 * matar o processo e deixar um orchestrator (PM2, Kubernetes)
 * reiniciá-lo automaticamente.
 */
process.on('uncaughtException', (err) => {
  console.error('[UNCAUGHT EXCEPTION]', err);
  process.exit(1);                            // Sai com código de erro
});

/**
 * Tratamento de promessas rejeitadas não capturadas.
 *
 * Node.js não mata o processo por promise rejection por padrão,
 * mas logamos para debugging. Em produção, use um handler global
 * como o 'domain' module ou bibliotecas como 'express-async-errors'.
 */
process.on('unhandledRejection', (reason, promise) => {
  console.error('[UNHANDLED REJECTION]', reason);
});

// Exporta o server para testes que precisam iniciar/parar o servidor
module.exports = server;
```

