## File 2: `src/utils/errors.js` — Custom Error Classes

```javascript
/**
 * @fileoverview Custom error classes for consistent API error handling.
 *
 * WHY custom errors? Standard JavaScript Error objects don't carry HTTP status
 * codes or structured messages. By extending Error and adding properties like
 * statusCode and isOperational, we can create middleware that automatically
 * translates these into proper HTTP responses — keeping client feedback clear
 * and consistent across all endpoints.
 */

/**
 * BaseError — extends the native Error class with HTTP-specific metadata.
 *
 * @param {string} message - Human-readable error description.
 * @param {number} statusCode - HTTP status code (e.g., 400, 404).
 * @param {boolean} [isOperational=true] - Indicates whether the error is expected
 *        (true) vs. an unexpected system failure (false). Operational errors are
 *        logged but not sent to external monitoring; non-operational ones trigger
 *        alerts because they suggest bugs in our code.
 */
class BaseError extends Error {
  constructor(message, statusCode, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;

    // Capture the stack trace for debugging. Setting captureStackTrace on the
    // current class ensures the stack points to where the error was thrown, not
    // inside the Error constructor itself — critical for accurate logs.
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * NotFoundError — thrown when a requested resource doesn't exist.
 *
 * Example: GET /books/999 when only books with IDs 1–5 exist.
 * HTTP 404 is the standard response for "resource not found."
 */
class NotFoundError extends BaseError {
  constructor(resource, id) {
    // Format a clear message so clients know exactly what was missing.
    super(`${resource} with id ${id} not found`, 404);
  }
}

/**
 * ValidationError — thrown when client input fails validation rules.
 *
 * Example: POST /books with an empty title or invalid genre.
 * HTTP 400 signals a bad request; the message tells the client what to fix.
 */
class ValidationError extends BaseError {
  constructor(message) {
    super(message, 400);
  }
}

/**
 * InternalServerError — thrown for unexpected server-side failures.
 *
 * WHY separate from NotFound/Validation? Clients should never see stack traces
 * or internal details. This class ensures we return a generic message (500) while
 * logging the real error internally for debugging. It also marks isOperational =
 * false so monitoring tools can alert us to genuine bugs.
 */
class InternalServerError extends BaseError {
  constructor(message = 'An unexpected error occurred') {
    super(message, 500, false); // false = non-operational; triggers alerts
  }
}

// Export all error classes for use across the application.
module.exports = {
  BaseError,
  NotFoundError,
  ValidationError,
  InternalServerError,
};
```

