## File 3: `src/data/books.js` — In-Memory Data Store

```javascript
/**
 * @fileoverview In-memory storage layer for book data.
 *
 * WHY in-memory? For this educational example, an array avoids external
 * dependencies (no database setup) while still demonstrating CRUD operations.
 * In production, you'd replace this with a real database (PostgreSQL, MongoDB,
 * etc.) — the interface here would stay the same, making swapping easy.
 *
 * Data structure choice: An array of objects is simple and supports O(n) search
 * by ID. For larger datasets, a Map or object keyed by ID would give O(1) lookups.
 * We use an array to keep the code accessible for learners.
 */

// Array that holds all book records. Each book is an object with:
//   - id: unique numeric identifier (auto-incremented)
//   - title: string, required
//   - author: string, required
//   - genre: string (e.g., 'Fiction', 'Science')
//   - publishedYear: number (e.g., 2023)
//   - rating: number between 1 and 5
const books = [];

// Track the next ID to assign. Starting at 1 ensures IDs are positive integers.
let nextId = 1;

/**
 * Retrieves all books, optionally filtered by query parameters.
 *
 * @param {Object} [filters] - Query filters from req.query.
 * @param {string} [filters.genre] - Filter by exact genre match (case-insensitive).
 * @param {number} [filters.minRating] - Minimum rating (1-5).
 * @param {number} [filters.maxYear] - Maximum published year.
 * @returns {Array<Object>} Array of matching book objects.
 *
 * WHY return a new array? Filtering creates a subset; returning the original
 * reference could allow accidental mutation. We also clone each object to ensure
 * consumers can't modify internal state directly.
 */
function getAllBooks(filters = {}) {
  let result = books;

  // Apply genre filter if provided — case-insensitive comparison for usability.
  if (filters.genre) {
    const normalizedGenre = filters.genre.toLowerCase();
    result = result.filter((book) => book.genre.toLowerCase() === normalizedGenre);
  }

  // Apply minimum rating filter if provided.
  if (filters.minRating !== undefined) {
    const minRating = Number(filters.minRating);
    result = result.filter((book) => book.rating >= minRating);
  }

  // Apply maximum published year filter if provided.
  if (filters.maxYear !== undefined) {
    const maxYear = Number(filters.maxYear);
    result = result.filter((book) => book.publishedYear <= maxYear);
  }

  // Return a shallow copy of the filtered array to prevent external mutation.
  return result.map((book) => ({ ...book }));
}

/**
 * Retrieves a single book by its ID.
 *
 * @param {number} id - The unique identifier of the book.
 * @returns {Object|null} The book object if found, otherwise null.
 */
function getBookById(id) {
  return books.find((book) => book.id === id) || null;
}

/**
 * Creates a new book and adds it to the store.
 *
 * @param {Object} bookData - The book data to insert.
 * @param {string} bookData.title - Book title (required).
 * @param {string} bookData.author - Author name (required).
 * @param {string} [bookData.genre] - Genre of the book.
 * @param {number} [bookData.publishedYear] - Year published.
 * @param {number} [bookData.rating] - Rating from 1 to 5.
 * @returns {Object} The newly created book object with an assigned ID.
 */
function createBook(bookData) {
  const newBook = {
    id: nextId++, // Auto-increment ID; simple and predictable for this example.
    title: bookData.title,
    author: bookData.author,
    genre: bookData.genre || 'Unknown', // Default to 'Unknown' if not provided.
    publishedYear: bookData.publishedYear || null,
    rating: bookData.rating || null,
  };

  books.push(newBook);
  return { ...newBook }; // Return a copy to prevent external mutation.
}

/**
 * Updates an existing book by ID.
 *
 * @param {number} id - The ID of the book to update.
 * @param {Object} updates - Fields to update (partial object).
 * @returns {Object|null} The updated book if found, otherwise null.
 */
function updateBook(id, updates) {
  const index = books.findIndex((book) => book.id === id);

  if (index === -1) return null; // Book not found.

  // Merge existing data with updates; only overwrite provided fields.
  books[index] = { ...books[index], ...updates };
  return { ...books[index] }; // Return a copy.
}

/**
 * Deletes a book by ID.
 *
 * @param {number} id - The ID of the book to delete.
 * @returns {boolean} True if the book was deleted, false if not found.
 */
function deleteBook(id) {
  const index = books.findIndex((book) => book.id === id);

  if (index === -1) return false; // Book not found.

  books.splice(index, 1); // Remove from array by index.
  return true;
}

/**
 * Computes aggregate statistics about the book collection.
 *
 * @returns {Object} Statistics including total count, average rating, genre distribution, etc.
 */
function getStats() {
  const totalBooks = books.length;

  // Calculate average rating (only for books that have a rating).
  const ratedBooks = books.filter((book) => book.rating !== null);
  const averageRating =
    ratedBooks.length > 0
      ? parseFloat(
          (ratedBooks.reduce((sum, book) => sum + book.rating, 0) / ratedBooks.length).toFixed(2)
        )
      : null;

  // Count books per genre.
  const genreCounts = {};
  books.forEach((book) => {
    const genre = book.genre || 'Unknown';
    genreCounts[genre] = (genreCounts[genre] || 0) + 1;
  });

  // Find the most common genre.
  let mostCommonGenre = null;
  let maxCount = 0;
  Object.entries(genreCounts).forEach(([genre, count]) => {
    if (count > maxCount) {
      maxCount = count;
      mostCommonGenre = genre;
    }
  });

  return {
    totalBooks,
    averageRating,
    mostCommonGenre,
    genreDistribution: genreCounts,
    booksWithRatings: ratedBooks.length,
  };
}

// Export all data-access functions. This keeps the module focused and testable.
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

