## File 4: `src/middleware/validation.js` — Request Validation Middleware

```javascript
/**
 * @fileoverview Validation middleware for POST and PUT requests.
 *
 * WHY validate input? Clients can send malformed or missing data. Validation
 * ensures our API only processes well-formed requests, preventing errors downstream
 * and providing clear feedback to clients about what went wrong.
 */

const { ValidationError } = require('../utils/errors');

/**
 * Validates the body of a POST /books request.
 *
 * @param {Object} req - Express request object.
 * @param {Object} res - Express response object (unused here).
 * @param {Function} next - Express next middleware function.
 * @throws {ValidationError} If required fields are missing or invalid.
 */
function validateCreateBook(req, res, next) {
  const { title, author } = req.body;

  // Check for required fields — both title and author must be present strings.
  if (!title || typeof title !== 'string' || title.trim() === '') {
    return next(new ValidationError('Title is required and must be a non-empty string'));
  }

  if (!author || typeof author !== 'string' || author.trim() === '') {
    return next(new ValidationError('Author is required and must be a non-empty string'));
  }

  // Optional fields: validate types if provided.
  if (req.body.genre !== undefined && typeof req.body.genre !== 'string') {
    return next(new ValidationError('Genre must be a string'));
  }

  if (req.body.publishedYear !== undefined) {
    const year = Number(req.body.publishedYear);
    if (!Number.isInteger(year) || year < 0 || year > new Date().getFullYear() + 1) {
      return next(new ValidationError('Published year must be a valid integer between 0 and current year'));
    }
  }

  if (req.body.rating !== undefined) {
    const rating = Number(req.body.rating);
    if (typeof rating !== 'number' || rating < 1 || rating > 5) {
      return next(new ValidationError('Rating must be a number between 1 and 5'));
    }
  }

  // All validations passed; proceed to the route handler.
  next();
}

/**
 * Validates the body of a PUT /books/:id request.
 *
 * Unlike POST, all fields are optional for updates (partial update).
 * However, if provided, each field must be valid.
 *
 * @param {Object} req - Express request object.
 * @param {Object} res - Express response object (unused here).
 * @param {Function} next - Express next middleware function.
 * @throws {ValidationError} If any provided fields are invalid.
 */
function validateUpdateBook(req, res, next) {
  const body = req.body;

  // Only validate fields that were actually provided.
  if (body.title !== undefined) {
    if (typeof body.title !== 'string' || body.title.trim() === '') {
      return next(new ValidationError('Title must be a non-empty string'));
    }
  }

  if (body.author !== undefined) {
    if (typeof body.author !== 'string' || body.author.trim() === '') {
      return next(new ValidationError('Author must be a non-empty string'));
    }
  }

  if (body.genre !== undefined && typeof body.genre !== 'string') {
    return next(new ValidationError('Genre must be a string'));
  }

  if (body.publishedYear !== undefined) {
    const year = Number(body.publishedYear);
    if (!Number.isInteger(year) || year < 0 || year > new Date().getFullYear() + 1) {
      return next(new ValidationError('Published year must be a valid integer between 0 and current year'));
    }
  }

  if (body.rating !== undefined) {
    const rating = Number(body.rating);
    if (typeof rating !== 'number' || rating < 1 || rating > 5) {
      return next(new ValidationError('Rating must be a number between 1 and 5'));
    }
  }

  next();
}

// Export validation middleware functions.
module.exports = {
  validateCreateBook,
  validateUpdateBook,
};
```

