## File 5: `src/middleware/errorHandler.js` — Global Error-Handling Middleware

```javascript
/**
 * @fileoverview Centralized error-handling middleware for Express.
 *
 * WHY a single error handler? Without it, every route would need its own try-catch
 * and response logic, leading to duplicated code and inconsistent error formats.
 * Express supports a special 4-argument middleware function (err, req, res, next)
 * that catches errors thrown anywhere in the pipeline — including async routes.
 *
 * This middleware:
 *   - Returns JSON responses with consistent structure for all errors.
 *   - Logs operational errors at WARN level and non-operational ones at ERROR.
 *   - Prevents stack traces from leaking to clients (security best practice).
 */

const { InternalServerError } = require('../utils/errors');

/**
 * Global error-handling middleware.
 *
 * @param {Error} err - The error object caught by Express.
 * @param {Object} req - Express request object.
 * @param {Object} res - Express response object.
 * @param {Function} next - Express next function (unused in this handler).
 */
function errorHandler(err, req, res, next) {
  // Determine the status code: use err.statusCode if available, otherwise default to 500.
  const statusCode = err.statusCode || 500;

  // Log the error with appropriate severity based on whether it's operational.
  if (err.isOperational === false) {
    // Non-operational errors are unexpected bugs — log full details for debugging.
    console.error('[ERROR]', err.message, err.stack);
  } else {
    // Operational errors are expected (e.g., client sent bad input) — log just the message.
    console.warn('[WARN]', err.message);
  }

  // Send a consistent JSON error response.
  res.status(statusCode).json({
    success: false,
    error: {
      message: err.message,
      // Only include stack trace in development to aid debugging; never in production.
      ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
    },
  });
}

// Export the middleware for use in server.js.
module.exports = errorHandler;
