## File 6: `src/routes/books.js` — Route Definitions

```javascript
/**
 * @fileoverview Express routes for book CRUD operations and statistics.
 *
 * WHY separate route file? Keeping routes in their own module improves
 * maintainability, testability, and readability. The main server.js stays lean
 * while this file owns all book-related endpoint logic.
 */

const express = require('express');
const router = express.Router(); // Create a standalone router instance.

// Import data-access functions from our storage layer.
const { getAllBooks, getBookById, createBook, updateBook, deleteBook, getStats } = require('../data/books');

// Import validation middleware.
const { validateCreateBook, validateUpdateBook } = require('../middleware/validation');

// Import custom error classes for throwing appropriate errors.
const { NotFoundError, ValidationError } = require('../utils/errors');

/**
 * GET /books — List all books with optional filtering.
 *
 * Query parameters supported:
 *   - genre: Filter by exact genre (case-insensitive).
 *   - minRating: Minimum rating (1-5).
 *   - maxYear: Maximum published year.
 *
 * Example: GET /books?genre=Fiction&minRating=4
 *
 * @returns {Array<Object>} Array of book objects matching the filters.
 */
router.get('/', (req, res) => {
  // Extract filter parameters from the query string; default to empty object if absent.
  const filters = {
    genre: req.query.genre,
    minRating: req.query.minRating,
    maxYear: req.query.maxYear,
  };

  // Call the data layer to retrieve filtered books.
  const result = getAllBooks(filters);

  // Respond with 200 OK and the array of books.
  res.status(200).json({
    success: true,
    count: result.length,
    data: result,
  });
});

/**
 * GET /books/:id — Get a single book by its ID.
 *
 * @param {number} params.id - The unique identifier of the book.
 * @returns {Object} The book object if found.
 * @throws {NotFoundError} If no book with the given ID exists.
 */
router.get('/:id', (req, res, next) => {
  const id = Number(req.params.id); // Convert string param to number for comparison.

  // Look up the book in our data store.
  const book = getBookById(id);

  if (!book) {
    // Throw NotFoundError; the global error handler will format the response.
    return next(new NotFoundError('Book', id));
  }

  res.status(200).json({
    success: true,
    data: book,
  });
});

/**
 * POST /books — Create a new book.
 *
 * Request body must include: title (string), author (string).
 * Optional fields: genre (string), publishedYear (number), rating (number).
 *
 * @returns {Object} The newly created book object.
 * @throws {ValidationError} If required fields are missing or invalid.
 */
router.post('/', validateCreateBook, (req, res) => {
  // Create the book using our data layer; validation middleware already ran.
  const newBook = createBook(req.body);

  // Respond with 201 Created and the new book in the response body.
  // 201 is the standard status for successful resource creation.
  res.status(201).json({
    success: true,
    data: newBook,
  });
});

/**
 * PUT /books/:id — Update an existing book by ID.
 *
 * All fields in the request body are optional (partial update supported).
 * Provided fields will overwrite existing values; omitted fields remain unchanged.
 *
 * @param {number} params.id - The unique identifier of the book to update.
 * @returns {Object} The updated book object.
 * @throws {NotFoundError} If no book with the given ID exists.
 */
router.put('/:id', validateUpdateBook, (req, res, next) => {
  const id = Number(req.params.id);

  // Check if the book exists before attempting update.
  const existingBook = getBookById(id);
  if (!existingBook) {
    return next(new NotFoundError('Book', id));
  }

  // Perform the update; only provided fields are changed.
  const updatedBook = updateBook(id, req.body);

  res.status(200).json({
    success: true,
    data: updatedBook,
  });
});

/**
 * DELETE /books/:id — Delete a book by ID.
 *
 * @param {number} params.id - The unique identifier of the book to delete.
 * @returns {null} No response body; only status code is returned.
 * @throws {NotFoundError} If no book with the given ID exists.
 */
router.delete('/:id', (req, res, next) => {
  const id = Number(req.params.id);

  // Check if the book exists before attempting deletion.
  const deleted = deleteBook(id);

  if (!deleted) {
    return next(new NotFoundError('Book', id));
  }

  // Respond with 204 No Content — standard for successful deletions with no body.
  res.status(204).send();
});

/**
 * GET /stats — Return aggregate statistics about the book collection.
 *
 * Statistics include: total books, average rating, most common genre, etc.
 *
 * @returns {Object} Statistics object.
 */
router.get('/stats', (req, res) => {
  const stats = getStats();

  res.status(200).json({
    success: true,
    data: stats,
  });
});

// Export the router so it can be mounted in server.js.
module.exports = router;
```

