## File 7: `src/server.js` — Application Entry Point

```javascript
/**
 * @fileoverview Main Express application setup and server startup.
 *
 * WHY this structure? We separate configuration, middleware registration, route
 * mounting, and server listening into clear sections for readability. Each part
 * is explained so learners understand the role of every line.
 */

const express = require('express');
const booksRouter = require('./routes/books');
const errorHandler = require('./middleware/errorHandler');

// Initialize Express application.
const app = express();

// ─────────────────────────────────────────────
// Middleware Configuration
// ─────────────────────────────────────────────

/**
 * express.json() — Parses incoming JSON request bodies.
 *
 * WHY needed? Without this middleware, req.body would be undefined for POST/PUT
 * requests with JSON payloads. This middleware extracts the JSON and populates
 * req.body as a JavaScript object, enabling our route handlers to access input data.
 */
app.use(express.json());

/**
 * Custom logging middleware — logs every request for debugging/monitoring.
 *
 * WHY add this? It's useful during development to see incoming requests, methods,
 * URLs, and response times. In production, you'd replace this with a proper logger
 * like Winston or Pino.
 */
app.use((req, res, next) => {
  const start = Date.now(); // Record request start time.

  // Attach an on('finish') listener to log after the response is sent.
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(
      `[${new Date().toISOString()}] ${req.method} ${req.url} → ${res.statusCode} (${duration}ms)`
    );
  });

  next(); // Proceed to the next middleware/route handler.
});

// ─────────────────────────────────────────────
// Route Mounting
// ─────────────────────────────────────────────

/**
 * Mount the books router at /books.
 *
 * WHY mount a router? It scopes all routes defined in books.js under the /books
 * prefix, keeping URL paths clean and organized. The router handles its own
 * middleware (validation) independently of the main app.
 */
app.use('/books', booksRouter);

// ─────────────────────────────────────────────
// Root Endpoint (Health Check)
// ─────────────────────────────────────────────

/**
 * GET / — Simple health check endpoint.
 *
 * WHY include this? It allows external monitoring tools or load balancers to
 * verify the server is running. Also useful for quick manual testing.
 */
app.get('/', (req, res) => {
  res.status(200).json({
    success: true,
    message: 'Book REST API is running',
    endpoints: {
      books: '/books',
      stats: '/books/stats',
    },
  });
});

// ─────────────────────────────────────────────
// Global Error-Handling Middleware
// ─────────────────────────────────────────────

/**
 * Register the global error handler as the LAST middleware.
 *
 * WHY last? Express processes middleware in order. If we placed this before routes,
 * it would intercept errors before they could be handled by route-specific logic.
 * By placing it at the end, we ensure all normal requests are processed first,
 * and any uncaught errors bubble up to this handler.
 */
app.use(errorHandler);

// ─────────────────────────────────────────────
// Server Startup
// ─────────────────────────────────────────────

const PORT = process.env.PORT || 3000; // Use env variable or default to 3000.

/**
 * Start the HTTP server and listen on the configured port.
 *
 * WHY wrap in a function? It keeps the startup logic encapsulated and allows
 * us to add error handling for the server itself (e.g., if the port is already in use).
 */
function startServer() {
  app.listen(PORT, () => {
    console.log(`📚 Book API running on http://localhost:${PORT}`);
    console.log(`   Try: GET http://localhost:${PORT}/books`);
  });
}

// Start the server.
startServer();

// Export the app for testing purposes (optional but recommended).
module.exports = app;
```

