## Arquivo 2: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================================
 *
 * POR QUE UM MIDDLEWARE DE ERRO?
 * --------------------------------
 * No Express, middlewares de erro são funções com 4 parâmetros (err, req, res, next).
 * Eles capturam erros lançados em rotas e middlewares anteriores, centralizando o
 * tratamento e garantindo que o cliente receba respostas consistentes.
 *
 * PADRÃO ADOTADO: Classe Error personalizada + middleware global.
 * Isso permite diferenciar erros de negócio (BadRequestError, NotFoundError) de
 * erros inesperados do sistema, retornando códigos HTTP apropriados para cada caso.
 */

// ----------------------------------------------------------------------------
// CLASSES DE ERRO PERSONALIZADAS
// ----------------------------------------------------------------------------
//
// POR QUE CLASSES DE ERRO?
// -------------------------
// Classes de erro personalizadas permitem:
// 1. Identificar o tipo de erro pelo nome da classe (instanceof)
// 2. Incluir metadados adicionais (como campos que falharam na validação)
// 3. Manter a stack trace para depuração
// 4. Separar claramente erros de negócio de erros técnicos
//
// Cada classe estende Error nativo e define um statusCode padrão, facilitando
// o mapeamento automático para respostas HTTP corretas.

/**
 * Erro genérico para requisições mal formadas ou com dados inválidos.
 * Corresponde ao código HTTP 400 (Bad Request).
 */
class BadRequestError extends Error {
  /**
   * @param {string} message - Descrição do erro
   * @param {*} data - Dados adicionais sobre o erro (ex: campos inválidos)
   */
  constructor(message, data = null) {
    super(message);
    this.name = 'BadRequestError';
    this.statusCode = 400;
    this.data = data;
  }
}

/**
 * Erro para recursos não encontrados.
 * Corresponde ao código HTTP 404 (Not Found).
 */
class NotFoundError extends Error {
  constructor(message) {
    super(message);
    this.name = 'NotFoundError';
    this.statusCode = 404;
  }
}

/**
 * Erro para recursos já existentes (violação de unicidade).
 * Corresponde ao código HTTP 409 (Conflict).
 */
class ConflictError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ConflictError';
    this.statusCode = 409;
  }
}

/**
 * Erro para recursos não autorizados.
 * Corresponde ao código HTTP 401 (Unauthorized).
 */
class UnauthorizedError extends Error {
  constructor(message) {
    super(message);
    this.name = 'UnauthorizedError';
    this.statusCode = 401;
  }
}

// ----------------------------------------------------------------------------
// FUNÇÃO DE RESPOSTA PADRÃO
// ----------------------------------------------------------------------------
//
// POR QUE UMA FUNÇÃO DE RESPOSTA?
// ---------------------------------
// Centralizar a formatação da resposta evita repetição de código e garante que
// todas as respostas sigam o mesmo formato JSON, facilitando o consumo pelo cliente.
// O formato inclui: status, mensagem, dados (opcional) e timestamp.

/**
 * Formata uma resposta HTTP padronizada.
 *
 * @param {import('express').Response} res - Objeto de resposta Express
 * @param {number} statusCode - Código HTTP da resposta
 * @param {string} message - Mensagem descritiva
 * @param {*} data - Dados a serem retornados (opcional)
 */
const sendResponse = (res, statusCode, message, data = null) => {
  res.status(statusCode).json({
    status: statusCode < 400 ? 'success' : 'error',
    message,
    ...(data !== null && { data }),
    timestamp: new Date().toISOString()
  });
};

// ----------------------------------------------------------------------------
// MIDDLEWARE DE TRATAMENTO DE ERROS
// ----------------------------------------------------------------------------
//
// POR QUE COLOCAR NO FINAL DA PILHA?
// ------------------------------------
// No Express, middlewares são executados em ordem FIFO. O middleware de erro
// deve ser o ÚLTIMO registrado para capturar erros de TODOS os middlewares e
// rotas anteriores. Se colocado no início, ele nunca seria alcançado após um
// erro, pois o Express pula para o próximo middleware de erro mais próximo.
//
// A verificação `err.statusCode` permite retornar o código HTTP correto baseado
// no tipo de erro personalizado. Erros sem statusCode conhecido recebem 500
// (Internal Server Error), que é o padrão seguro para erros inesperados.

/**
 * Middleware global de tratamento de erros.
 * Deve ser registrado por último na pilha de middlewares do Express.
 *
 * @param {Error} err - O erro capturado
 * @param {import('express').Request} req - Objeto de requisição
 * @param {import('express').Response} res - Objeto de resposta
 * @param {Function} next - Função next do Express (não usada aqui)
 */
const errorHandler = (err, req, res, next) => {
  // Log do erro para depuração no servidor
  console.error(`[ERROR] ${new Date().toISOString()} - ${err.name}: ${err.message}`);

  // Determina o código HTTP baseado no tipo de erro
  const statusCode = err.statusCode || 500;
  const message = err.message || 'Erro interno do servidor';

  // Para erros de validação com dados adicionais (ex: campos inválidos)
  if (err.name === 'BadRequestError' && err.data) {
    return sendResponse(res, statusCode, message, err.data);
  }

  // Para erros genéricos de servidor, não expomos detalhes ao cliente
  if (statusCode >= 500) {
    return sendResponse(res, 500, 'Ocorreu um erro interno no servidor.', null);
  }

  sendResponse(res, statusCode, message);
};

// ----------------------------------------------------------------------------
// EXPORTAÇÕES
// ----------------------------------------------------------------------------
module.exports = {
  BadRequestError,
  NotFoundError,
  ConflictError,
  UnauthorizedError,
  errorHandler,
  sendResponse
};
```

