## Arquivo 3: `src/services/bookService.js`

```javascript
/**
 * ============================================================================
 * SERVIÇO DE LIVROS — LÓGICA DE NEGÓCIO
 * ============================================================================
 *
 * POR QUE UMA CAMADA DE SERVIÇO?
 * --------------------------------
 * Separar a lógica de negócio das rotas HTTP segue o princípio de separação de
 * responsabilidades (SoC - Separation of Concerns). As rotas se preocupam apenas
 * com: receber requisição, chamar o serviço e enviar resposta. A lógica de
 * manipulação dos dados fica no serviço, tornando o código mais testável e
 * reutilizável.
 *
 * ESTRUTURA DE DADOS — Array em Memória:
 * ----------------------------------------
 * Cada livro é um objeto com a seguinte estrutura:
 * {
 *   id: number,          // Identificador único auto-incrementado
 *   title: string,       // Título do livro (obrigatório)
 *   author: string,      // Autor do livro (obrigatório)
 *   isbn: string,        // ISBN (opcional, mas recomendado)
 *   genre: string,       // Gênero literário
 *   publishedYear: number,// Ano de publicação
 *   createdAt: string,   // Timestamp ISO da criação
 *   updatedAt: string    // Timestamp ISO da última atualização
 * }
 *
 * POR QUE ARRAY?
 * - Simplicidade para fins educacionais
 * - Acesso O(1) por índice (para busca por ID com findIndex)
 * - Fácil de iterar para filtragem e estatísticas
 * - Em produção, substituiríamos por um banco de dados real
 */

// Importa as classes de erro personalizadas
const { BadRequestError, NotFoundError, ConflictError } = require('./middleware/errorHandler');

// ----------------------------------------------------------------------------
// ARMAZENAMENTO EM MEMÓRIA
// ----------------------------------------------------------------------------
//
// POR QUE UMA CONST COM LET PARA O ARRAY?
// -----------------------------------------
// Usamos `let` em vez de `const` porque o array será mutado (push, splice).
// O `const` impede reatribuição da variável, mas permite mutação do conteúdo.
//
// O `nextId` é um contador simples para gerar IDs únicos. Em produção, usaríamos
// UUIDs ou um banco de dados com auto-incremento.

/** Array que armazena todos os livros em memória */
let books = [];

/** Contador para gerar IDs únicos e sequenciais */
let nextId = 1;

// ----------------------------------------------------------------------------
// FUNÇÕES DE VALIDAÇÃO
// ----------------------------------------------------------------------------
//
// POR QUE VALIDAR ANTES DE PROCESSAR?
// -------------------------------------
// A validação antecipada (fail-fast) evita que dados inválidos entrem no
// armazenamento e garante que erros sejam reportados ao cliente antes de
// qualquer processamento desnecessário.
//
// Cada função de validação retorna um array de mensagens de erro, permitindo
// reportar múltiplos problemas de uma vez (ex: título e autor ausentes).

/**
 * Valida os dados obrigatórios para criação de um livro.
 *
 * @param {Object} bookData - Dados do livro a ser criado
 * @returns {string[]} Array de mensagens de erro (vazio se válido)
 */
const validateCreateBook = (bookData) => {
  const errors = [];

  // Verifica se o título foi fornecido e não é apenas whitespace
  if (!bookData.title || bookData.title.trim() === '') {
    errors.push('O campo "title" é obrigatório.');
  }

  // Verifica se o autor foi fornecido e não é apenas whitespace
  if (!bookData.author || bookData.author.trim() === '') {
    errors.push('O campo "author" é obrigatório.');
  }

  // Valida o ISBN se fornecido: deve ter 10 ou 13 dígitos
  if (bookData.isbn) {
    const isbnClean = bookData.isbn.replace(/[-\s]/g, '');
    if (!/^\d{10}(\d{3})?$/.test(isbnClean)) {
      errors.push('O ISBN deve conter 10 ou 13 dígitos numéricos.');
    }
  }

  // Valida o ano de publicação se fornecido
  if (bookData.publishedYear) {
    const year = parseInt(bookData.publishedYear, 10);
    const currentYear = new Date().getFullYear();
    if (isNaN(year) || year < 0 || year > currentYear + 1) {
      errors.push(`O ano de publicação deve ser um número entre 0 e ${currentYear + 1}.`);
    }
  }

  return errors;
};

/**
 * Valida os dados para atualização parcial de um livro.
 * Campos vazios são ignorados (atualização parcial permitida).
 *
 * @param {Object} updateData - Dados parciais para atualização
 * @returns {string[]} Array de mensagens de erro (vazio se válido)
 */
const validateUpdateBook = (updateData) => {
  const errors = [];

  // Só valida campos que foram efetivamente fornecidos
  if (updateData.title !== undefined && updateData.title.trim() === '') {
    errors.push('O campo "title" não pode ser vazio.');
  }

  if (updateData.author !== undefined && updateData.author.trim() === '') {
    errors.push('O campo "author" não pode ser vazio.');
  }

  if (updateData.isbn) {
    const isbnClean = updateData.isbn.replace(/[-\s]/g, '');
    if (!/^\d{10}(\d{3})?$/.test(isbnClean)) {
      errors.push('O ISBN deve conter 10 ou 13 dígitos numéricos.');
    }
  }

  return errors;
};

// ----------------------------------------------------------------------------
// OPERAÇÕES CRUD (Create, Read, Update, Delete)
// ----------------------------------------------------------------------------

/**
 * Cria um novo livro no armazenamento em memória.
 *
 * @param {Object} bookData - Dados do livro a ser criado
 * @returns {Object} O livro criado com id e timestamps
 * @throws {BadRequestError} Se os dados forem inválidos
 */
const createBook = (bookData) => {
  // Valida os dados antes de criar
  const validationErrors = validateCreateBook(bookData);
  if (validationErrors.length > 0) {
    throw new BadRequestError('Validação falhou', { errors: validationErrors });
  }

  // Cria o objeto livro com timestamps e ID único
  const now = new Date().toISOString();
  const book = {
    id: nextId++,
    title: bookData.title.trim(),
    author: bookData.author.trim(),
    isbn: bookData.isbn ? bookData.isbn.trim() : null,
    genre: bookData.genre ? bookData.genre.trim() : null,
    publishedYear: bookData.publishedYear ? parseInt(bookData.publishedYear, 10) : null,
    createdAt: now,
    updatedAt: now
  };

  // Adiciona ao array (operação O(1))
  books.push(book);

  return book;
};

/**
 * Lista todos os livros com suporte a filtragem opcional.
 *
 * PARÂMETROS DE FILTRAGEM (query string):
 * - author: filtra por autor (case-insensitive, partial match)
 * - genre: filtra por gênero (case-insensitive, partial match)
 * - search: busca por título ou autor (partial match)
 * - publishedYear: filtra por ano exato de publicação
 *
 * @param {Object} filters - Filtros aplicados à lista
 * @returns {Object[]} Array de livros filtrados
 */
const listBooks = (filters = {}) => {
  let result = [...books]; // Cria cópia para não mutar o array original

  // Filtra por autor (busca parcial, case-insensitive)
  if (filters.author) {
    const authorLower = filters.author.toLowerCase();
    result = result.filter(book => book.author.toLowerCase().includes(authorLower));
  }

  // Filtra por gênero
  if (filters.genre) {
    const genreLower = filters.genre.toLowerCase();
    result = result.filter(book => book.genre && book.genre.toLowerCase().includes(genreLower));
  }

  // Busca por título ou autor
  if (filters.search) {
    const searchLower = filters.search.toLowerCase();
    result = result.filter(book =>
      book.title.toLowerCase().includes(searchLower) ||
      book.author.toLowerCase().includes(searchLower)
    );
  }

  // Filtra por ano de publicação
  if (filters.publishedYear) {
    const year = parseInt(filters.publishedYear, 10);
    result = result.filter(book => book.publishedYear === year);
  }

  return result;
};

/**
 * Busca um livro pelo seu ID.
 *
 * @param {number} id - ID do livro a ser buscado
 * @returns {Object|null} O livro encontrado ou null se não existir
 */
const findBookById = (id) => {
  return books.find(book => book.id === id) || null;
};

/**
 * Busca um livro pelo ID ou lança erro 404 se não encontrado.
 * Usada nas rotas HTTP para garantir resposta adequada.
 *
 * @param {number} id - ID do livro
 * @returns {Object} O livro encontrado
 * @throws {NotFoundError} Se o livro não for encontrado
 */
const getBookById = (id) => {
  const book = findBookById(id);
  if (!book) {
    throw new NotFoundError(`Livro com ID ${id} não encontrado.`);
  }
  return book;
};

/**
 * Atualiza parcialmente um livro existente (PATCH semantics).
 * Apenas os campos fornecidos são atualizados.
 *
 * @param {number} id - ID do livro a ser atualizado
 * @param {Object} updateData - Campos a serem atualizados
 * @returns {Object} O livro atualizado
 * @throws {NotFoundError} Se o livro não existir
 * @throws {BadRequestError} Se os dados de atualização forem inválidos
 */
const updateBook = (id, updateData) => {
  // Encontra o índice do livro no array
  const index = books.findIndex(book => book.id === id);
  if (index === -1) {
    throw new NotFoundError(`Livro com ID ${id} não encontrado.`);
  }

  // Valida os dados de atualização
  const validationErrors = validateUpdateBook(updateData);
  if (validationErrors.length > 0) {
    throw new BadRequestError('Validação falhou', { errors: validationErrors });
  }

  // Atualiza apenas os campos fornecidos (atualização parcial)
  const allowedFields = ['title', 'author', 'isbn', 'genre', 'publishedYear'];
  for (const field of allowedFields) {
    if (updateData[field] !== undefined) {
      books[index][field] = updateData[field].trim();
    }
  }

  // Atualiza o timestamp de modificação
  books[index].updatedAt = new Date().toISOString();

  return books[index];
};

/**
 * Exclui um livro do armazenamento.
 *
 * @param {number} id - ID do livro a ser excluído
 * @returns {boolean} true se excluído, false se não encontrado
 * @throws {NotFoundError} Se o livro não existir
 */
const deleteBook = (id) => {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) {
    throw new NotFoundError(`Livro com ID ${id} não encontrado.`);
  }

  // splice remove o elemento e realinha os índices (O(n))
  books.splice(index, 1);
  return true;
};

/**
 * Calcula estatísticas sobre o acervo de livros.
 *
 * ESTATÍSTICAS RETORNADAS:
 * - totalBooks: número total de livros
 * - totalAuthors: número de autores únicos
 * - averagePublishedYear: ano médio de publicação (arredondado)
 * - booksByGenre: contagem de livros por gênero
 * - booksByDecade: contagem de livros por década de publicação
 * - oldestBook: livro mais antigo por ano de publicação
 * - newestBook: livro mais recente por ano de publicação
 *
 * @returns {Object} Estatísticas do acervo
 */
const getStats = () => {
  const totalBooks = books.length;

  // Se não há livros, retorna estatísticas zeradas
  if (totalBooks === 0) {
    return {
      totalBooks: 0,
      totalAuthors: 0,
      averagePublishedYear: null,
      booksByGenre: {},
      booksByDecade: {},
      oldestBook: null,
      newestBook: null
    };
  }

  // Calcula autores únicos usando Set (elimina duplicatas automaticamente)
  const uniqueAuthors = new Set(books.map(book => book.author.toLowerCase()));

  // Calcula a média dos anos de publicação (ignorando livros sem ano)
  const booksWithYear = books.filter(b => b.publishedYear !== null);
  const averagePublishedYear = booksWithYear.length > 0
    ? Math.round(booksWithYear.reduce((sum, b) => sum + b.publishedYear, 0) / booksWithYear.length)
    : null;

  // Contagem por gênero (ignora livros sem gênero)
  const booksByGenre = {};
  books.forEach(book => {
    if (book.genre) {
      booksByGenre[book.genre] = (booksByGenre[book.genre] || 0) + 1;
    }
  });

  // Contagem por década (ex: 2020 -> "2020s")
  const booksByDecade = {};
  booksWithYear.forEach(book => {
    const decade = Math.floor(book.publishedYear / 10) * 10;
    const decadeLabel = `${decade}s`;
    booksByDecade[decadeLabel] = (booksByDecade[decadeLabel] || 0) + 1;
  });

  // Encontra o livro mais antigo e mais recente por ano de publicação
  const sortedByYear = [...booksWithYear].sort((a, b) => a.publishedYear - b.publishedYear);
  const oldestBook = sortedByYear[0] || null;
  const newestBook = sortedByYear[sortedByYear.length - 1] || null;

  return {
    totalBooks,
    totalAuthors: uniqueAuthors.size,
    averagePublishedYear,
    booksByGenre,
    booksByDecade,
    oldestBook,
    newestBook
  };
};

// ----------------------------------------------------------------------------
// FUNÇÃO DE POPULAÇÃO INICIAL (DEMO)
// ----------------------------------------------------------------------------
//
// Popula o array com dados de exemplo para facilitar os testes iniciais.
// Em produção, esses dados viriam de um banco de dados.

/**
 * Popula o armazenamento com livros de exemplo para demonstração.
 */
const seedDatabase = () => {
  const demoBooks = [
    { title: 'Dom Casmurro', author: 'Machado de Assis', isbn: '9788594108', genre: 'Romance', publishedYear: 1899 },
    { title: 'Memórias Póstumas de Brás Cubas', author: 'Machado de Assis', isbn: '9788594109', genre: 'Romance', publishedYear: 1881 },
    { title: 'O Senhor dos Anéis', author: 'J.R.R. Tolkien', isbn: '9780261103', genre: 'Fantasia', publishedYear: 1954 },
    { title: '1984', author: 'George Orwell', isbn: '9780451524', genre: 'Distopia', publishedYear: 1949 },
    { title: 'Admirável Mundo Novo', author: 'Aldous Huxley', isbn: '9780060850', genre: 'Distopia', publishedYear: 1932 },
    { title: 'O Pequeno Príncipe', author: 'Antoine de Saint-Exupéry', isbn: '9780156012', genre: 'Fábula', publishedYear: 1943 },
    { title: 'Capitães da Areia', author: 'Jorge Amado', isbn: '9788573540', genre: 'Romance', publishedYear: 1937 },
    { title: 'Grande Sertão: Veredas', author: 'Guimarães Rosa', isbn: '9788571640', genre: 'Romance', publishedYear: 1956 }
  ];

  demoBooks.forEach(bookData => {
    books.push({
      id: nextId++,
      ...bookData,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    });
  });
};

// ----------------------------------------------------------------------------
// EXPORTAÇÕES
// ----------------------------------------------------------------------------
module.exports = {
  createBook,
  listBooks,
  getBookById,
  findBookById,
  updateBook,
  deleteBook,
  getStats,
  seedDatabase
};
