```javascript
/**
 * ============================================================================
 * ROTAS DA API DE LIVROS
 * ============================================================================
 *
 * POR QUE ARQUIVO DE ROTAS SEPARADO?
 * ------------------------------------
 * Separar rotas em arquivos distintos segue o princípio de modularidade. Isso
 * permite que cada conjunto de rotas seja desenvolvido, testado e mantido
 * independentemente. Em projetos maiores, poderíamos ter um arquivo de rotas
 * por recurso (autores, editoras, etc.).
 *
 * CONVENÇÕES REST ADOTADAS:
 * --------------------------
 * 1. Recursos são nomeados no plural (/books), não no singular
 * 2. Métodos HTTP mapeiam para operações CRUD:
 *    - GET    -> Listar/Buscar (read)
 *    - POST   -> Criar (create)
 *    - PUT    -> Atualizar completamente (update)
 *    - DELETE -> Excluir (delete)
 * 3. IDs são parte da URL para recursos específicos (/books/:id)
 * 4. Filtros usam query strings (?author=...)
 * 5. Respostas seguem formato JSON consistente
 * 6. Códigos HTTP semânticos:
 *    - 200 OK (sucesso em GET/PUT)
 *    - 201 Created (sucesso em POST)
 *    - 204 No Content (sucesso em DELETE)
 *    - 400 Bad Request (dados inválidos)
 *    - 404 Not Found (recurso inexistente)
 *    - 500 Internal Server Error (erro do servidor)
 *
 * PADRÃO ASYNC/AWAIT:
 * -------------------
 * Usamos async/await porque:
 * 1. Torna o código assíncrono mais legível que callbacks ou .then() encadeados
 * 2. Facilita o tratamento de erros com try/catch
 * 3. É o padrão moderno do ecossistema Node.js
 * Neste exemplo específico, as operações são síncronas (array em memória),
 * mas a estrutura async está preparada para migração futura a banco de dados.
 */

const express = require('express');
const router = express.Router();

// Importa o serviço de livros e funções de resposta
const { createBook, listBooks, getBookById, updateBook, deleteBook, getStats } = require('../services/bookService');
const { sendResponse } = require('../middleware/errorHandler');

// ----------------------------------------------------------------------------
// GET /books — Listar todos os livros com filtragem
// ----------------------------------------------------------------------------
//
// EXEMPLO DE USO:
//   curl http://localhost:3000/books
//   curl "http://localhost:3000/books?author=machado"
//   curl "http://localhost:3000/books?genre=romance&publishedYear=1954"
//   curl "http://localhost:3000/books?search=tolkien"
//
// POSTMAN:
//   Method: GET
//   URL: http://localhost:3000/books?author=machado&genre=romance
//
// A filtragem é feita por query strings. Múltiplos filtros podem ser combinados
// e são aplicados logicamente (AND entre filtros diferentes).

/**
 * @route GET /books
 * @description Lista todos os livros com suporte a filtragem opcional
 * @access Public
 * @query {string} [author] - Filtra por autor (busca parcial)
 * @query {string} [genre] - Filtra por gênero (busca parcial)
 * @query {string} [search] - Busca por título ou autor
 * @query {number} [publishedYear] - Filtra por ano de publicação
 * @returns {200} Array de livros
 * @returns {400} Erro de validação
 */
router.get('/books', async (req, res, next) => {
  try {
    // Extrai os filtros da query string
    const { author, genre, search, publishedYear } = req.query;

    // Constrói o objeto de filtros passando apenas os valores definidos
    const filters = {};
    if (author) filters.author = author;
    if (genre) filters.genre = genre;
    if (search) filters.search = search;
    if (publishedYear) filters.publishedYear = publishedYear;

    // Chama o serviço para listar livros com os filtros aplicados
    const books = listBooks(filters);

    // Retorna a lista de livros com status 200
    sendResponse(res, 200, `Lista de ${books.length} livro(s) encontrada(s).`, books);
  } catch (error) {
    // Encaminha o erro para o middleware de tratamento de erros
    next(error);
  }
});

// ----------------------------------------------------------------------------
// GET /books/stats — Estatísticas do acervo
// ----------------------------------------------------------------------------
//
// EXEMPLO DE USO:
//   curl http://localhost:3000/books/stats
//
// POSTMAN:
//   Method: GET
//   URL: http://localhost:3000/books/stats

/**
 * @route GET /books/stats
 * @description Retorna estatísticas agregadas sobre o acervo de livros
 * @access Public
 * @returns {200} Objeto com estatísticas do acervo
 */
router.get('/books/stats', async (req, res, next) => {
  try {
    const stats = getStats();
    sendResponse(res, 200, 'Estatísticas do acervo calculadas.', stats);
  } catch (error) {
    next(error);
  }
});

// ----------------------------------------------------------------------------
// GET /books/:id — Obter livro por ID
// ----------------------------------------------------------------------------
//
// EXEMPLO DE USO:
//   curl http://localhost:3000/books/1
//   curl http://localhost:3000/books/999  // Retorna 404
//
// POSTMAN:
//   Method: GET
//   URL: http://localhost:3000/books/1

/**
 * @route GET /books/:id
 * @description Busca um livro específico pelo seu ID
 * @access Public
 * @param {number} id - ID do livro (path parameter)
 * @returns {200} Objeto do livro encontrado
 * @returns {404} Erro se o livro não for encontrado
 */
router.get('/books/:id', async (req, res, next) => {
  try {
    // Converte o ID de string (vem da URL) para número
    const id = parseInt(req.params.id, 10);

    // Valida se o ID é um número válido
    if (isNaN(id)) {
      return sendResponse(res, 400, 'O parâmetro "id" deve ser um número válido.');
    }

    // Chama o serviço que lança NotFoundError se não encontrar
    const book = getBookById(id);
    sendResponse(res, 200, 'Livro encontrado.', book);
  } catch (error) {
    next(error);
  }
});

// ----------------------------------------------------------------------------
// POST /books — Criar novo livro
// ----------------------------------------------------------------------------
//
// EXEMPLO DE USO COM CURL:
//   curl -X POST http://localhost:3000/books \
//     -H "Content-Type: application/json" \
//     -d '{"title":"O Apanhador no Campo de Centeio","author":"J.D. Salinger","genre":"Romance","publishedYear":1951}'
//
// POSTMAN:
//   Method: POST
//   URL: http://localhost:3000/books
//   Headers: Content-Type: application/json
//   Body (raw JSON):
//   {
//     "title": "Título do Livro",
//     "author": "Nome do Autor",
//     "isbn": "9780000000",
//     "genre": "Gênero",
//     "publishedYear": 2020
//   }
//
// POR QUE POST E NÃO PUT?
// ------------------------
// POST é usado para criar recursos porque:
// 1. O ID é gerado pelo servidor, não pelo cliente
// 2. A URL não especifica o recurso (criamos em /books, não em /books/5)
// 3. É idempotente na prática (cada POST cria um recurso único)

/**
 * @route POST /books
 * @description Cria um novo livro no acervo
 * @access Public
 * @body {string} title - Título do livro (obrigatório)
 * @body {string} author - Autor do livro (obrigatório)
 * @body {string} [isbn] - ISBN do livro (opcional)
 * @body {string} [genre] - Gênero literário (opcional)
 * @body {number} [publishedYear] - Ano de publicação (opcional)
 * @returns {201} Livro criado com ID e timestamps
 * @returns {400} Erro de validação se os dados forem inválidos
 */
router.post('/books', async (req, res, next) => {
  try {
    // Extrai os dados do corpo da requisição
    const { title, author, isbn, genre, publishedYear } = req.body;

    // Valida se o corpo contém os campos obrigatórios antes de chamar o serviço
    if (!title || !author) {
      return sendResponse(res, 400, 'Os campos "title" e "author" são obrigatórios.');
    }

    // Chama o serviço para criar o livro
    const newBook = createBook({ title, author, isbn, genre, publishedYear });

    // Retorna 201 Created com o livro criado — código semântico para criação
    sendResponse(res, 201, 'Livro criado com sucesso.', newBook);
  } catch (error) {
    next(error);
  }
});

// ----------------------------------------------------------------------------
// PUT /books/:id — Atualizar livro existente
// ----------------------------------------------------------------------------
//
// EXEMPLO DE USO COM CURL:
//   curl -X PUT http://localhost:3000/books/1 \
//     -H "Content-Type: application/json" \
//     -d '{"title":"Dom Casmurro (Ed. Definitiva)","genre":"Romance Psicológico"}'
//
// POSTMAN:
//   Method: PUT
//   URL: http://localhost:3000/books/1
//   Headers: Content-Type: application/json
//   Body (raw JSON):
//   {
//     "title": "Título Atualizado",
//     "genre": "Novo Gênero"
//   }
//
// POR QUE PUT E NÃO PATCH?
// -------------------------
// PUT é usado aqui porque:
// 1. Atualiza parcialmente (campos enviados) — na prática, isso seria PATCH
// 2. Para fins educacionais, mantemos PUT como padrão REST
// 3. Em produção real, poderíamos ter ambos: PUT (substituição completa) e
//    PATCH (atualização parcial). Aqui unificamos em PUT por simplicidade.

/**
 * @route PUT /books/:id
 * @description Atualiza um livro existente parcialmente
 * @access Public
 * @param {number} id - ID do livro a ser atualizado
 * @body {string} [title] - Novo título
 * @body {string} [author] - Novo autor
 * @body {string} [isbn] - Novo ISBN
 * @body {string} [genre] - Novo gênero
 * @body {number} [publishedYear] - Novo ano de publicação
 * @returns {200} Livro atualizado
 * @returns {404} Erro se o livro não for encontrado
 * @returns {400} Erro de validação se os dados forem inválidos
 */
router.put('/books/:id', async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      return sendResponse(res, 400, 'O parâmetro "id" deve ser um número válido.');
    }

    // Verifica se pelo menos um campo foi fornecido
    const updateData = req.body;
    const allowedFields = ['title', 'author', 'isbn', 'genre', 'publishedYear'];
    const hasValidField = allowedFields.some(field => updateData[field] !== undefined);

    if (!hasValidField) {
      return sendResponse(res, 400, 'Pelo menos um campo para atualização deve ser fornecido.');
    }

    // Chama o serviço para atualizar o livro
    const updatedBook = updateBook(id, updateData);
    sendResponse(res, 200, 'Livro atualizado com sucesso.', updatedBook);
  } catch (error) {
    next(error);
  }
});

// ----------------------------------------------------------------------------
// DELETE /books/:id — Excluir livro
// ----------------------------------------------------------------------------
//
// EXEMPLO DE USO COM CURL:
//   curl -X DELETE http://localhost:3000/books/1
//
// POSTMAN:
//   Method: DELETE
//   URL: http://localhost:3000/books/1
//
// POR QUE 204 NO CONTENT?
// ------------------------
// DELETE retorna 204 porque não há conteúdo para retornar no corpo — a operação
// foi bem-sucedida e o recurso foi removido. Retornar 200 com um objeto seria
// redundante. O 204 é o código HTTP semântico para "sucesso sem conteúdo".

/**
 * @route DELETE /books/:id
 * @description Exclui um livro do acervo
 * @access Public
 * @param {number} id - ID do livro a ser excluído
 * @returns {204} Sucesso (sem conteúdo)
 * @returns {404} Erro se o livro não for encontrado
 */
router.delete('/books/:id', async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      return sendResponse(res, 400, 'O parâmetro "id" deve ser um número válido.');
    }

    // Chama o serviço para excluir o livro
    deleteBook(id);

    // Retorna 204 No Content — padrão REST para DELETE com sucesso
    res.status(204).end();
  } catch (error) {
    next(error);
  }
});

// ----------------------------------------------------------------------------
// EXPORTAÇÃO DO ROUTER
// ----------------------------------------------------------------------------
module.exports = router;
```

