## Arquivo 5: `src/app.js`

```javascript
/**
 * ============================================================================
 * APP PRINCIPAL — Ponto de entrada da API REST de Livros
 * ============================================================================
 *
 * ESTRUTURA DE MIDDLEWARES (ordem de execução):
 * ----------------------------------------------
 * 1. express.json()        -> Parseia o corpo das requisições JSON
 * 2. cors (opcional)       -> Habilita CORS para desenvolvimento
 * 3. logger                -> Log de cada requisição (debug)
 * 4. Rotas (/books, /stats) -> Manipulação das requisições
 * 5. 404 handler           -> Captura rotas inexistentes
 * 6. errorHandler          -> Captura e trata erros lançados
 *
 * POR QUE ESTA ORDEM?
 * --------------------
 * Middlewares de parsing (json()) devem vir antes das rotas para que req.body
 * esteja disponível quando as rotas forem executadas. O middleware de erro
 * deve ser o último para capturar erros de todos os middlewares anteriores.
 * O handler 404 vem antes do errorHandler porque é uma "resposta normal"
 * (não um erro lançado), então deve ser tratado como tal.
 */

const express = require('express');

// Importa o router de livros e o middleware de erro
const bookRoutes = require('./routes/books');
const { errorHandler } = require('./middleware/errorHandler');
const { seedDatabase } = require('./services/bookService');

// ----------------------------------------------------------------------------
// INICIALIZAÇÃO DO APP EXPRESS
// ----------------------------------------------------------------------------
const app = express();
const PORT = process.env.PORT || 3000;

// ----------------------------------------------------------------------------
// MIDDLEWARES GLOBAIS
// ----------------------------------------------------------------------------

/**
 * Middleware para parsear corpos de requisição JSON.
 * Limita o tamanho máximo a 10kb para evitar requisições maliciosamente grandes.
 */
app.use(express.json({ limit: '10kb' }));

/**
 * Middleware de logging simples para depuração.
 * Registra método, URL e timestamp de cada requisição.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next();
});

// ----------------------------------------------------------------------------
// ROTAS
// ----------------------------------------------------------------------------

/**
 * Rota raiz da API com mensagem de boas-vindas.
 */
app.get('/', (req, res) => {
  res.json({
    status: 'success',
    message: 'API de Livros REST — Example Educacional',
    endpoints: {
      'GET /books': 'Listar todos os livros (com filtragem opcional)',
      'GET /books/stats': 'Estatísticas do acervo',
      'GET /books/:id': 'Obter livro por ID',
      'POST /books': 'Criar novo livro',
      'PUT /books/:id': 'Atualizar livro existente',
      'DELETE /books/:id': 'Excluir livro'
    },
    version: '1.0.0'
  });
});

/**
 * Mount das rotas de livros no caminho /books.
 * Todas as rotas definidas em routes/books.js são acessíveis sob este prefixo.
 */
app.use('/books', bookRoutes);

// ----------------------------------------------------------------------------
// HANDLER PARA ROTAS NÃO ENCONTRADAS (404)
// ----------------------------------------------------------------------------
//
// POR QUE ESTE HANDLER ANTES DO ERROR HANDLER?
// ---------------------------------------------
// Um 404 de rota não é um erro lançado — é uma resposta intencional. Se
// colocássemos após o errorHandler, ele nunca seria alcançado porque o
// errorHandler captura tudo que vem depois. Colocado antes, ele responde
// diretamente sem passar pelo tratamento de erros.

app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: `Rota ${req.method} ${req.url} não encontrada.`,
    timestamp: new Date().toISOString()
  });
});

// ----------------------------------------------------------------------------
// MIDDLEWARE DE TRATAMENTO DE ERROS (SEMPRE POR ÚLTIMO)
// ----------------------------------------------------------------------------
app.use(errorHandler);

// ----------------------------------------------------------------------------
// INICIALIZAÇÃO DO SERVIDOR
// ----------------------------------------------------------------------------

/**
 * Inicia o servidor HTTP e popula o banco de dados com dados de exemplo.
 */
app.listen(PORT, () => {
  // Popula com livros de demonstração
  seedDatabase();

  console.log(`\n========================================`);
  console.log(`  API de Livros REST rodando na porta ${PORT}`);
  console.log(`  http://localhost:${PORT}`);
  console.log(`========================================\n`);
  console.log(`Endpoints disponíveis:`);
  console.log(`  GET    http://localhost:${PORT}/books`);
  console.log(`  GET    http://localhost:${PORT}/books/stats`);
  console.log(`  GET    http://localhost:${PORT}/books/:id`);
  console.log(`  POST   http://localhost:${PORT}/books`);
  console.log(`  PUT    http://localhost:${PORT}/books/:id`);
  console.log(`  DELETE http://localhost:${PORT}/books/:id\n`);
});

// ----------------------------------------------------------------------------
// EXPORTAÇÃO PARA TESTES
// ----------------------------------------------------------------------------
// Exportamos o app para que testes automatizados possam injetá-lo sem precisar
// iniciar um servidor HTTP separado.
module.exports = app;
```

